(window.ST=window.ST||{}).stories=[{"id":"donovan","name":"도노번","chapters":[{"id":"donovan_01","i":1,"title":"원조 레시피","req":"donovan:1","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"herbalist","t":"마리벨 약품 상점에 오신 것을 환영합니다! 어떻게 도와드릴까요?"},{"a":"donovan","t":"레이디 마리벨이셨죠? 개인적으로 당신의 최근 작품에 깊은 인상을 받았어요."},{"a":"donovan","t":"활력의 물약의 발명가로서 당신이 수정한 설계도는 천재라 해도 부족함이 없더군요!"},{"a":"donovan","t":"안개꼭대기 꽃을 살짝 추가하다니, 대단했어요!"},{"a":"herbalist","t":"잠깐... 그쪽이 그 도노번이란 말씀이세요? 말도 안 돼!"},{"a":"herbalist","t":"활력의 물약 설계도는 거의 700년도 전에 발명된 건데..."},{"a":"herbalist","t":"엘프라고 해도 150살 이상으로 보이지가 않는데요!"},{"a":"donovan","t":"친절하시군요, 레이디 마리벨."},{"a":"donovan","t":"제 설계도가 전부 상업적으로 이용 가능한 건 아니라고만 말해 두죠..."},{"a":"donovan","t":"하지만 당신 같은 뛰어난 연금술사라면 배우는 데 별 문제는 없을 것 같군요."},{"a":"donovan","t":"그러면 이제, 제가 한 번 그 안개꼭대기 꽃을 좀 봐도 괜찮을까요?"}]},{"id":"donovan_02","i":2,"title":"풍요의 땅","req":"donovan:2","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"donovan","t":"흥미롭군요... 이곳에서는 그 흔한 사과도 이토록 탐스럽다니요."},{"a":"donovan","t":"어떻게 이럴 수가 있죠...?"},{"a":"lilu","t":"설명할 사람이 있다면 그건 아마 주니퍼일 거예요!"},{"a":"lilu","t":"아, 죄송해요! 그 나무...와의 대화에 끼어들 생각은 아니었어요."},{"a":"donovan","t":"아, 챙이 넓은 모자를 쓰고 부엉이와 다니는 아가씨라면..."},{"a":"donovan","t":"당신은 분명 릴루 씨겠군요."},{"a":"lilu","t":"맞아요! 그리고 도노번 씨는 굳이 소개해주지 않으셔도 알겠네요!"},{"a":"donovan","t":"도시의 놀라운 어린 문하생에 대해 들었답니다. 만나서 반갑군요."},{"a":"donovan","t":"자, 릴루 씨. 아까 하려던 말이...?"},{"a":"lilu","t":"아 맞아요! 주니퍼는 마을 주변의 대지가 생명으로 넘쳐난다고 매일같이 얘기하고 다녀요."},{"a":"lilu","t":"그게 그렇게나 정원 일을 좋아하는 이유 중 하나라고 했어요."},{"a":"lilu","t":"어쨌든 전 오로라 동굴에 가던 중이었거든요, 만나서 반가웠어요 도노번 씨!"},{"a":"donovan","t":"곧 다시 만납시다."},{"a":"donovan","t":"흠... 어쩌면 이 아가씨가 뭔가 알고 있을지도..."},{"a":"donovan","t":"컨이... 고갈되고 있다고? 이 왕국의 모든 것이 더 활기차 보여."},{"a":"donovan","t":"그 정원사라는 사람에게 가 봐야겠군. 만약 여기 재료들이 더 강력하다면..."},{"a":"donovan","t":"... 나는 이걸 이용해야 할 거야."}]},{"id":"donovan_03","i":3,"title":"가면에 숨겨진 얼굴","req":"donovan:3","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"lilu","t":"절 찾으셨어요, 시아 씨?"},{"a":"sia","t":"아, 릴루. 갑자기 불렀는데 와줘서 고마워요."},{"a":"sia","t":"...이미 도노번을 만났다면서요?"},{"a":"lilu","t":"오, 네! 연금술사들 사이에서는 전설이시죠! 만날 수 있어서 기뻤어요!"},{"a":"sia","t":"그를 만날 땐 각별히 주의를 기울이세요."},{"a":"lilu","t":"ㄴ...네? 하지만 신사 같은 분인걸요! 아는 것도 많으시고..."},{"a":"sia","t":"보이는 게 다가 아닐 때가 있죠. 젊어 보이는 모습 뒤에는 천 년을 산 교활한 주모자가 있어요."},{"a":"lilu","t":"천 년이요? 엘프도 그렇게 오래 살지 않는데! 그럼 혹시..."},{"a":"sia","t":"네. 불멸의 엘릭서 같은 걸 찾은 것 같다고 하더군요."},{"a":"lilu","t":"와! 제 마법서에 그 레시피를 추가할 수 있다면 좋겠네요."},{"a":"sia","t":"수많은 지도자들도 그렇게 생각하겠죠. 컨의 황제가 꼭두각시 노릇을 해주고 있는 것 같아요."},{"a":"lilu","t":"...정치라는 건 참 복잡하군요."},{"a":"lilu","t":"어쨌든 감사해요! 조심할게요!"},{"a":"sia","t":"이해해줄 줄 알았어요."},{"a":"sia","t":"저는... 쉽게 휘둘리는 우리 폐하께서 그를 만나지 못하게 막을게요."},{"a":"lilu","t":"네... 그러는 게 좋을 것 같네요."}]},{"id":"donovan_a","i":3,"title":"10골드는 거저먹기","req":"donovan:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"행운의 토큰"},"side":true,"lines":[{"a":"leather","t":"저기요, 약물 양반. 잠깐 시간 돼요?"},{"a":"donovan","t":"윽... 방랑객이군."},{"a":"donovan","t":"어떻게... 도와드릴까요?"},{"a":"leather","t":"난 태마스예요. 가죽 장인이죠."},{"a":"leather","t":"멋진 불멸의 엘릭서를 만들 수 있다고 들었어요. 저도 한 병 주면 안 될까요?"},{"a":"donovan","t":"...그런 소문은 어디서 들으셨는지 모르겠군요."},{"a":"donovan","t":"설령 사실이라고 해도, 그렇게 귀한 걸 그냥 드릴 수는 없죠."},{"a":"leather","t":"10골드 드리죠."},{"a":"donovan","t":"절.대. 안 됩니다. 이 레시피를 차지하려고 전쟁도 났었다고요! 전 세계의 황제들이 맛만 보게 해달라고 빌빌 기는데!"},{"a":"leather","t":"흥정하기 어려운 상대네요. 15골드. 마지막 제안이에요."},{"a":"donovan","t":"가죽 냄새로 머리가 어떻게 된 거 아닙니까? 세계의 골드를 다 바친다고 해도 이 레시피는 못 줘요!"},{"a":"donovan","t":"가봐야겠어요. 다시는 절 찾아오지 마세요."},{"a":"leather","t":"젠장, 아깝게 놓쳤네."},{"a":"leather","t":"... 양들 줄 간식은 따로 찾아봐야겠군."}]}]},{"id":"king","name":"라인홀드","chapters":[{"id":"king_farewell","i":0,"title":null,"req":null,"reward":null,"side":false,"lines":[{"a":"sia","t":"라인홀드 폐하..."},{"a":"king","t":"아... 처리해야 할 업무가 내 발에 채는구나!"},{"a":"sia","t":"\"산더미처럼 쌓였다\"는 게 더 적합하겠습니다. 귀빈들께서 기다리십니다."},{"a":"king","t":"잘 있게나, 상인이여! 다시 돌아오겠다!"},{"a":"sia","t":"아뇨, 아마 못 오실 겁니다."}]},{"id":"king_01","i":1,"title":"왕의 법정","req":"king:1","reward":{"k":"tokens","id":"tokens","q":5,"n":"행운의 토큰"},"side":false,"lines":[{"a":"king","t":"왕의 법정을 열도록 하겠다! 탄원자는 앞으로 나오도록!"},{"a":"rudo","t":"흠."},{"a":"king","t":"라인홀드 왕국이 국민을 위해 무엇을 해주면 좋을지 말해보거라, 큰... 곰 인간?"},{"a":"rudo","t":"모든 마법을 금하고 주문술사를 쫓아내야 한다고 생각합니다."},{"a":"king","t":"오... 그건 좀... 음..."},{"a":"king","t":"자네의 제안을... 고려해보도록 하겠다! 다음!"},{"a":"herbs","t":"안녕하세요오! 저는 매일을 피냐타의 날로 지정해야 한다고 생각합니다!"},{"a":"king","t":"굉장히 좋은 생각이구나! 아니면 이참에..."},{"a":"sia","t":"..."},{"a":"king","t":"...이 내용에 관해 더 논의해봐도 좋을 것 같구나! 제안해주어 고맙다!"},{"a":"king","t":"...시아, 탄원자가 얼마나 더 남았지?"},{"a":"sia","t":"55명 남았습니다, 폐하."},{"a":"king","t":"이런."}]},{"id":"king_02","i":2,"title":"어리석은 황금의 심장","req":"king:2","reward":{"k":"tokens","id":"tokens","q":5,"n":"행운의 토큰"},"side":false,"lines":[{"a":"donovan","t":"실례합니다, 여기 자리 있나요?"},{"a":"sia","t":"지금 내 하루를 망치려는 거야, 도노번?"},{"a":"donovan","t":"방금 그 말은 상처야, 시아. 난 그저 황실의 국민끼리 인사를 건네려는 건데."},{"a":"donovan","t":"우리 어리석은 국왕 폐하께서는 어찌 지내시나?"},{"a":"sia","t":"염탐 실력이 점점 녹슬고 있나 보네, 도노번. 네 생각과 달리 라인홀드 폐하는 전혀 어리석지 않거든."},{"a":"sia","t":"늘 웃으시지만, 국민을 위해 많은 것을 희생하시지."},{"a":"sia","t":"그건... 우리의 황제께서도 본받을만한 점이야."},{"a":"sia","t":"지금까지 내 역할은 국왕 폐하가 국민을 위해 일하다가 자멸하지 않도록 막는 거였어."},{"a":"donovan","t":"그랬나? 흥미롭군."},{"a":"sia","t":"황금 같은 심장을 가진 바보일지는 모르지만, 과소평가하면 큰코다칠 거야."}]},{"id":"king_03","i":3,"title":"왕실 업무 이후 시간","req":"king:3","reward":{"k":"tokens","id":"tokens","q":5,"n":"행운의 토큰"},"side":false,"lines":[{"a":"king","t":"휴! 아무리 일해도 보고서가 줄지를 않는군, 안 그래?"},{"a":"sia","t":"오늘도 밤새도록 일하겠어."},{"a":"king","t":"날 도와주어 고맙네, 시아!"},{"a":"sia","t":"당연히 제가 할 일입니다, 폐하. 다음 보고로 넘어가겠습니다..."},{"a":"sia","t":"사우스버그의 농부들이 세금 일부를 미납하고 있습니다. 올해 농사가 흉작이었다는 이유를 들었군요."},{"a":"sia","t":"이번이 두 번째인 것으로 알고 있습니다만..."},{"a":"king","t":"왕실 마법사를 보내 상황을 파악하도록 하지. 누군가 그 땅을 저주했을지도 모르니."},{"a":"sia","t":"관대한 처사입니다."},{"a":"king","t":"그리고 이번에도 세금은 면제해 주도록. 아버지께서도 그리하셨을 거야!"},{"a":"sia","t":"알겠습니다. 분명 케이난 폐하께서도 이리하셨을 겁니다."},{"a":"king","t":"아버지가 남기고 가신 왕관의 무게가 느껴지는구나..."},{"a":"king","t":"다음 보고는 무엇인가?"},{"a":"sia","t":"다음 보고는 인접 제국과의 국경에서 긴장 상태가 이어지고 있다는 내용입니다..."}]},{"id":"king_04","i":4,"title":"그림자 보고 놀란 가슴","req":"king:4","reward":{"k":"tokens","id":"tokens","q":5,"n":"행운의 토큰"},"side":false,"lines":[{"a":"king","t":"..."},{"a":"sia","t":"폐ㅎ..."},{"a":"king","t":"으악!"},{"a":"king","t":"아니, 뒤에서 나타날 거면 미리 그 사실을 알리란 말이다!"},{"a":"sia","t":"아, 지난번 닌자 습격이 아직 마음에 남으셨나 보군요."},{"a":"king","t":"당연하지! 가까스로 목숨을 지켰단 말이다!"},{"a":"sia","t":"수비대 인원을 늘릴까요?"},{"a":"king","t":"그럴... 필요는 없다. 앞으로는 그렇게 조용히 다니지 말도록!"},{"a":"sia","t":"분부대로 하겠습니다, 폐하."},{"a":"hemma","t":"아, 역시 집에 오니... 응?"},{"a":"king","t":"아아!!! 닌자가?!"},{"a":"hemma","t":"이런, 실례했군요. 목적지를 잘못 설정했나 봅니다."},{"a":"hemma","t":"그림자 이동술을 쓰다 보면 가끔 이럴 때가 있죠."},{"a":"king","t":"내 알현실에서 그림자 이동술은 금지네!"},{"a":"sia","t":"라인홀드 폐하? 괜찮으세요?"},{"a":"king","t":"괜찮다! 어서 이... 방문객을 내보내게나."},{"a":"sia","t":"알겠습니다. 앞으로는 이런 침입이 일어나지 않도록 성의 보안을 강화하겠습니다."},{"a":"hemma","t":"꽤 흥미로운 좌표를 찾았군요. 다음에 또 보죠."},{"a":"king","t":"그건 사양하겠네!"}]}]},{"id":"rudo","name":"루도","chapters":[{"id":"rudo_01","i":1,"title":"리빙 마운틴","req":"rudo:1","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"argon","t":"으으으... 이렇게 추울 줄이야! 여기가 어디라고?"},{"a":"lilu","t":"이 보석들은 엄청난 가치가 있다고! 그리마르가 알려줬..."},{"a":"argon","t":"릴루, 기다려! 저것 봐! 누가 예티랑 싸우고 있는데!"},{"a":"lilu","t":"인간 맞나!? 몸집이 집채만 하군!"},{"a":"lilu","t":"예티를... 메다 꽂고 있잖아!?"},{"a":"rudo","t":"후우... 이걸로 열 마리로군."},{"a":"argon","t":"멋진 전투였소! 정말 대단하시더군!"},{"a":"rudo","t":"어?"},{"a":"lilu","t":"아니... 다쳤잖소! 내가 회복을 시켜드리지!"},{"a":"lilu","t":"<c1>회복-</c1>...!"},{"a":"rudo","t":"물러나!"},{"a":"rudo","t":"난 괜찮아. 내버려 두면 나아."},{"a":"rudo","t":"애들이 이런 데서 노는 게 아냐. 집으로 가라."},{"a":"argon","t":"마법을 진짜 싫어하시는 모양이군?"},{"a":"lilu","t":"아니. 눈빛에서 두려움이 느껴졌어..."}]},{"id":"rudo_02","i":2,"title":"퇴거 통지","req":"rudo:2","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"elderowen","t":"미안하지만 무슨 말인지..."},{"a":"rudo","t":"하! 그렇다면 우리 영감님들까지도 알아들을 수 있도록 쉽게 말해주지!"},{"a":"rudo","t":"이 도시의 마법사는 엄청난 미치광이이고 모두의 안전을 위해서 내쫓아야 한다는 말이야."},{"a":"elderowen","t":"아이고... 그런 매정한 말이라니..."},{"a":"rudo","t":"바로 어제, 그가 내게 티모세우스를 주시하라고 하더군..."},{"a":"rudo","t":"...\"팀\"이 망상에 가득 차 있고, 혼란스러워하고 있으며, 항상 누군가가 그를 감독하에 두어야 한다고 말이지."},{"a":"rudo","t":"하지만 자신이 바로 티모세우스였어!"},{"a":"elderowen","t":"흠, 그래, 그렇군."},{"a":"elderowen","t":"그의... \"상태\"에도 불구하고 티모세우스 그리마르는 이 도시에서 매우 중요한 역할을 하는 자일세."},{"a":"elderowen","t":"많은 도움을 주고, 그의 상태는 무해하네. 경계해야 한다고는 생각하지 않아."},{"a":"lilu","t":"마스터 그리마르를 내쫓는다니 그게 무슨 말이죠?"},{"a":"rudo","t":"넌 이 문제에서 빠져."},{"a":"lilu","t":"싫어요! 마스터 그리마르는 강력한 마법사지만, 누굴 해칠 사람은 아니에요!"},{"a":"rudo","t":"참 나! 좋아! 하지만 이 마을이 쑥대밭이 되는 날에 나한테 뭐라고 하기만 해."},{"a":"elderowen","t":"저 친구는 참 말썽꾼이구먼."},{"a":"lilu","t":"제가 지켜봐야겠어요..."}]},{"id":"rudo_03","i":3,"title":"스파크 태생","req":"rudo:3","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"priest","t":"실례지만... 뭘 그렇게 투덜거리시는 건가요?"},{"a":"rudo","t":"젠장. 이 도시에는 주문술사가 왜 이렇게 많은 건지..."},{"a":"priest","t":"아, 당신이 루도 님이시군요."},{"a":"rudo","t":"이봐 마법사 양반, 나한테 친절하게 굴 생각 하지 않는 게 좋아."},{"a":"priest","t":"저는 여신을 섬기는 여사제입니다. 제 힘은 마법사의 것과는 조금 다르죠."},{"a":"priest","t":"제 헌신의 일환으로 치유하고 보호하는 삶을 살 것을 맹세했습니다."},{"a":"rudo","t":"난 안 믿어. 스파크 태생들은 다 똑같아."},{"a":"priest","t":"스파크에 대해 아신다고요...?"},{"a":"rudo","t":"흥. 내가 한 말은 잊어. 이곳을 뜨든가 해야지."},{"a":"priest","t":"... 듣고 있었나요, 릴루?"},{"a":"lilu","t":"넵, 다 들었어요!"},{"a":"priest","t":"제가 스파크에 대해 가르쳐드린 것 기억하고 있죠?"},{"a":"lilu","t":"당연하죠! 스파크를 가지고 태어난 사람만이 마법 주문을 제어하고 만들 수 있다고 하셨잖아요."},{"a":"lilu","t":"하지만 이 사실은 일반 대중들에게 잘 알려지지 않았다고 알려주셨죠."},{"a":"priest","t":"맞아요! 역시 저의 우수생답군요!"},{"a":"priest","t":"하지만 그렇다면... 저자는 어떻게 알고 있는 걸까요...?"},{"a":"lilu","t":"흠... 혹시...?"}]},{"id":"rudo_04","i":4,"title":"부수고 훔치기","req":"rudo:4","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"polonia","t":"요호호! 폴로니아 선장이 이번에는 제대로 때렸다네!"},{"a":"polonia","t":"해적질하기 딱 좋은 왕의 무덤을 통째로 발견했다고!"},{"a":"rudo","t":"진정하시지, 뱃사람 씨. 난 바쁘다고."},{"a":"polonia","t":"아니면... 족쇄를 채운 광전사가 모든 녀석들에게 본때를 보여줄 수도 있지!"},{"a":"polonia","t":"데비 존스가 노하겠군! 도대체 문제가 뭐지, 친구? 그건 엄청난 금화의 값어치가 있는 거라고!"},{"a":"rudo","t":"아주 아주 오래됐고."},{"a":"rudo","t":"마법적이기까지 하고."},{"a":"rudo","t":"또 아마 저주가 걸려 있을 거야."},{"a":"rudo","t":"먼지가 되도록 박살내서 누군가의 문제를 해결해 주겠어."},{"a":"rudo","t":"만약 이 도시가 너무 멍청해서 문제를 보지 못한다면 내 손으로 직접 처리하지!"},{"a":"polonia","t":"오, 친구. 그 지팡이 정말 값나가게 생겼는걸. 설마 그걸..."},{"a":"rudo","t":"흠."},{"a":"rudo","t":"...이런."},{"a":"polonia","t":"크라켄 같으니라고! 무릎으로 그렇게 꺾지 마!"},{"a":"polonia","t":"...그런데 부러진 건 지팡이가 아닌 것 같군. 긁힌 자국 하나 없네!"},{"a":"polonia","t":"다리는 어떤가, 친구?"},{"a":"rudo","t":"괜찮은데. 하지만 지팡이가 보기보다 단단하군."},{"a":"rudo","t":"게다가 왠지 몰라도 손에서 놓을 수가 없어. 꼭... 풀로 붙인 것처럼."},{"a":"polonia","t":"난 배의 의사는 아니지만 보아하니 제대로 저주에 걸린 것 같구먼, 친구."},{"a":"polonia","t":"...한번 누구한테 보여주는 게 좋겠어."},{"a":"rudo","t":"당연히 그렇겠지. 항상 그렇지만 마법 저주 아니면 뭐겠어."},{"a":"rudo","t":"좋아. 난 이만 가야겠어. 나머지는 대신 부숴 줘."},{"a":"polonia","t":"알았네, 친구!"},{"a":"polonia","t":"...그보단 노략질에 가깝겠지만 말야, 왜냐면 이 해적님은 해적질을 할 거니까!"}]},{"id":"rudo_a","i":4,"title":"강인한 사랑","req":"rudo:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"행운의 토큰"},"side":true,"lines":[{"a":"herbs","t":"고르자!"},{"a":"gems","t":"고르자!<sprite tint=1 name=Note2>"},{"a":"wood","t":"안녕, 주니퍼. 메일리도! 잘 지내?"},{"a":"herbs","t":"나랑 메일리는 미래의 왕자님에 대해 얘기하고 있었어..."},{"a":"gems","t":"아, 정말 기대돼!"},{"a":"herbs","t":"...그래서 궁금해졌는데... 너흰 어떻게 만난 거야?"},{"a":"wood","t":"미련퉁이 바보 루도 말이야? 하!"},{"a":"wood","t":"그렇게 보이지는 않겠지만 루도는 여자랑 대화하는 법을 알고 있거든."},{"a":"wood","t":"보자... 이런 식이었어..."},{"a":"rudo","t":"...마지막으로 한 잔 더."},{"a":"tavern","t":"그래... 루도. 이제 정착할 생각은 없나?"},{"a":"rudo","t":"그쪽 일이나 신경 쓰시지, 나야. 그런 데 쓸 시간은 없다고."},{"a":"tavern","t":"사랑은 상상도 못한 순간에 나타나는 거지! 누가 알겠어, 꿈꿔오던 여자가 갑자기 나타날지..."},{"a":"rudo","t":"하! 날 땅에 메다꽂을 수 있는 여자가 아니면 정착할 일 없어!"},{"a":"wood","t":"지금 그거 도전인가, 덩치?"},{"a":"rudo","t":"덤벼 보시지!"},{"a":"tavern","t":"고르자, 의자는 내려놓고-"},{"a":"wood","t":"이건 어떠냐, 얼간이? 더 해볼래?"},{"a":"rudo","t":"으아아아아!!!"},{"a":"wood","t":"워우!"},{"a":"wood","t":"...그리고 일주일 뒤에 결혼했어. 내가 본 것 중 가장 피 튀기는 결혼이었지."},{"a":"herbs","t":"..."},{"a":"gems","t":"..."},{"a":"herbs","t":"...어, 어쩌면 다른 사람에게 물어봐야 될지도 모르겠다."}]},{"id":"rudo_05","i":5,"title":"저주와 폭발","req":"rudo:5","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"rudo","t":"부술 수 없다니, 그게 무슨 말이야!?"},{"a":"master","t":"말 그대로야. 이 사나운 친구야. 난 이 유물을 부술 수 없어."},{"a":"rudo","t":"이 하찮은 지팡이도 못 부수면 아다만티움 망치가 다 뭐야!"},{"a":"master","t":"그렇게 하찮은 지팡이가 아냐... 내 눈엔 꽤 사악해 보이는걸!"},{"a":"master","t":"어쨌든 뭔가 더 작용하고 있어. 아마 마법이겠지..."},{"a":"rudo","t":"당연히 그렇겠지."},{"a":"rudo","t":"항상 그렇지만 마법 저주 아니면 뭐겠어."},{"a":"master","t":"이미 잘 아시는 것 같네! 나 대신 이런 거에 조예가 깊은 사람에게 가보는 게 어때?"},{"a":"rudo","t":"마법사를 어떻게 믿어... 절대 안 돼."},{"a":"master","t":"흠, 이번에는 선택권이 없는 것 같은데."},{"a":"master","t":"그리고 그 귀여운 릴루를 어떻게 못 믿어? 그렇게 사랑스러운 아이를!"},{"a":"rudo","t":"걔도 마법사 맞지? 걔도 마찬가지라는 뜻이야."},{"a":"rudo","t":"위험하고 사악하고 야비할걸."},{"a":"master","t":"어쨌든 지팡이를 없애버리고 싶다면 도울 수 있는 건 그 애뿐인 것 같은데."},{"a":"rudo","t":"...망할."}]},{"id":"rudo_06","i":6,"title":"의도하지 않은 마법사","req":"rudo:6","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"rudo","t":"안녕, 나야. 늘 먹던 걸로."},{"a":"tavern","t":"루도, 미안하지만 무기는 못 가지고 들어와요. 규칙 알잖아요."},{"a":"rudo","t":"이거? 그냥 지팡인데."},{"a":"tavern","t":"속일 생각 하지 마세요! 한눈에 봐도 마법 지팡이인걸요!"},{"a":"rudo","t":"쳇. 좋아. 이거 보여? 저주받았어. 떨어지질 않는다고."},{"a":"tavern","t":"저런! 그렇다면 이번에는 특별히 봐드리죠. 루도니까 봐주는 거예요!"},{"a":"rudo","t":"흥. 고맙군."},{"a":"tavern","t":"그래서, 그거 어떻게 하려고요?"},{"a":"rudo","t":"신경 쓰지 마. 그냥 달고 살 거니까."},{"a":"tavern","t":"정말요? 그러면 짜증 내실 것 같은데요. 평소보다 더요. 그게 가능하다면 말이에요."},{"a":"tavern","t":"게다가 겉모습만 보면 다들 루도가 마법사라고 생각할걸요."},{"a":"rudo","t":"...정말? 망할 마법사로 보인다고?"},{"a":"tavern","t":"웃기게 생긴 모자만 쓰면 딱이겠어요! 그리고 좀 더 점잖게 굴면요!"},{"a":"rudo","t":"...그런 것 같군. 무슨 수를 써야겠어. 또 보자고."},{"a":"tavern","t":"좋은 하루 보내세요. 이건 외상으로 달아 둘게요!"}]},{"id":"rudo_07","i":7,"title":"트라우마의 그림자","req":"rudo:7","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"rudo","t":"아까는 미안했어. 내가 듣기로는 자네가... 이 저주를 도와줄 수 있다던데."},{"a":"lilu","t":"그 지팡이요? 꽤 끔찍한 저주 같네요!"},{"a":"lilu","t":"저주를 풀어 본 적은 없지만, 이론상으로는... 가능할 거예요."},{"a":"lilu","t":"준비된 건 맞죠? 많이 긴장한 것처럼 보여요."},{"a":"rudo","t":"...그래."},{"a":"lilu","t":"좋아요! 집중부터 할게요..."},{"a":"lilu","t":"저주가 보여요... 온몸을 감싸고 있어요."},{"a":"lilu","t":"잠시만요, 좀 더 파고들어 봐야겠어요..."},{"a":"rudo","t":"...으으!"},{"a":"lilu","t":"워우!"},{"a":"lilu","t":"방금 진짜, 진심으로 절 때리려던 것 같은데요!"},{"a":"rudo","t":"...미안하다. 일부러 그런 건 아니었어."},{"a":"lilu","t":"이 방법으론 안 되겠어요. 집중에 방해받으면 안 되거든요."},{"a":"rudo","t":"내 잘못이야. 다른 방법을 찾도록 하지."},{"a":"lilu","t":"맬러디한테 부탁해 보는 건 어때요? 제가 못 보는 걸 볼 수 있을지도 몰라요."},{"a":"rudo","t":"맬러디? 한번 가보지."},{"a":"lilu","t":"단, 상냥하게 대하세요! 맬러디한테... 특별한 사정이 있는데 그걸 알고 가셔야 해요..."}]},{"id":"rudo_08","i":8,"title":"둘을 위한 저주","req":"rudo:8","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"rudo","t":"맬러디 씨, 혹시 시간 있나?"},{"a":"malady","t":"(오 이런, 릴루가 이 사람 주의하라고 했는데...)"},{"a":"malady","t":"음... 죄송해요. 지금은 좀..."},{"a":"rudo","t":"미안, 겁을 주려는 건 아니었는데. 혹시 이 지팡이에 대해 뭔가 좀 아나 싶어서."},{"a":"malady","t":"그... 마법을 싫어하시는 거 아니었어요?"},{"a":"rudo","t":"세상에서 제일 싫어하신다고 들었는데."},{"a":"rudo","t":"저주받은 거 아닌가? 나도 똑같네."},{"a":"rudo","t":"자네가 마법을 선택한 게 아니잖아. 자네 잘못이 아니지."},{"a":"malady","t":"...그렇다면, 한 번... 지팡이랑 얘기를 해볼게요."},{"a":"malady","t":"..."},{"a":"malady","t":"...기생하는 것 같은데요. 루도 씨 스파크에 붙었어요."},{"a":"rudo","t":"지능이 있다고?"},{"a":"malady","t":"네... 어떤 면에서는요."},{"a":"malady","t":"스파크가 굉장히 강력하네요. 수십 년이 걸릴 수 있겠지만..."},{"a":"malady","t":"...어쩌면 마법에서 해방해 줄 수도 있지 않을까요...?"},{"a":"rudo","t":"허. 그렇게 될 것 같진 않은데."},{"a":"rudo","t":"그러니까 마법을 빨아먹을 게 필요한 것뿐이란 말이지?"},{"a":"malady","t":"음... 네. 그런 셈이죠."},{"a":"malady","t":"제발... 저는 이미 저주받았으니까..."},{"a":"rudo","t":"하! 그럴 생각은 추호도 없었네, 아가씨."},{"a":"rudo","t":"도와줘서 고맙네. 아이디어가 떠오른 것 같아..."}]},{"id":"rudo_09","i":9,"title":"병사의 과거","req":"rudo:9","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"malady","t":"저... 들어가도 될까요?"},{"a":"veteran","t":"아, 다들 그렇게 얘기하던 메두사로군."},{"a":"veteran","t":"들어와라, 애송이. 아쉽게도 네 키에 맞는 의자는 없어."},{"a":"malady","t":"괜찮아요... 감사합니다. 그 루도라는 분에 대해 궁금한 게 있어서요."},{"a":"veteran","t":"그 덩치 큰 멍청이? 혹시 널 괴롭히거나 그런 건 아니지?"},{"a":"malady","t":"아뇨... 저한텐 이상하게 친절했어요."},{"a":"veteran","t":"그래? 이상하군. 마법을 정말 싫어하는데."},{"a":"malady","t":"그래서 찾아온 거예요. 대체... 왜 그랬을까요?"},{"a":"veteran","t":"예전에 같이 제국의 군대에서 복무했지. 전쟁 친구랄까."},{"a":"veteran","t":"루도는... 어떤 실험에 '자원'하게 되었어. 병사의 몸에 스파크를 인공적으로 이식하는 실험이었지."},{"a":"veteran","t":"거기서 가혹한 일들이 벌어졌어. 그 뒤로 루도는 완전히 다른 사람이 됐고."},{"a":"malady","t":"끔찍하네요... "},{"a":"veteran","t":"실제로는 훨씬 끔찍했어. 우린 서둘러 거기서 빠져나왔지."},{"a":"malady","t":"그 실험이... 성공하긴 했나요? 몸 안에서 아주 강력한 스파크가 느껴졌거든요..."},{"a":"veteran","t":"뭐라 말하기 어렵군. 녀석 상태 봤잖아. 황제조차 루도한테 간단한 주문 하나 시키지 못했어."},{"a":"malady","t":"그리고 지금은... 그 일 때문에 끔찍한 저주에 시달리고 있고요... 도울 방법이 없을까요?"},{"a":"veteran","t":"널 찾아왔다면서? 녀석이 도움을 청한다는 건 좋은 징조야! "},{"a":"veteran","t":"똑똑하진 않아도, 끈질긴 친구거든. 분명 방법을 찾아낼 거다."}]},{"id":"rudo_10","i":10,"title":"소유권 이전","req":"rudo:10","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"rudo","t":"좋아, 이 고약한 젓가락 같으니. 거래를 하지."},{"a":"rudo","t":"저기 트러블린에게 널 넘겨주겠어."},{"a":"monster_Forest_Blacksmith","t":"으...으악! 날... 놔줘!"},{"a":"rudo","t":"둘이 절친이 된다면 이 모든 걸 없던 일로 해주지."},{"a":"rudo","t":"하지만 그러지 않겠다면..."},{"a":"rudo","t":"이 용암에 뛰어들어서 우리 둘 중 누가 더 오래 버티는지 보는 거야."},{"a":"rudo","t":"어느 쪽이냐? 이 '물'에 뛰어드는 것도 나쁘지 않은 것 같긴 하다만!"},{"a":"monster_Forest_Blacksmith","t":"..."},{"a":"rudo","t":"...좋은 선택이야. 잘 가지고 놀아 봐, 트러블린."},{"a":"monster_Forest_Blacksmith","t":"윽! 이거... 꼼짝도 안 하네!"},{"a":"rudo","t":"와하하하!!! 잘 있어라!"}]},{"id":"rudo_epilogue","i":11,"title":"에필로그","req":"rudo:11","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"lilu","t":"루도! 지난번 일 말인데..."},{"a":"rudo","t":"음?"},{"a":"lilu","t":"아! 지팡이를 없앴군!"},{"a":"rudo","t":"맞아, 걱정거리가 하나 줄었지."},{"a":"rudo","t":"...지난번 일은 미안해. 너무 예민했던 것 같아."},{"a":"lilu","t":"...용서해 줄게. 하지만 마법사에 대한 네 태도는 좀 고쳐야 할 것 같아!"},{"a":"rudo","t":"하! 그 맬러디는 예상외로 유용했어. 누가 알아, 언젠가 내 생각이 바뀔지도 모르지."},{"a":"lilu","t":"저주를 풀어줬어?"},{"a":"rudo","t":"꼭 그런 건 아닌데, 덕분에... 뜻밖의 도움을 받을 수 있었지."},{"a":"rudo","t":"도움은 언제든지 도움이 되는 법이지. 으하하!"},{"a":"argon","t":"애쉴리, 조심해! 다른 게 온다!"},{"a":"ashley","t":"난 뭐든 마주할 준비가 됐어! 와라, 괴물아!"},{"a":"monster_Forest_Blacksmith","t":"...도와줘..."},{"a":"argon","t":"음?"},{"a":"ashley","t":"어어?"}]}]},{"id":"lilu","name":"릴루","chapters":[{"id":"lilu_01","i":1,"title":"조숙한 수습생","req":"lilu:1","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"lilu","t":"어때, 폴럭스? 새로운 주문이 어떤 것 같아? 완벽하지?"},{"a":"lilu","t":"이번에는 정말 잘해냈다니까!"},{"a":"herbalist","t":"안녕하세요, 릴루. 이번 주에 사용할 살아있는 뿌리 때문에 오셨나요?"},{"a":"lilu","t":"네, 고마워요, 마리벨!"},{"a":"herbalist","t":"이번 주에는 정말 많은 양을 주문하셨네요! 마스터는 이 많은 양을 어디에 쓰시는 거예요?"},{"a":"lilu","t":"사실 이 중 반은 제가 사용할 거예요. 요즘 중요한 연구 중이거든요!"},{"a":"herbalist","t":"그래요? 어떤 연구 중인데요?"},{"a":"lilu","t":"치유 주문이요! 지난 주 내내 훈련소에서 찰과상과 멍을 치료했어요!"},{"a":"herbalist","t":"그랬군요, 당신이 주변에 있으면 영웅들도 든든할 거예요."},{"a":"herbalist","t":"...아르곤도요!"},{"a":"lilu","t":"...!"},{"a":"lilu","t":"어... 그만 가야겠네요! 고마워요!"}]},{"id":"lilu_02","i":2,"title":"암울한 소식","req":"lilu:2","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"lilu","t":"여기 있어요, 마스터 그리마르. 이번 주에 사용할 살아있는 뿌리예요."},{"a":"wizard","t":"고맙구나, 롤라. 여기 오늘 숙제다."},{"a":"lilu","t":"우와! 마법 서적이네요! 치유 마법이 적혀 있나요?"},{"a":"lilu","t":"악당의 저주 사용법...?"},{"a":"lilu","t":"이 책은 너무 수준이 높잖아요! 저주에 관한 부분까지 있어요!"},{"a":"wizard","t":"...저주?"},{"a":"wizard","t":"흠... 저주라...?"},{"a":"lilu","t":"마스터?"},{"a":"wizard","t":"35년 전 그날... 난...!"},{"a":"lilu","t":"마스터 그리마르!?"},{"a":"wizard","t":"...기억이 안 나는구나. 그런데 넌 누구니?"},{"a":"lilu","t":"...전 릴루예요, 사부님 제자요. 가끔 절 롤라라고 부르기도 하셔요..."},{"a":"lilu","t":"아니에요. 그냥 이 책을 공부할게요. 감사합니다."}]},{"id":"lilu_03","i":3,"title":"혼란한 마음","req":"lilu:3","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"lilu","t":"...그리고 은 가루 조금이면...됐다!"},{"a":"lilu","t":"빛나는 것 봐! 괜찮네, 안 그래 폴럭스?"},{"a":"lilu","t":"악당의 저주 사용법이라는 책이 맞다면 이 물약은.."},{"a":"wizard","t":"롤라, 이 난장판은 뭐냐? 잠 좀 자자!"},{"a":"lilu","t":"마스터 그리마르! 그 책 덕분에 엄청난 물약을 만들었어요! 이건.."},{"a":"wizard","t":"뭘 했다고!?"},{"a":"wizard","t":"그럼 내놔봐! 맛 좀 보자!"},{"a":"wizard","t":"..."},{"a":"lilu","t":"마스터 그리마르?"},{"a":"wizard","t":"릴루! 나 나나 나는 탈출해야 해! 이 머 멍청하고 얼빠진 정신에서 나가게 해줘!"},{"a":"lilu","t":"마스터 그리마르! 괜찮으세요?"},{"a":"wizard","t":"..."},{"a":"wizard","t":"꺼억! 약간 과일 향인데!"},{"a":"wizard","t":"나쁘지 않군 롤라. 그럼 마저 일하게."},{"a":"lilu","t":"...저건 정상이 아닌데."}]},{"id":"lilu_a","i":3,"title":"시대의 비축꾼","req":"lilu:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"행운의 토큰"},"side":true,"lines":[{"a":"lilu","t":"그리마르! <c1>컬렉션 책</c1>이 하나 더 있다는 말은 안 했잖아요!"},{"a":"wizard","t":"<c1>컬렉션 책</c1>...? 들어본 적이 있는 것 같은데..."},{"a":"lilu","t":"우와! 이 책에는 정보가 가득하잖아! <c1>다모클레스</c1>... <c1>불씨 성채</c1>..."},{"a":"lilu","t":"<c1>그리마르의 대 마법봉</c1>...? 직접 이름을 지으신 건가요?"},{"a":"lilu","t":"페이지가 정말 많네요! 아주 열정적인 수집가셨군요!"},{"a":"sundragon","t":"그랬고말고!"},{"a":"wizard","t":"내 오랜 친구 썬드라가 온 건가?"},{"a":"lilu","t":"우와! 두 분이 아는 사이인가요?"},{"a":"sundragon","t":"그럼. 어린 그리마르는 자신의 컬렉션 책에 흠뻑 빠져있었지."},{"a":"sundragon","t":"그 덕분에 인간 또래들 사이에서 아주 영예로운 호칭을 얻기도 했지. \"괴짜\"라고 했었나?"},{"a":"lilu","t":"아이고..."},{"a":"sundragon","t":"희귀한 아이템을 찾기 위한 여정을 하던 그를 만났고, 함께 <c1>융합 솥</c1>을 만들었지."},{"a":"sundragon","t":"그는 밤낮없이 수백 개의 아이템을 융합했고... 보름달이 뜰 때면 그 수는 더욱 많았어!"},{"a":"lilu","t":"정말 많은 노력을 들였군요... 하지만 그의 컬렉션은 아직 완성되지 않았어요!"},{"a":"lilu","t":"제가 반드시 치료해드릴게요, 마스터 그리마르! 인생을 바치신 업적을 완성해야죠!"},{"a":"sundragon","t":"시간이라는 건 인간에게 참 가혹하지. 여정에 행운이 있기를 빈다, 작은 아이야."}]},{"id":"lilu_04","i":4,"title":"혈통의 끝","req":"sia:3","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"lilu","t":"마스터 그리마르가 이상해..."},{"a":"lilu","t":"목소리가 마치 안에 다른 사람이 있는 것 같았어!"},{"a":"lilu","t":"복잡한 변신 주문이 아닐까?"},{"a":"lilu","t":"아니면.."},{"a":"leather","t":"형씨, 릴루! 왕의 만찬에서 무슨 일이 생겼대!"},{"a":"lilu","t":"태마스? 무슨 일이에요?"},{"a":"leather","t":"성에 침입자가 발생했대. 소름 끼쳐!"},{"a":"lilu","t":"침입자라고요...! 안 돼, 오늘은 아르곤의 기사 임무 첫 날인데!"},{"a":"lilu","t":"고마워요 태마스, 가봐야겠어요!"},{"a":"lilu","t":"세상에...! 무슨 일이지!?"},{"a":"lilu","t":"아르곤, 어디 있어!?"},{"a":"king","t":"아아악..."},{"a":"lilu","t":"라인홀드 폐하!? 괜찮으세요!?"},{"a":"king","t":"아아... 내 삶이... 스쳐 지나가는구나..."},{"a":"lilu","t":"이건 아니야...!"},{"a":"lilu","t":"집중해 릴루! 현자 훈련을 떠올려!"},{"a":"lilu","t":"라인홀드 폐하! 조금만 버티세요! <c1>회복</c1>!"},{"a":"king","t":"소용 없네... 제발... 내 아름다운 몸을 보존해주게..."},{"a":"lilu","t":"효과가 없어..."},{"a":"lilu","t":"안 돼... 이건 독인가?"},{"a":"lilu","t":"...부모님이랑 마찬가지야...! 이번엔 실패 안 해! 못 해!"},{"a":"lilu","t":"<c1>강력 해독!</c1>"},{"a":"king","t":"...아아아... 어?"},{"a":"lilu","t":"라인홀드 폐하! 좀 어떠세요?"},{"a":"lilu","t":"잠시만... 저 컵이 수리검을 막아줬네요! 다치지 않으셨어요!"},{"a":"king","t":"오! 그랬나? 내가 너무 오버한 모양이군."},{"a":"king","t":"군주의 죽음은 오버할 만한 일이긴 하죠."},{"a":"lilu","t":"아아! 라인홀드!"}]},{"id":"lilu_05","i":5,"title":"잃을 것만 남은 선택","req":"lilu:5","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"lilu","t":"윽... 큰일 날 뻔했네."},{"a":"lilu","t":"라인홀드가 정말 중독되었더라면... 난 그를 구할 수 없었을 거야."},{"a":"lilu","t":"다시 힘을 단련해야겠어. 나처럼 누군가가 소중한 사람을 잃지 않도록..."},{"a":"lilu","t":"시아 씨!"},{"a":"sia","t":"아, 오늘의 영웅이군요! 침입자를 잡기 위해 기사가 파견됐어요. 안심해도 됩니다."},{"a":"lilu","t":"(기사라면? 아르곤, 행운이 함께하길!)"},{"a":"sia","t":"여의치 않은 상황에도... 우리의 왕을 구해줘서 고마워요."},{"a":"lilu","t":"별거 아니었어요! 하지만 그런 일이 또 발생했을 때, 제가 도움이 될 수 있을지..."},{"a":"lilu","t":"시아 씨, 독에 대해 좀 아시나요?"},{"a":"sia","t":"물론이죠. 늑대의 골칫거리라고 불리는 아코닛은 매우 효율적인 살인 무기예요."},{"a":"sia","t":"하지만 개인적으로는 리신을 제일 좋아합니다. 조용히 치명적이고, 구하기도 쉽고..."},{"a":"lilu","t":"음... 해독하는 법은요?"},{"a":"sia","t":"아, 그건 별로 생각해본 적이 없네요."},{"a":"lilu","t":"... 괜히 물어봤네요."}]},{"id":"lilu_06","i":6,"title":"스승과 제자","req":"lilu:6","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"lilu","t":"마스터 그리마르, 제가 돌아왔어요!"},{"a":"wizard","t":"아, 롤라, 돌아온 걸 환영한다."},{"a":"lilu","t":"들으셨어요? 왕이 암살당할 뻔했어요!"},{"a":"wizard","t":"그렇구나..."},{"a":"lilu","t":"암살자가 난데없이 나타나서 수리검으로 그를 공격했다니까요!"},{"a":"lilu","t":"그러다 그가 죽어가는 걸 제가 서둘러 도우려는데...!"},{"a":"wizard","t":"그... 자네가 누구더라?"},{"a":"lilu","t":"아 맞다, 정신이 안 좋으셨지... 이것도 계속 알아봐야겠어!"},{"a":"lilu","t":"마찬가지로 독과 관련이 있을지도 모르니까..."},{"a":"lilu","t":"보자... 그리마르는 나이가 정말 많으니까..."},{"a":"lilu","t":"폴럭스, 어떻게 생각해?"},{"a":"lilu","t":"맞아, 사람들에게 물어보는 게 좋겠어!"},{"a":"lilu","t":"나이가 있는 주민들 중에 젊은 시절의 그리마르가 어땠는지 기억하는 사람이 있을지도 몰라..."}]},{"id":"lilu_07","i":7,"title":"고대의 지식","req":"lilu:7","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"lilu","t":"마스터 테오도르!"},{"a":"master","t":"릴루로군! 오늘은 뭘 도와줄까?"},{"a":"lilu","t":"마스터 그리마르가 어렸을 때 얘기 좀 해주실 수 있어요?"},{"a":"lilu","t":"...아, 그러니까... 마스터께서는 나이도 있고 경험도 많으시니까."},{"a":"master","t":"호호호! 물론, 그렇고 말고."},{"a":"master","t":"늙은 그리마르는 항상 조금... 뭐랄까, 괴짜 같았지."},{"a":"master","t":"하지만 내가 아직 꼬마였을 때는 지금보다 훨씬 날카로운 사람이었다. 체스 실력도 비슷했으니까."},{"a":"master","t":"그러다가 내가 생각하기로는 크로노스 유적에 다녀온 뒤로... 항상 기분이 좋지 않았어."},{"a":"lilu","t":"크로노스 유적! 정말 위험한 곳이잖아요!"},{"a":"lilu","t":"...시간 마법을 연구하다가 문명 자체가 폐허로 변해 버린 곳..."},{"a":"lilu","t":"마법 같은 이상 현상으로 가득한 곳이죠! 마스터 그리마르는 그런 곳에서 뭘 찾고 계셨던 걸까요?"},{"a":"lilu","t":"네가 맞아, 폴럭스. 이게 우리가 가진 유일한 실마리야. 조사해 봐야겠어!"},{"a":"lilu","t":"우릴 지켜 줄 사람이 필요한데... 아르곤한테 말해볼까...?"},{"a":"lilu","t":"아니다! 시간의 소용돌이가 갑자기 그 사람을 늙은이로 만들어버리면? 아니면 마스터 그리마르처럼..."},{"a":"lilu","t":"...우릴 도와줄 또 다른 사람은 한 명뿐이야..."},{"a":"lilu","t":"쉬운 일이 아니야, 폴럭스! 하지만 시도해 봐야해!"},{"a":"lilu","t":"고마워요, 마스터 테오도르! 큰 도움이 되었어요!"},{"a":"master","t":"천만에, 릴루! 또 보자!"},{"a":"master","t":"..."},{"a":"master","t":"...저 부엉이는 어떻게 저렇게 똑똑하지...?"}]},{"id":"lilu_08","i":8,"title":"공동의 목적","req":"lilu:8","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"lilu","t":"루도 씨, 제발요! 가지 마세요! 저랑 얘기 좀 해요!"},{"a":"rudo","t":"꺼져, 꼬마야. 듣고 싶지 않다."},{"a":"rudo","t":"부엉이 데리고 딴 데 가서 놀아!"},{"a":"lilu","t":"주문술사를 좋아하지 않으시는 거 알아요... 하지만 정말 도움이 필요해요!"},{"a":"lilu","t":"크로노스 유적 깊은 곳까지 가야 하는데 혼자서는 못 가요! "},{"a":"rudo","t":"빛나는 갑옷을 입은 네 아르곤 기사님께 부탁하지 그러냐?"},{"a":"lilu","t":"아르곤은... 지금 다른 일로 바빠요..."},{"a":"lilu","t":"당신한테는 부탁해도 소용이 없을 것 같네요..."},{"a":"rudo","t":"제대로 봤다, 꼬마야."},{"a":"tavern","t":"안타깝게 됐군."},{"a":"tavern","t":"크로노스 유적의 키클롭스 군주는 전투에서 패배한 적이 한 번도 없다고 들었어..."},{"a":"tavern","t":"릴루를 거기까지 데려가려면 아주 뛰어난 전사가 필요하겠지!"},{"a":"rudo","t":"...한 번도 패배한 적이 없다고?"},{"a":"rudo","t":"좋아, 말해봐. 부숴야 할 게 얼마나 되지?"},{"a":"lilu","t":"분명 많겠죠!"},{"a":"lilu","t":"음, 제가 할 일은 여러 크리스털에서 나오는 시간의 흐름의 원천을 찾아 분리하고-"},{"a":"rudo","t":"부수는 얘기로 바로 넘어가지."},{"a":"lilu","t":"...몬스터와 마법 크리스털을 부숴야 해요."},{"a":"rudo","t":"좋다, 하겠어. 나한테 하나 빚진 거다."},{"a":"lilu","t":"정말 잘됐네요! 정말 고마워요, 루도 씨!"},{"a":"rudo","t":"그 말은 여행이 끝날 때까지 아껴둬. 쉽지 않을 거다."},{"a":"lilu","t":"몬스터가 너무 많으면 제가 상처를 치유해드릴게요!"},{"a":"rudo","t":"흠, 어림없는 소리."},{"a":"lilu","t":"고마워요, 나야!"},{"a":"tavern","t":"별말을 다."}]},{"id":"lilu_09","i":9,"title":"거울 세계","req":"lilu:9","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"rudo","t":"내가 키클롭스를 상대할 테니 어서 가도록 해!"},{"a":"rudo","t":"덤벼라, 우둔한 놈들아! 한 방 제대로 먹여주마!"},{"a":"lilu","t":"알겠어요! 행운을 빌어요!"},{"a":"lilu","t":"여기가... 시간의 방이군요. 제 연구에 의하면..."},{"a":"lilu","t":"이 수반이 분열된 시간선과 이곳을 연결해주고 있을 거예요!"},{"a":"lilu","t":"크로노스 시티가 아직 번창하고 있는 평행우주의 세계 말이죠..."},{"a":"lilu","t":"폴럭스, 저길 봐! 물속을 자세히 보면... 뭔가 있어!"},{"a":"lilu","t":"저기 어딘가에는 크로노스의 사람들이 평범하게 살고 있는 모양이네..."},{"a":"lilu","t":"흠... 이 사람 우리한테 손 흔들고 있는 것 같지 않아?"},{"a":"lilu","t":"생긴 게 꼭... 그리마르!?"}]},{"id":"lilu_10a","i":10,"title":"영원의 저주","req":"lilu:10","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"lilu","t":"그리마르!!! 이걸 마셔요!"},{"a":"wizard","t":"음? 이거 뭔가... 익숙한 느낌이구나."},{"a":"lilu","t":"특수 물약이에요. 크로노스산 물을..."},{"a":"wizard","t":"... 안정화시켜서 운명의 실타래로 두 번 가공한 다음...?"},{"a":"lilu","t":"... 증류한 심령을 사용해 물질 형태로 만들어냈죠."},{"a":"wizard","t":"거기에 맛을 위해 심해의 산호를 약간 더했구나!"},{"a":"wizard","t":"아주 뛰어나구나, 릴루. 군계일학이 따로 없어."},{"a":"lilu","t":"ㄱ...그리마르... 원래대로 돌아왔군요! 성공했어!"},{"a":"wizard","t":"특이한 일이구나... 마치 머릿속의 안개가 걷힌 기분이야..."},{"a":"lilu","t":"물약이 어떻게 작용하는지는 대충 아는데... 말이 안 되는 게 있어요."},{"a":"lilu","t":"수반에서 그리마르를 봤어요! 평행 우주의 시간선에서요!"},{"a":"wizard","t":"허허! 그게 사실이냐? 그거라면 나름의 가설이 있지..."},{"a":"wizard","t":"폴럭스, 오웬을 데려와 주겠니? 설명해야 할 게 좀 많을 것 같구나..."}]},{"id":"lilu_10b","i":11,"title":"시간 균열 이론","req":"lilu:10","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"elderowen","t":"세상에, 친구여! 엄청난 이야기구만!"},{"a":"lilu","t":"저도 믿기지 않아요... 그리마르가 크로노스 시티의 생존자라니?"},{"a":"wizard","t":"시간의 주문이 잘못되고, 도시가 통째로 다른 시간선으로 던져졌단다."},{"a":"elderowen","t":"마치 어제 일처럼 생생하게 기억나. 도시 하나가 눈 깜짝할 사이에 사라졌지!"},{"a":"elderowen","t":"그 폐허에 남겨진 거라곤 홀로 떠도는 아이뿐이었어..."},{"a":"lilu","t":"그리마르죠? 두 분의 어릴 적이라니 상상도 안 되네요..."},{"a":"elderowen","t":"허허! 우린 금새 친해졌지, 안 그래?"},{"a":"wizard","t":"그랬지. 그 이후로 이 기묘한 일을 직접 알아볼 수 있는 마법사가 되기 위해 공부했단다."},{"a":"wizard","t":"릴루가 본 게 사실이라면, 또 다른 그리마르가 존재한다고 봐야겠지."},{"a":"lilu","t":"다른 그리마르라면... 다른 시간선에서 여전히 존재한다는 거예요!?"},{"a":"wizard","t":"그런 것 같구나. 처음에는 아무런 영향도 받지 않았지만..."},{"a":"wizard","t":"두 그리마르가 자라면서 우리의 인생 경험과 개성이 달라지기 시작한 거야."},{"a":"lilu","t":"그렇게 심해진 역설이 그리마르의 정신을 괴롭힌 거군요..."},{"a":"lilu","t":"아! 알았어요! 크로노스 유적에서 획득한 물약을 마시면 그 시간선과 다시 연결되는 건가 봐요!"},{"a":"wizard","t":"내 생각도 그렇단다. 다른 그리마르에게도 도움이 될 거야."},{"a":"lilu","t":"이야... 엄청난 이야기네요. 좀 쉬면서 더 생각해 봐야겠어요... 폴럭스, 가자."},{"a":"elderowen","t":"자, 그리마르. 우리 늙은이들끼리 해야 할 얘기가 참 많은 것 같은데!"},{"a":"wizard","t":"사돈 남 말 하는군, 할배! 난 그 어느 때보다 팔팔하다고!"}]},{"id":"lilu_epilogue","i":12,"title":"에필로그","req":"lilu:11","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"lilu","t":"안녕하세요, 그리마르! 새 레시피예요. 약효가 좀 더 오래 갈 거예요!"},{"a":"wizard","t":"놀라운 성과구나! 네 부모님이 보시면 참 자랑스러워하실 게다."},{"a":"lilu","t":"... 제가 연금술을 조금만 더 일찍 시작했더라면..."},{"a":"wizard","t":"나도 그런 생각을 한단다. 내 몸과 정신이 온전했더라면..."},{"a":"lilu","t":"... 괜찮아요. 미래에 집중하기로 했어요. 더 나은 사람이 되고, 우리의 운명으로부터 모두를 구할 거예요."},{"a":"lilu","t":"... 제 부모님도 그걸 바라셨을 거예요."},{"a":"wizard","t":"정말 많이 자랐구나... 몰라보겠어."},{"a":"wizard","t":"아니... 네가 누구더라?"},{"a":"lilu","t":"이런! 약효가 벌써 떨어지고 있잖아! 어서 가서..."},{"a":"wizard","t":"허허허! 농담이란다. 이 약은 느낌이 좋구나."},{"a":"wizard","t":"자 그럼, 내 정신이 온전한 김에 마법을 좀 배우는 건 어떻겠니?"},{"a":"wizard","t":"네 스승 아직 건재하다는 거 아니냐!"},{"a":"lilu","t":"오! 다형 변신은 어때요? 정말 기대되네요!"}]}]},{"id":"malady","name":"맬러디","chapters":[{"id":"malady_01","i":1,"title":"단단히 고정되다","req":"malady:1","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"argon","t":"퀘스트를 완료했습니다! 잃어버린 아이들을 찾아 구출했어요!"},{"a":"argon","t":"크로노스 유적은 그다지 안전한 놀이터가 아니었어요."},{"a":"argon","t":"저도 이제 나갈 길을 찾아야겠네요!"},{"a":"malady","t":"...오늘은 그 못된 트러블린들이 절 내버려두기를 바라요."},{"a":"argon","t":"거기 여성분, 안녕하세요! 길을 잃으셨나요?"},{"a":"malady","t":"더... 가까이 오지 마세요!"},{"a":"argon","t":"네?"},{"a":"argon_stone","t":"..."},{"a":"malady","t":"제 눈을 바라보면 영원히 돌이 돼요. 그게 메두사의 저주."},{"a":"malady","t":"그래도... 착한 사람 같았는데."},{"a":"malady","t":"...미안해요."}]},{"id":"malady_02","i":2,"title":"대리석의 그","req":"malady:2","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"lilu","t":"*끙끙*... 오웬... 장로님..."},{"a":"elderowen","t":"릴루! 뭘 하고 있는 건가? 왜 조각상을 끌고 다녀?"},{"a":"elderowen","t":"그 조각상은... 아르곤!?"},{"a":"lilu","t":"헉... 헉... 조각상이 바로 아르곤이에요!"},{"a":"elderowen","t":"오 이런. 석화된 모양이군?"},{"a":"lilu","t":"그런 것 같아요. 크로노스 유적에서 발견했을 때부터 이 상태였어요."},{"a":"lilu","t":"감사하게도 루도가 그를 운반하는 걸 조금 도와줬어요!"},{"a":"elderowen","t":"참 곤란하게 됐구나. 치유할 수 있겠니?"},{"a":"lilu","t":"아마도요! 근데 재료가 희귀해서, 쉽지는 않을 거예요."},{"a":"lilu","t":"시민들을 모을게요. 상인도요! 아르곤을 좀 맡아 주세요!"},{"a":"elderowen","t":"물론이지. 아르곤, 미안하지만 잠시만 내 정원의 장식품으로 있어줘야 겠구나."},{"a":"argon_stone","t":"..."},{"a":"elderowen","t":"오, 빌어먹을 비둘기! 훠이!"}]},{"id":"malady_03","i":3,"title":"눈에는 눈","req":"malady:3","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"lilu","t":"...이 과성장 줄기 정도면 충분히 오래된 것 같아. 이것도 몇 개 안 남았네..."},{"a":"lilu","t":"그 다음은... 메두사의 피. 쉽지 않겠군."},{"a":"malady","t":"음..."},{"a":"lilu","t":"으악! 괴물이다!"},{"a":"malady","t":"...혹시 아까 그 사람의 친구인가요?"},{"a":"lilu","t":"아르곤이요? 잠깐, 당신이 그런 거예요?"},{"a":"lilu","t":"와, 일이 훨씬 수월해졌네요. 안 그래도 메두사의 피가 필요했던 참이라..."},{"a":"malady","t":"안 돼! 제발요! 해칠 의도는 없었어요."},{"a":"lilu","t":"웃기시네! 돌로 만들었잖아요!"},{"a":"malady","t":"...미안해요. 저는 무서웠고, 그러다 눈이 마주쳤어요."},{"a":"malady","t":"어떻게 반응해야 할지 몰랐어요... 누가 저한테 친절하게 대해 준 적이 없어서요."},{"a":"lilu","t":"...아이고. 힘들었겠네요."},{"a":"malady","t":"피가 필요하다면... 드릴게요."},{"a":"malady","t":"대신, 부탁인데... 저를 데려가 주세요. 직접 사과하고 싶어요."},{"a":"lilu","t":"...알겠어요. 마음에는 안 들지만, 내가 돌로 변하면 도노번이 절 구하러 올 것 같진 않네요."},{"a":"lilu","t":"지켜볼 거예요. 하지만 당신은 눈길도 주면 안 돼요!"},{"a":"malady","t":"...그럴게요. 고마워요."}]},{"id":"malady_04","i":4,"title":"다시 피와 살이 되다","req":"malady:4","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"lilu","t":"다 됐어요! 이 물약이면 될 거예요. 얍!"},{"a":"argon","t":"...아아! 스트레칭하니까 기분이 좋네요!"},{"a":"argon","t":"잠깐, 어떻게 된 거죠?"},{"a":"lilu","t":"이 맬러디라는 친구가 실수로 돌로 변하게 했는데, 그 일을 사과하고 싶대요."},{"a":"malady","t":"아, 안녕하세요. 미안해요. 그러려는 게 아니었는데..."},{"a":"argon","t":"뭐, 괜찮아요! 기분 좋은데요! ...조금 뻐근하긴 하지만 말이죠."},{"a":"argon","t":"맬러디라고요? 저는 아르곤이에요. 만나서 반가워요!"},{"a":"argon","t":"어, 두건이 틀어졌네요. 고쳐드릴게요!"},{"a":"lilu","t":"아르곤! 안 돼!"},{"a":"argon_stone","t":"..."},{"a":"lilu","t":"아르곤... 메두사에 대해 가르쳐 주든가 해야지..."},{"a":"malady","t":"오 이런! 죄송해요!"},{"a":"lilu","t":"괜찮아요. 이건 쟤 잘못이니까요."},{"a":"malady","t":"피, 피 한 번 더 드릴 수 있는데..."},{"a":"lilu","t":"메두사 몸에 대해서 잘은 모르지만, 피는 며칠의 간격을 두고 뽑는 게 좋아요."},{"a":"lilu","t":"그동안은 여기 있어요. 약해진 상태에서 혼자 돌아다니는 건 위험해요."},{"a":"lilu","t":"생각해 보니 당신의... 힘이 뭔지 고려하면, 오웬 장로에게 먼저 물어봐야겠군요..."},{"a":"malady","t":"...네."}]},{"id":"malady_05","i":5,"title":"집에 온 걸 환영합니다.","req":"malady:5","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"lilu","t":"오웬 장로님, 저희 돌아왔어요!"},{"a":"elderowen","t":"아르곤이 치유됐다고? 좋은 소식이구나!"},{"a":"lilu","t":"그게... 아직은 아니에요. 하지만..."},{"a":"malady","t":"..."},{"a":"elderowen","t":"여, 여신이시여! 메두사가, 여기에!?"},{"a":"lilu","t":"맬러디예요. 아르곤을 치유하는 걸 도와줬어요!"},{"a":"lilu","t":"그를... 또 치유하려면 이곳에서 며칠 지내야 할 것 같아요."},{"a":"elderowen","t":"그... 그렇구나. 확실히 악의는 느껴지지 않는군. 무례하게 반응해서 미안합니다, 맬러디."},{"a":"malady","t":"제 저주 때문에... 모두가 절 싫어합니다. 같은 괴물들까지도요. 이런 건 익숙해요."},{"a":"elderowen","t":"도시의 문은 모두의 안녕을 위해 일하고자 하는 이들에게는 항상 열려 있네."},{"a":"malady","t":"...정말요?"},{"a":"elderowen","t":"눈만 계속 가려준다면야, 문제는 없어 보이네만."},{"a":"elderowen","t":"맬러디... 괴물들 사이에서보다 이곳에서 더 잘 지냈으면 좋겠군."},{"a":"malady","t":"감사합니다... 그 어떤 곳에서도 환영받은 적은 없었는데..."},{"a":"elderowen","t":"조만간 상인을 방문해 보는 게 좋겠어. 자네 같은 젊은 친구들에게는 일거리가 넘치는 곳이거든."},{"a":"lilu","t":"맞아요! 우리랑 퀘스트도 떠나고요!"},{"a":"malady","t":"그럴게요... 고마워요, 릴루와 오웬."}]}]},{"id":"bjorn","name":"비외른","chapters":[{"id":"bjorn_01","i":1,"title":"아빠의 집","req":"bjorn:1","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"bjorn","t":"얘들아! 아빠 왔다!"},{"a":"steel","t":"아빠!"},{"a":"wood","t":"...오셨어요."},{"a":"bjorn","t":"표정이 좋지 않구나. 무슨 일이니, 고르자?"},{"a":"wood","t":"몇 달씩이나 집을 비우셨잖아요!"},{"a":"bjorn","t":"그게 레인저의 삶이지 않니! 집을 떠나 탁 트인 바깥으로 나가는 것 말이다."},{"a":"wood","t":"칫. 좀 더 자주 집에 들르셔도 되잖아요."},{"a":"bjorn","t":"나도 그러고 싶지만, 신더레이크 화산 때문에 도통 틈이 안 나지 뭐냐!"},{"a":"wood","t":"화산이요? 브릭스파이어 피크를 조사한다고 하셨잖아요..."},{"a":"bjorn","t":"...내가 그랬나?"},{"a":"bjorn","t":"헷갈렸나 보구나! 핫핫!"},{"a":"bjorn","t":"어쨌든, 내가 너희들을 위해 기념품을 가져왔단다! 이리 와서 봐 보렴!"},{"a":"steel","t":"와! 크러시 인형이 있으면 좋겠네요!"}]},{"id":"bjorn_a","i":1,"title":"단짝 밴햄","req":"bjorn:1","reward":{"k":"tokens","id":"tokens","q":3,"n":"행운의 토큰"},"side":true,"lines":[{"a":"bjorn","t":"얘들아, 밴햄을 잠깐 돌봐주겠니?"},{"a":"wood","t":"저 기분 나쁜 멧돼지요? 절대 싫어요. 아빠가 데리고 있으세요."},{"a":"steel","t":"죄송하지만 아빠, 밴햄은 약간... 미친 것 같아요."},{"a":"bjorn","t":"에이, 그런 말 마렴! 밴햄이 얼마나 귀여운데!"},{"a":"wood","t":"아빠, 아빠가 저 녀석을 내려놓을 때마다 얼마나 미친 듯이 날뛰는데요."},{"a":"bjorn","t":"그땐 사고였어. 밴햄이 아주 쬐끔 흥분했을 뿐이야."},{"a":"wood","t":"그때 말고 다른 때는요?"},{"a":"bjorn","t":"그때도 다... 사고였어. 귀염둥이 밴햄은 파리 한 마리도 못 잡는다고!"},{"a":"wood","t":"잡을걸요. 그것도 아주 즐거워하면서요."},{"a":"wood","t":"아빠, 마을에 있을 때는 저 녀석을 데리고 다니는 게 훨씬 좋을 거예요."},{"a":"steel","t":"...모두의 안전을 위해서요."},{"a":"bjorn","t":"알겠다, 알겠어. 그렇게 하지. 상처받지 마, 밴햄. 난 널 사랑한단다."},{"a":"bjorn","t":"워워워! 얌전히 있어, 밴햄!"}]},{"id":"bjorn_02","i":2,"title":"비외른의 심부름","req":"bjorn:2","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"bjorn","t":"반갑게 맞아주셔서 감사합니다, 여러분! 돌아오니 좋군요!"},{"a":"elderowen","t":"자네가 무사히 돌아온 걸 보니 우리 모두 마음이 놓이는군. 자네가 몇 달씩이나 돌아오지 않으니 안 좋은 일이 생긴 건 아닌가 걱정했다네..."},{"a":"bjorn","t":"죄송해요, 죄송해요! 레인저의 삶이 그렇죠, 뭐! 핫핫!"},{"a":"oils","t":"보나 마나 또 다음 탐험을 떠날 생각을 하고 계시겠죠?"},{"a":"bjorn","t":"핫핫! 들켰군! 바로 내일 새벽에 떠날 예정이지!"},{"a":"oils","t":"여전하시군요, 비외른. 떠나 계시는 동안 브롬과 고르자를 잘 보살필게요."},{"a":"oils","t":"...만약 가시는 길이라면 야광 버섯 몇 개만 따다 주시겠어요?"},{"a":"bjorn","t":"물론이지! 힘든 일도 아닌데!"},{"a":"elderowen","t":"아... 난 요새 허리가 말썽이라서 말이야. 혹시 얼음 진주를 발견하게 된다면..."},{"a":"bjorn","t":"많이 돌아가는 길도 아닌데요. 찾아보도록 하죠, 장로님."},{"a":"engineer","t":"아! 비외른! 제 다음 실험에 필요한 러스트웜 비늘 좀 가져다주실 수 있나요? 무리가 아니라면요!"},{"a":"bjorn","t":"물론이지, 물론이야. 기억해 두지!"},{"a":"bjorn","t":"휴...! 가방이 몇 개 더 필요하겠어, 밴햄!"}]},{"id":"bjorn_03","i":3,"title":"버려진 건 모두 금이다","req":"bjorn:3","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"bjorn","t":"흠... 이 냄새가 너도 맡아져, 밴햄?"},{"a":"bjorn","t":"맞아, 금속이야. 아마도 버려진 걸 거야. 좋아, 밴햄. 찾아서 가져와!"},{"a":"bjorn","t":"잘했어, 어디 보자..."},{"a":"bjorn","t":"흠. 이상한 장치군. 누가 실수로 놓고 간 거 같지는 않은데..."},{"a":"bjorn","t":"이 크랭크를 조금 당기면..."},{"a":"bjorn","t":"흠... 좋아, 내 생각대로야."},{"a":"bjorn","t":"...부서졌군. 딱히 알아낸 건 없는 것 같군, 안 그래? 핫핫!"},{"a":"bjorn","t":"그래도 단서는 찾은 것 같아. 몇 달을 돌아다니고 있었는데 이건 저번에 없었어."},{"a":"bjorn","t":"돌아가서 전문가에게 맡기는 게 좋겠어. 난 기술이라면 젬병인 거 알잖아!"}]},{"id":"bjorn_04","i":4,"title":"미지의 비컨","req":"bjorn:4","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"engineer","t":"정말 이상한 장치네요! 이런 건 본 적이 없어요."},{"a":"engineer","t":"마법과 과학을 결합해서 비컨...? 아니면 레이더처럼 작동하는 것 같아요."},{"a":"engineer","t":"이걸 찾았을 때 부서져 있다고 하셨죠?"},{"a":"bjorn","t":"맞아. 참 운이 나빴지, 안 그런가? 핫핫!"},{"a":"engineer","t":"아깝네요. 확실히 말할 수 있는 건 하나뿐이군요. 이 장치는 어떤 정보를 보내고 있어요."},{"a":"engineer","t":"이렇게 하면 어때요? 제게 시간을 주시면 이... \"마법 비컨\"을 더 찾을 수 있는 장치를 만들어 드릴게요."},{"a":"bjorn","t":"좋지! 다시 거기로 갈 준비됐어, 밴햄?"},{"a":"bjorn","t":"이것들이 뭔지는 모르지만... 좋은 일에 쓰이는 것 같지는 않아."},{"a":"bjorn","t":"배후에 누가 있는지 우리가 찾아내야 해!"},{"a":"engineer","t":"행운을 빌어요! 그리고... 뭔지 모르는 기술을 다룰 땐 조심하세요!"}]}]},{"id":"atlab_sokka","name":"소카","chapters":[{"id":"atlab_sokka_01","i":1,"title":"위대한 전사 소카","req":"atlab_sokka:1","reward":{"k":"tokens","id":"tokens","q":5,"n":"행운의 토큰"},"side":false,"lines":[{"a":"atlab_aang","t":"그리고... 이건 어때!"},{"a":"tavern","t":"오, 귀여운 마술인데!"},{"a":"atlab_sokka","t":"윽, 항상 저걸 한다니까!"},{"a":"argon","t":"안녕, 네가 소카지? 나는 아르곤이야!"},{"a":"atlab_sokka","t":"오, 안녕. 벤딩 마술을 보고 싶으면 아앙을 찾아가."},{"a":"argon","t":"아, 아니야. 나는 마법은 잘 몰라. 벤딩도."},{"a":"argon","t":"네 장비를 보니 무시무시한 전사로 보이는데."},{"a":"atlab_sokka","t":"무, 무시무시한 전사?"},{"a":"atlab_sokka","t":"다, 당연하지! 난 아바타 팀의 위대한 전사, 소카야!"},{"a":"argon","t":"그럴 줄 알았어! 넌 엄청난 경험담이 많겠다!"},{"a":"atlab_sokka","t":"당연하지! 예를 들면 아그나 켈라의 포위전에서..."},{"a":"atlab_sokka","t":"그렇게 당시의 여자친구가 달이 됐지."},{"a":"argon","t":"다, 달이라고!?"},{"a":"atlab_sokka","t":"응. 근데 불의 제국 함대가..."},{"a":"atlab_sokka","t":"...그리고 쾅! 그 거대한 부엉이 인간을 도서관에서 쓰러뜨렸어."},{"a":"argon","t":"우와! 그 부엉이, 엄청 강한 정령 아니었어?"},{"a":"atlab_sokka","t":"맞아! 하지만 이 소카가 있는 한 아바타 팀은 언제나 승리하지!"},{"a":"atlab_sokka","t":"...그러고 보니 아앙은 어디 갔지?"},{"a":"argon","t":"아, 한 시간쯤 전에 갔어."},{"a":"atlab_sokka","t":"이런! 시간 가는 줄도 몰랐네. 미안, 아르곤. 가야겠어!"}]},{"id":"atlab_sokka_02","i":2,"title":"위대한 대장장이 소카","req":"atlab_sokka:2","reward":{"k":"tokens","id":"tokens","q":5,"n":"행운의 토큰"},"side":false,"lines":[{"a":"blacksmith","t":"열심히 일하는 중인가, 소카?"},{"a":"atlab_sokka","t":"안녕하세요, 월리스. 도구를 사용하는 걸 허락해 주셔서 고마워요!"},{"a":"blacksmith","t":"별것도 아닌걸! 이렇게 어리고 훌륭한 장인이라니, 놀라운데!"},{"a":"atlab_sokka","t":"무리에서 유일하게 벤딩 능력이 없다 보니 별 기술을 다 배우게 되거든요."},{"a":"atlab_sokka","t":"이렇게 좋은 도구는 정말 오랜만에 써 봐요..."},{"a":"atlab_sokka","t":"정비는 눈 깜짝하면 끝날 거예요!"},{"a":"blacksmith","t":"지금 갈고 있는 그 검... 어디서 구한 거야?"},{"a":"atlab_sokka","t":"이건 우주의 검이에요! 제가 직접 제련했어요!"},{"a":"blacksmith","t":"별의 금속? 나쁘지 않은데, 꼬마야!"},{"a":"blacksmith","t":"이 세상 검이 아니겠구나!"},{"a":"atlab_sokka","t":"그렇죠! 세상에서 유일한 검이에요!"},{"a":"polonia","t":"어어이! 방해해서 미안한데, 내 배를 수리해 줄 사람 없나?"},{"a":"polonia","t":"오늘 좀 상태가 안 좋아. 이상한 철공에 좀 맞고 해변에 정박했거든..."},{"a":"blacksmith","t":"엄청나게 힘들 것 같은데!"},{"a":"atlab_sokka","t":"문제없어요! 저는 물의 부족 출신인걸요! 제가 한번 볼게요. 미안해요, 월리스. 갈게요!"},{"a":"blacksmith","t":"그동안 네 다른 장비를 수리해주마. 행운을 빈다!"}]},{"id":"atlab_sokka_03","i":3,"title":"위대한 길잡이 소카","req":"atlab_sokka:3","reward":{"k":"tokens","id":"tokens","q":5,"n":"행운의 토큰"},"side":false,"lines":[{"a":"atlab_sokka","t":"이제 적어도 항구까지는 안전하게 갈 수 있을 거예요."},{"a":"polonia","t":"제대로 고쳐 줬네. 거의 새것이나 다름 없네!"},{"a":"atlab_sokka","t":"....배의 키가 유목이랑 제 옷 조각으로 버티고 있는데요?"},{"a":"atlab_sokka","t":"\"새것\"보다는, 소카 수리품인 거죠."},{"a":"polonia","t":"요호호! 근데 너 같은 풋내기가 어쩌다 배를 고치게 됐나?"},{"a":"atlab_sokka","t":"물의 부족민이라면 배랑 낚시는 필수죠. 걸음마를 배우기 전에 배 타는 법을 먼저 배웠어요."},{"a":"atlab_sokka","t":"최근에는 워터벤딩으로 움직이는 잠수함을 만들 계획도 세웠다고요!"},{"a":"polonia","t":"육지 말은 못 알아듣겠는데. 그게 뭐야?"},{"a":"atlab_sokka","t":"이게... 어, 물속으로 들어갈 수 있는 철로 된 배예요."},{"a":"polonia","t":"뱃사람을 예쁘게 포장해서 데비 존스한테 보내겠다는 말로 들리는데."},{"a":"engineer","t":"\"굉장히 위험하고, 테스트 안 해본 시제품\"이 있다는 거지?"},{"a":"atlab_sokka","t":"아... 그런 건.."},{"a":"engineer","t":"그거 마음에 드는데. 따라와, 신참."},{"a":"polonia","t":"요호호, 바다로 돌아갈 시간이야! 현상금 사냥꾼이 오기 전에 닻을 올려!"},{"a":"polonia","t":"음, 이번에는 그 떠다니는 철공을 피하는 게 좋겠어."}]},{"id":"atlab_sokka_04","i":4,"title":"위대한 발명가 소카","req":"atlab_sokka:4","reward":{"k":"tokens","id":"tokens","q":5,"n":"행운의 토큰"},"side":false,"lines":[{"a":"engineer","t":"멋진걸! 솔직히 설계도는 좀 엉성하지만..."},{"a":"engineer","t":"...그래도 조금만 손보면 이 잠수함 작동할 것 같아!"},{"a":"atlab_sokka","t":"천재적이죠? 그럴 줄 알았어!"},{"a":"atlab_sokka","t":"하지만 이게 워터벤더의 손으로 움직이도록 설계됐다는 걸 잊으면 안 돼요."},{"a":"engineer","t":"그런 자세한 건 괜찮아. 뭔가 방법이 있겠지."},{"a":"engineer","t":"생각해 봐! 이거면 가라앉은 사원을 탐험할 수 있을 거야!"},{"a":"atlab_sokka","t":"아, 근데 공기는 많이 안 들어가니, 금방 돌아와야 해요."},{"a":"atlab_sokka","t":"... 듣고 있어요?"},{"a":"engineer","t":"큰 철공에 기대지 마."},{"a":"atlab_sokka","t":"...네? 우워! 왜요?"},{"a":"engineer","t":"어뢰 시제품이야. 만지지 마. 폭발할 수도 있으니까."},{"a":"atlab_sokka","t":"...아."},{"a":"atlab_sokka","t":"뭐, 아무튼. 시제품이 어떻게 됐는지 말해줘."},{"a":"atlab_sokka","t":"그게 작동한다면... 나중에 쓸 데가 있으니까."}]}]},{"id":"sia","name":"시아","chapters":[{"id":"sia_01","i":1,"title":"왕의 첫 걸음","req":"sia:1","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"king","t":"시아! 결정했어!"},{"a":"sia","t":"네?"},{"a":"king","t":"오늘은 쇼핑을 갈 거야!"},{"a":"sia","t":"멋진 생각이십니다, 폐하."},{"a":"sia","t":"그런데 오늘 일정을 보니 외국 귀빈과의 만남이 있습니다..."},{"a":"king","t":"너무 따분해! 그냥 보내면 안 돼?"},{"a":"sia","t":"폐하는 아직 어리시지만, 여전히 왕이십니다. 폐하의 말은 곧 법이지요."},{"a":"king","t":"...맞는 말이야! 그럼 오늘은 쇼핑을 간다! 귀빈은 기다리라고 해!"},{"a":"sia","t":"존경할 만한 결단력이십니다. 저도 함께 갈까요?"},{"a":"king","t":"당연하지! 내 고귀한 몸을 믿고 맡길 사람은 시아뿐이라고."}]},{"id":"sia_02","i":2,"title":"하층민 친구","req":"sia:2","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"sia","t":"...왕의 신변이 위험하다는 징후가 있어요."},{"a":"elderowen","t":"그렇겠지. 왕이 죽으면 이득을 보는 라이벌 왕국이 있으니까."},{"a":"elderowen","t":"수상한 사람은 보지 못했지만, 여관의 나야라면 좀 더 아는 게 있을 거네."},{"a":"sia","t":"감사합니다, 장로님. 장로님의 지혜와 애국심에 감사드려요."},{"a":"elderowen","t":"아니네. 내가 사는 왕국의 번영을 위해 당연히 해야 할 일이지."},{"a":"elderowen","t":"라인홀드는 아직은 어리고 미숙하지만, 나이가 들면 좋은 왕이 될 것이네."},{"a":"sia","t":"그때까지 제가 지켜드려야죠!"},{"a":"tavern","t":"이런 여관에서 귀족을 보는 건 흔한 일이 아니죠!"},{"a":"sia","t":"그만해요, 나야. 내가 누군지 알잖아요."},{"a":"tavern","t":"물론이죠! 컨 황제가 우리 왕에게 선물로 준 시아 레오넬이잔하요..."},{"a":"tavern","t":"고문의 역할도 하지만, 왕을 감시하기도 하고요, 그렇죠?"},{"a":"sia","t":"...!"},{"a":"sia","t":"...참견하기 좋아하는 분이네요?"},{"a":"sia","t":"그럼 질문 하나만 하죠, 참견하기 좋아하는 나야..."},{"a":"sia","t":"근래에 여관에서 수상한 사람을 본 적이 있나요?"},{"a":"tavern","t":"오, 수상한 사람은 많이 봤죠! 취한 오크나 상점 주인이나..."},{"a":"tavern","t":"하지만 그중에서도 가장 수상한 건 저기 구석에 있는 여자예요."},{"a":"yami","t":"...!"},{"a":"sia","t":"도망쳤군..."},{"a":"sia","t":"아주마의 첩자였어요! ...암살자일 수도 있고요."},{"a":"sia","t":"경비를 늘려야겠네요..."}]},{"id":"sia_03","i":3,"title":"불청객","req":"sia:3","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"sia","t":"오늘은 폐하의 놀라운 너그러움을 축하하기 위해 모였습니다."},{"a":"sia","t":"지난 몇 달 간 왕께서는 수백 만 골드를 사비로 기부하셨습니다."},{"a":"sia","t":"...기부처는 지역 사원과 학교 및 고아원입니다."},{"a":"sia","t":"모든 분들은 오늘 연회에 초대되셨으니 가족과 친구들에게도 알리시기 바랍니다."},{"a":"sia","t":"라인홀드 왕 만세!"},{"a":"yami","t":"독재자 라인홀드, 오늘이 네 제삿날이다!"},{"a":"king","t":"아아악..."},{"a":"sia","t":"수리검...! 아주마의 첩자로군!"},{"a":"sia","t":"경비대! 성 주변에 경계선을 쳐라! 절대로 놓치지 마라!"},{"a":"sia","t":"아르곤, 저 놈을 쫒아!"},{"a":"argon","t":"지금 당장!"},{"a":"sia","t":"너! 지저분한 놈! 왕께서 다치셨다, 어서 치유사를 데려와!"},{"a":"leather","t":"와우, 무례하네요."},{"a":"sia","t":"(삼엄한 감시지만 진입로는 전부 파악했어...)"},{"a":"sia","t":"(...얘는 누구지?)"}]},{"id":"sia_04","i":4,"title":"검게 그을린 편지","req":"sia:4","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"sia","t":"참견쟁이 나야, 이떻게 된 일인지 설명해 봐."},{"a":"tavern","t":"아 리오넬 부인, 설명은 그 쪽에서 해주셔야겠는데요."},{"a":"sia","t":"뭐라고?"},{"a":"tavern","t":"아주 흥미로운 편지를 확보했습니다. 부인이 보낸 것 같더군요."},{"a":"tavern","t":"같이 읽어볼까요?"},{"a":"sia","t":"...!"},{"a":"tavern","t":"어디 보자... 컨의 봉인에 컨 황제 앞으로 되어 있군요?"},{"a":"tavern","t":"이런, 스캔들을 일으킬 불륜 이야기를 기대했는데, 뭐 반역도 괜찮겠네요."},{"a":"sia","t":"나 나야, 제발 그만해!"},{"a":"tavern","t":"오! 여기 재미있는 부분이 있네요!"},{"a":"tavern","t":"\"라인홀드 왕은 왕좌에 앉아있는 것만으로 이쪽에 엄청난 도움이 되는 바보니까요.\""},{"a":"tavern","t":"\"놈을 살려두는 게 죽이는 것보다 더 큰 피해를 왕국에 안겨줄 겁니다.\""},{"a":"sia","t":"..."},{"a":"tavern","t":"이런 망언을 했으니 조언자 자리는 내려 놓으셔야겠는데요!"},{"a":"sia","t":"참견을 좋아하는... 나야... 반드시 복수해주마!"},{"a":"tavern","t":"뭐 언젠가는요. 하지만 지금 대가를 치를 건 제가 아닌 것 같네요."},{"a":"sia","t":"협박까지 할 정도로 형편없는 인간이 된 거야?"},{"a":"tavern","t":"반역에 비하면 협박은 가벼운 죄죠!"},{"a":"tavern","t":"그리고 폐하를 해칠 생각이었다면..."},{"a":"sia","t":"흠, 그래 좋아. 원하는 대가를 말해. 그리고 내 스파이 부하들이 네 부하들보다 뛰어나게 되지 않길 기도해."},{"a":"tavern","t":"기대하고 있을게요!"}]},{"id":"sia_a","i":4,"title":"왕의 카프리스","req":"sia:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"행운의 토큰"},"side":true,"lines":[{"a":"sia","t":"폐하."},{"a":"king","t":"시아! 무슨 일로 왔는가?"},{"a":"sia","t":"최근에 혹시라도 \"변덕\"이 폭발한 적이 있습니까?"},{"a":"king","t":"그, 그럴 리가! 당연히 아니지! 내가 왜 그러겠어!"},{"a":"sia","t":"이상하군요. 장부를 보니 36번 금고에 <c1>비도</c1>가 가득한데요."},{"a":"sia","t":"이것이 아주 희귀한 아이템이라는 걸 폐하께 상기시켜드릴 필요는 없겠지요."},{"a":"king","t":"내, 내 생각에는 완벽한-"},{"a":"sia","t":"게다가 왕국에서 가장 희귀한 골동품 다수가 일반인의 손에서 목격되었습니다."},{"a":"sia","t":"폐하의 자비로움은 인정받아 마땅합니다..."},{"a":"sia","t":"...하지만 기분에 따라 값비싼 유물을 나누어주는 것은 자제해주시기 바랍니다."},{"a":"king","t":"흠. 잘 알겠네! 오늘부터 달라지겠어!"},{"a":"sia","t":"이해해주셔서 감사합니다. 이만 가보겠습니다."},{"a":"king","t":"의지가 약해질 일은 없어! 짐은 물질적인 건 필요 없다고!"},{"a":"king","t":"...이 방에 <c1>리걸 칼날</c1>을 몇 개 두면 좋을 것 같은데. 안 그런가?"}]},{"id":"sia_05","i":5,"title":"스완 요원","req":"sia:5","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"sia","t":"... 갑자기 뒤바뀐 상황에서, 라인홀드 왕에 대한 암살 시도가 있었습니다."},{"a":"sia","t":"아주마 쪽이 배후에 있는 듯합니다. 스완 요원이 계속 조사하겠습니다."},{"a":"king","t":"시아! 뭘 하고 있는 건가?"},{"a":"sia","t":"그저 편지를 쓰고 있습니다. 신경 쓰지 마십시오."},{"a":"sia","t":"(컨의 황제에게 쓰는 것이긴 하지만...)"},{"a":"king","t":"알겠네! 지금 몇몇 해외 대신들이 날 기다리고 있네."},{"a":"king","t":"지난 쇼핑 외출 때문에 조금... 기분이 상해있을 수도 있어."},{"a":"king","t":"이 상황을 진정시키는 데 네가 도와준다면 참 좋겠구나!"},{"a":"sia","t":"물론입니다. 곧 따라가겠습니다, 폐하."},{"a":"sia","t":"이 암살 시도를 컨의 황제에게 알리면 심각한 일들이 일어날 수도 있어..."},{"a":"sia","t":"생각을... 좀 더 해봐야겠어. 이 왕국은 아직... 컨을 상대하기엔 무리야."},{"a":"sia","t":"모두의 안전을 위해... 이 사실은 굳이 보고하지 않아도 될 것 같기도 하고..."},{"a":"sia","t":"모두 계획대로 진행되고 있습니다. 이번 달 스완 요원이 보고해야 할 내용은 없습니다."}]},{"id":"sia_06","i":6,"title":"장미와 가시","req":"sia:6","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"king","t":"시아! 그대를 위한 방문객이 왔노라! 실로 고귀한 친구라 할 수 있지."},{"a":"sia","t":"...왕이시여, 고귀하다고요? 설마..."},{"a":"donovan","t":"레이디 시아."},{"a":"sia","t":"...도노번."},{"a":"sia","t":"왕이시여, 재무부에 긴급한 사안이 있다 합니다. 즉시 가서 보시지요."},{"a":"king","t":"오, 최신 순금 배송이 도착했나? 어서 가 봐야겠군!"},{"a":"donovan","t":"이 왕은 변함없는 바보로군요. 그렇지 않습니까?"},{"a":"sia","t":"무슨 더러운 일로 라인홀드의 왕국에 온 거지, 연금술사?"},{"a":"donovan","t":"항상 말을 돌리는 법이 없으시네요, 스완 요원."},{"a":"donovan","t":"그저 개인 휴가차 온 것 뿐입니다. 물론 컨 황제의 승인 하에 말이죠."},{"a":"donovan","t":"꽃 향기를 맡고, 물약 맛을 보고... 연금술사의 휴가란 게 이렇죠."},{"a":"sia","t":"하고 많은 곳 중에 여기로 왔다는 거야?"},{"a":"donovan","t":"거꾸로 가는 이 왕국에 노련한 연금술사를 위한 몫이 좀 있지 않을까 싶었거든요."},{"a":"donovan","t":"...비록 스완의 충성심은 갈팡질팡하지만 말입니다..."},{"a":"sia","t":"하고 싶은 말은 다 했나 본데, 도노번. 가서 그... 휴가나 즐겨."},{"a":"donovan","t":"원하시는 대로, 레이디 시아. 언제나처럼 즐거운 대화였답니다."},{"a":"sia","t":"...골칫거리가 또 하나 늘었군."}]},{"id":"sia_07","i":7,"title":"황금의 도시에 온 이방인","req":"sia:7","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"sia","t":"도노번? 제가 첩자질을 방해하는 게 아니어야 할 텐데요..."},{"a":"donovan","t":"오! 레이디 시아!"},{"a":"donovan","t":"전혀 아닙니다! 그냥 둘러보고 있었어요."},{"a":"sia","t":"그렇게 숨기지 않아도 돼요. 사라진 황금의 도시는 모두를 환영하니까요."},{"a":"sia","t":"하지만 왕국의 법에 따라 왕국 내부에서 발견되는 모든 <c1>순금</c1>은 라인홀드 왕에게 귀속된다는 것을 명심하세요."},{"a":"sia","t":"그 대가로 용맹한 모험가들은 그들의 기여에 대한 보상을 받게 됩니다."},{"a":"donovan","t":"그렇군요. 가장... 관대한 통치자시네요."},{"a":"donovan","t":"<c1>순금</c1>은 동전으로 주조되어 화폐에 급격한 인플레이션을 일으키죠..."},{"a":"sia","t":"정확해요. 그동안 황제에게 보내는 제 우편을 가로채셨군요."},{"a":"donovan","t":"전 정보에 빠삭한 걸 좋아하거든요."},{"a":"sia","t":"여기까지 온 김에, 일 좀 도와주세요. 성으로 <c1>순금</c1>을 가져가야 해요."},{"a":"donovan","t":"물론이죠. 레이디를 위해서라면 뭐든지요."},{"a":"sia","t":"돌아가는 길에 손톱 조심해요, 도노번."}]},{"id":"sia_08","i":8,"title":"운명의 갈림길에서","req":"sia:8","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"tavern","t":"꼬마 백조가 돌아왔군요! 위대한 관리자님답게 시간은 칼같이 지킨다니까."},{"a":"sia","t":"불러서 왔어요, 참견쟁이 나야. 기분이 좋지 않으니 용건을 빨리 말하시죠."},{"a":"tavern","t":"그럼 기분이 더 안 좋아지겠네요! 제가 어떤 연금술사의 우편물을 가로챘거든요..."},{"a":"tavern","t":"그것도 특급 우편으로! 이게 얼마나 손에 넣기 힘든 건지 모르실걸요!"},{"a":"sia","t":"설마..."},{"a":"tavern","t":"당신이 하는 장난질이 도노번의 귀에 들어간 모양이에요."},{"a":"sia","t":"당신이 가로챘다면..."},{"a":"tavern","t":"맞아요. 우편은 도착하지 않겠죠! 당신이 대가를 지불한다면 말이지만."},{"a":"sia","t":"난... 좋아요. 뭘 원하는지 말해요, 나야. 내도록 하죠."},{"a":"tavern","t":"평소보다 값을 올렸어요. 이번에는 특별 현상금을 원해요."},{"a":"sia","t":"...좋아요. 그럼..."},{"a":"tavern","t":"어느 편에 설지 확실히 정하세요, 시아. 그게 제가 원하는 거예요."},{"a":"sia","t":"..."},{"a":"tavern","t":"양쪽에서 노는 건 위험해요... 게다가 이미 보기 좋게 일이 꼬인 것 같으니까요."},{"a":"tavern","t":"물론 당신의 대답에 따라 제가 도와줄 수도 있어요..."}]},{"id":"sia_09","i":9,"title":"배반의 사슬","req":"sia:9","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"sia","t":"도노번, 괜찮다면 요청을 하나 하고 싶어."},{"a":"donovan","t":"그래? 들어보지."},{"a":"sia","t":"황제에게 가서 스완 요원이 죽었다고 해. 제국을 위한 명예롭고도 슬픈 죽음이었다고."},{"a":"donovan","t":"뭐, 뭐라고?"},{"a":"sia","t":"나 관두려고, 도노번. 편 바꾸기라고나 할까."},{"a":"sia","t":"그 소식을 네가 전하게 될 거야. 당연히 내 사정도 옹호해 줘야 하고."},{"a":"donovan","t":"마, 말도 안 돼! 이건 대역죄야! 난 절대..."},{"a":"sia","t":"난 널 믿어, 도노번. 전 세계가 네 불멸의 엘릭서 레시피를 알게 되길 원하진 않겠지?"},{"a":"donovan","t":"아하, 이렇게까지 나오겠다는 거지, 시아? 난 누구에게도 레시피를 말한 적 없어. 절대."},{"a":"sia","t":"뭐였더라? 백 년 된 하루살이 날개랑... 스틱스 강물이었나...?"},{"a":"donovan","t":"이, 이건..."},{"a":"sia","t":"재료가 좀 많았어야 말이지.... 와인도 좀 넣었다지? 맛을 내려고?"},{"a":"donovan","t":"그, 그만해! 그만! 어떤 어둠의 힘을 통해 이걸 알아냈는지 모르겠지만..."},{"a":"sia","t":"내 염탐 실력을 얕잡아 봤나 보네."},{"a":"donovan","t":"...그래도 네 하찮은 게임에 참여해 주지. 이번에는."},{"a":"sia","t":"우린 늘 배 아픈 패배자 꼴이네? 내가 건 조건은 충분히 좋은 것 같은데."},{"a":"sia","t":"일생의 업을 위해서라면 배신 한 번쯤이야 괜찮지 않겠어?"}]},{"id":"sia_10","i":10,"title":"사후의 도움","req":"sia:10","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"sia","t":"위스퍼 요원. 나야."},{"a":"essence","t":"*하품*... 이렇게 일찍이요?"},{"a":"sia","t":"자네가 준 정보가 맞았어. 훌륭하게 해냈더군. 잘했어."},{"a":"essence","t":"별거... 아니에요..."},{"a":"sia","t":"도노번은 매사에 신중한 사람이지만, 유령이 훔쳐보는 건 어쩔 도리가 없는 모양이야!"},{"a":"essence","t":"그러게요..."},{"a":"essence","t":"엄청... 화나 보였어요..."},{"a":"sia","t":"약속한 대로 보답은 자네 무덤에 제물로 올리도록 하지."},{"a":"sia","t":"보너스도 조금 챙겨 줬으니까. 가서 도노번을 좀 더 괴롭혀줘. 당분간은 말이야."},{"a":"essence","t":"유령 일을 하고... 돈을 벌다니. 좋네요."}]},{"id":"sia_11","i":11,"title":"자유로워진 백조","req":"sia:11","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"king","t":"시아! 도저히 못 참겠다! 세상에 내 카프리스를 해방하려면 얼마나 기다려야 하는 게냐!?"},{"a":"sia","t":"아직 며칠밖에 지나지 않았습니다, 폐하. 조금만 더 여유를 가지시지요."},{"a":"king","t":"아! 이 문서들은 다 뭐지?"},{"a":"sia","t":"제 출생증명서와 저와 관련된 중요한 행정 서류들입니다."},{"a":"sia","t":"정말 우연히도 이 왕국에서의 제 삶이 기록된 서류 상당수가 사라졌더군요."},{"a":"sia","t":"그래서 기억에 의지해 이 서류들을 충실히 작성해 왔습니다."},{"a":"king","t":"물론이지! 내 최고의 고문이 내 왕국에서 공식적인 인정을 받지 못해서야 쓰겠나!"},{"a":"king","t":"여기 있다! 바로 내 옥새를 찍어주지!"},{"a":"king","t":"끝났다! 언제나처럼 아무리 사소한 것도 자네의 날카로운 눈을 피할 수 없지!"},{"a":"sia","t":"감사합니다, 폐하. 앞으로도 폐하를 모실 수 있기를 바랄 뿐입니다."},{"a":"king","t":"나 또한 그렇다!"},{"a":"king","t":"시아, 지금 내가 보고 있는 게 눈물인가? 서류를 작성하는 게 그렇게나 기쁜 일이었는고?"},{"a":"sia","t":"아... 아닙니다. 사실 이 서류들을 작성하는 건 눈물이 날 정도로 지루했습니다."},{"a":"sia","t":"자, 그럼! 이제 자네의 카프리스에 대해 이야기하는 건 어떤가?"},{"a":"king","t":"시작하지! 내 생각에는 지금 방패 상황이 말이야..."}]}]},{"id":"argon","name":"아르곤","chapters":[{"id":"argon_01","i":1,"title":"왕의 그림자","req":"argon:1","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"argon","t":"...그리고 제 검으로 트러블린을 베어버렸어요! 휘리릭!"},{"a":"elderowen","t":"하하! 멋진 이야기구나, 아르곤!"},{"a":"elderowen","t":"젊은이들은 열정이 넘치는군..."},{"a":"elderowen","t":"자네가 이렇게 함께 아침 산책을 해주니 좋구만."},{"a":"argon","t":"별 말씀을요! 언젠가 기사가 되면 어려운 사람을 도와줄 거예요!"},{"a":"elderowen","t":"자네 아버지처럼 말이지? 자넨 좋은 기사가 될 거야."},{"a":"elderowen","t":"어쩌면 왕의 근위대가 될 수도 있겠지!"},{"a":"elderowen","t":"말이 나와서 말인데 왕이 시장에 행차하신 것 같더구나! 가서 물어보는 건 어떠니?"},{"a":"argon","t":"폐하! 폐하의 기사가 되어 모시고 싶습니다!"},{"a":"king","t":"이... 이게 뭐 하는 짓이지!? 시아, 이 평민을 처리해."},{"a":"sia","t":"알겠습니다, 폐하."},{"a":"sia","t":"당신, 원하는 게 뭐죠?"},{"a":"argon","t":"우와! 전, 어..."},{"a":"argon","t":"전 기사라고 해요! 전 아르곤이 되고 싶어요!"},{"a":"argon","t":"아니, 그게 아니라 반대로..."},{"a":"sia","t":"확실히 배짱은 있네요!"},{"a":"sia","t":"결심이 정말 확고하다면 다음 주에 궁전으로 절 찾아오세요."},{"a":"sia","t":"그리고 그때까지 열심히 훈련하세요! 폐하의 기사 중에 엉터리가 있는 건 참을 수 없어요..."}]},{"id":"argon_02","i":2,"title":"훈련 몽타주","req":"argon:2","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"lilu","t":"아르곤, 여기서 뭐 하는 거예요?"},{"a":"argon","t":"훈련 중이에요! 드디어 왕을 위한 기사가 될 수 있는 기회가 생겼거든요!"},{"a":"lilu","t":"왕이요? ...정체를 알 수 없는 왕의 고문인 시아가 아니고요?"},{"a":"argon","t":"그 여자 이름이 시아예요?! 정말 아름답던데!"},{"a":"lilu","t":"..."},{"a":"argon","t":"으아! 아니야! 중요한 건 폐하라고!"},{"a":"argon","t":"전 기사가 될 거예요! 다른 건 관심 없어요!"},{"a":"lilu","t":"그렇겠죠... 상처를 치료해줄게요, 이리 오세요."},{"a":"argon","t":"고마워요... 아야! 이 주문은 왜 이렇게 아픈 거죠?!"}]},{"id":"argon_03","i":3,"title":"동전의 양면","req":"argon:3","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"argon","t":"좋았어! 시아가 곧 올 거야!"},{"a":"argon","t":"훈련의 성과가 있네, 준비 됐어!"},{"a":"argon","t":"...하지만 아직 너무 긴장되는걸..."},{"a":"argon","t":"오! 안녕하세요! 거기 덤불 안에 있는 분이요!"},{"a":"yami","t":"...!"},{"a":"argon","t":"당신도 기사가 되기 위해 왔나요?"},{"a":"argon","t":"곧 시아가 올 거예요! 친절하시니까 숨지 않아도 돼요!"},{"a":"yami","t":"시아...!"},{"a":"yami","t":"난 이만."},{"a":"argon","t":"잠시만요!"},{"a":"argon","t":"우와! 연막탄이잖아!?"},{"a":"argon","t":"이상한 여자로군..."},{"a":"sia","t":"젊은이, 누구한테 말하는 거야?"},{"a":"argon","t":"시아! 그냥 부끄럼 많은 행인이에요! 신경 쓰지 마세요!"},{"a":"sia","t":"...그래. 그럼 아직 결심이 흔들리진 않은 모양이군."},{"a":"sia","t":"왕의 기사로써 목숨을 걸 준비는 됐나?"},{"a":"argon","t":"당연하지! 아 아니, 물론이죠! 아버지를 자랑스럽게 할 거에요!"},{"a":"sia","t":"좋아. 첫 번째 임무를 주지, 지금 중요한 행사를 앞두고 있다."}]},{"id":"argon_04","i":4,"title":"빈 손으로","req":"yami:4","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"argon","t":"..."},{"a":"sia","t":"농담도 잘해!"},{"a":"sia","t":"암살자를 몰아넣었으면서...막지 못하다니."},{"a":"sia","t":"뿐만 아니라 좋은 사람이라고 생각해서 놓.아.주.라.고 했다며!?"},{"a":"argon","t":"..."},{"a":"sia","t":"이게 무슨 말도 안 되는 소리지?"},{"a":"sia","t":"이 암살자가 네가 목숨 걸고 지키기로 맹세한 우리 왕을 죽이려고 했다는 건 알고 있나?"},{"a":"sia","t":"이런 사건이 생기면 네 알량한 머리로는 이해할 수 없을 만큼 큰 위험이 따르는 법이다."},{"a":"sia","t":"어...왕께서 기사단을 없애버리겠다고 선언하신 듯한데..."},{"a":"sia","t":"...내 입에서 칭찬이 나올 리가 없지. 그만해."},{"a":"argon","t":"..."},{"a":"argon","t":"이런 젠장..."},{"a":"argon","t":"죄송해요, 아버지."}]},{"id":"argon_a","i":4,"title":"명인의 탑","req":"argon:4","reward":{"k":"tokens","id":"tokens","q":3,"n":"행운의 토큰"},"side":true,"lines":[{"a":"elderowen","t":"명인의 탑이라고?"},{"a":"lilu","t":"명인의 탑에 대해 말해주세요!"},{"a":"argon","t":"몇몇 영웅들이 그에 대해 속삭이는 걸 듣긴 했지만, 그걸 본 사람은 없다던데..."},{"a":"elderowen","t":"그래, 명인의 탑은 정말 신비로운 곳이지. 실제로 존재하는지는 아무도 몰라."},{"a":"elderowen","t":"난데없이 나타나 가장 강력한 영웅들에게 탑 속의 수많은 층을 오르도록 시험한다고 해..."},{"a":"elderowen","t":"...그러다가 탑을 본 모든 이의 기억을 지우고 갑자기 사라진다더구나."},{"a":"argon","t":"기, 기억을 지운다고요!?"},{"a":"lilu","t":"이상해요... 그럼 그 전설은 어디서 생겨난 걸까요?"},{"a":"argon","t":"맞아! 누군가는 기억해야 하잖아요!"},{"a":"elderowen","t":"명인의 시험을 극복한 사람은 탑으로부터 그 가치를 인정받는다고 하지."},{"a":"elderowen","t":"이 영웅들은... 그 경험을 통해 달라진 모습으로 돌아온단다. 기억은 그대로 간직한 채 말이다."},{"a":"elderowen","t":"더 정확하게 말하면, 그들의 일부가 탑에 남게 되고 탑의 일부도 그들에게 남아있는 거지."},{"a":"elderowen","t":"...오늘 이야기는 여기까지다. 이 늙은이의 이야기를 들어줘서 고맙구나."},{"a":"lilu","t":"우와! 탑이 정말 존재하는지 궁금한데?"},{"a":"argon","t":"맞아! 나도 그런 던전을 탐험해보고 싶어!"},{"a":"lilu","t":"한 가지 이상한 점이 있어... 오웬 장로님은 이걸 어떻게 다 아시는 걸까?"},{"a":"argon","t":"...!"}]},{"id":"argon_05","i":5,"title":"모험을 찾아다니는 기사","req":"argon:5","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"argon","t":"휴..."},{"a":"steel","t":"아르곤이잖아! 잘 지내?"},{"a":"argon","t":"브롬님, 안녕하세요... 제가 도와드릴 일이 있을까요?"},{"a":"steel","t":"오늘은 없어, 기사님! 무슨 일이길래 그렇게 쳐져 있어?"},{"a":"argon","t":"이제 그냥 아르곤이에요. 저... 기사 직위를 잃었거든요."},{"a":"steel","t":"저런, 속상하겠다..."},{"a":"steel","t":"어떻게 되든, 긍정적으로 생각해야 해! 잘 견뎌낼 수 있을 거야!"},{"a":"steel","t":"조만간 네 운수도 다시 좋아질 거야!"},{"a":"argon","t":"그렇네요... 고마워요, 브롬 님."},{"a":"argon","t":"그때까지... 마을 광장 주변에 있어야겠어요."},{"a":"argon","t":"휴..."}]},{"id":"argon_b","i":5,"title":"우리는 명인일까?","req":"argon:5","reward":{"k":"tokens","id":"tokens","q":3,"n":"행운의 토큰"},"side":true,"lines":[{"a":"lilu","t":"좋은 아침이야, 아르곤."},{"a":"argon","t":"하암... 좋은 아침."},{"a":"lilu","t":"...너도 똑같은가보다?"},{"a":"argon","t":"맞아, 완전히 지쳤어. 밤새 퀘스트를 한 것 같은 느낌이야!"},{"a":"lilu","t":"봐, 네 방패도 전부 깨졌어!"},{"a":"argon","t":"엥? 진짜네! 맹세코 어제까지만 해도 눈부시게 깨끗했던 것 같은데..."},{"a":"lilu","t":"아르곤... 설마...?"},{"a":"polonia","t":"어이! 시장에 <c1>저거너트 정강이 보호대</c1> 구하러 온 풋내기 선원 있나?"},{"a":"lilu","t":"말도 안 돼... 20개라면 더더욱! 다 어디서 난 거죠?"},{"a":"polonia","t":"하! 네가 이런 걸 다 묻다니. 전혀 모르겠어."},{"a":"polonia","t":"자면서 전리품을 획득한 모양이야. 내 안의 해적이 나선 거지. 으르렁."},{"a":"lilu","t":"저 이상한 해적 아가씨도..."},{"a":"lilu","t":"...우리가 전부 탑에 도전했다가 기억을 잃게 된 걸까...?"},{"a":"argon","t":"즉 우리 힘이 부족했다는 거네..."},{"a":"argon","t":"다음을 대비해서 더 열심히 훈련하겠어! 두고 봐!"}]},{"id":"argon_06","i":6,"title":"두 번째 빛","req":"argon:6","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"sia","t":"그래서 그... \"기사\"가 폐하의 암살자를 잡았는데..."},{"a":"sia","t":"...그 사람이 선인이라고 믿고 놓아주었단 말이죠!"},{"a":"king","t":"흥미로운 이야기구나! 이 새로운 기사라는 자는 정말 유망한 사람인 것이 분명해!"},{"a":"sia","t":"외람되지만, 왕이시여..."},{"a":"sia","t":"이자는 폐하를 암살하려던 자를 고작 직감 때문에 잡지 못한 것입니다."},{"a":"king","t":"전형적인 <c1>성전사</c1>의 특징이지, 안 그런가?"},{"a":"sia","t":"네?"},{"a":"king","t":"자기 앙숙의 목숨을 손에 쥐었는데도 단순한 갈등과 싸움 너머를 생각하고..."},{"a":"king","t":"...자신의 직위를 걸 만큼 구제의 가능성에 대한 확신에 차서 놓아준 것 아닌가."},{"a":"king","t":"용기와 박애심에서 비롯된 대단한 행동이야!"},{"a":"sia","t":"저... 저는 미처 그 관점을 생각하지 못했습니다, 폐하."},{"a":"sia","t":"하지만 왕국에서 명망 있는 성전사가 존재했던 것도 이미 수십 년 전인데..."},{"a":"sia","t":"기사단을 소환해 이 문제를 논하도록 할까요?"},{"a":"king","t":"당치 않은 소리! 형식적인 절차는 내가 직접 처리하겠네."},{"a":"sia","t":"분부대로 하겠습니다, 폐하. 당장 호위대를 준비하죠."},{"a":"king","t":"그럴 필요 없네. 쥐 죽은 듯 조용히 행동하겠어!"}]},{"id":"argon_07","i":7,"title":"눈에 띄지 않는 왕","req":"argon:7","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"king","t":"농부들이여, 옆으로 비키거라! 평범한 노동자가 납신다!"},{"a":"tavern","t":"아, 라인홀드 왕이시여! 오랜만에 뵙습니다. 암브로시아라도 대령할까요?"},{"a":"king","t":"쉿! 오늘은 잠행 중이니라! 모르는 척하거라!"},{"a":"tavern","t":"명심하겠습니다! 이리 멍청하게 굴다니!"},{"a":"king","t":"거기! 카운터 뒤에 숨어 있는 너!"},{"a":"argon","t":"아! 죄송합니다, 폐하. 피해 드리겠습니다..."},{"a":"king","t":"무슨 소리! 성전사가 된다는 건 위대한 왕의 곁에 앉는것보다 더 큰 가치를 지니고 있거늘!"},{"a":"argon","t":"곁에 앉는다니... 성전사라니요!?"},{"a":"king","t":"그래! 내 무한한 지혜로 보건대 넌 엄청난 잠재력을 지녔구나!"},{"a":"king","t":"비록 네 행동은... 특이하다만 네 마음은 진실되고, 정의감은... 감탄할 만하구나!"},{"a":"king","t":"하여 왕국은 네가 성전사 시험을 치르기를 명하노라!"},{"a":"argon","t":"성전사 시험... 와!"},{"a":"argon","t":"그건 잘 알고 있습니다! 하나 하나 특별하고, 성전사가 직접 결정한다고..."},{"a":"argon","t":"분명 어려운 시험들이겠죠, 용을 해치운다거나 위험한 유물을 파괴한다거나 하는..."},{"a":"king","t":"물론! 왕국을 위해 용기와 희생 정신을 발휘하는 일이란 당연히 위험한 법이지!"},{"a":"argon","t":"이해합니다! 정말 감사합니다, 폐하! 절대 후회하지 않으실 겁니다!"},{"a":"king","t":"물론이지. 난 항상 옳은 법이니까!"},{"a":"king","t":"...자 그런데, 난 아직 잠행 중이라..."},{"a":"king","t":"거기 자네! 노인분! 카드놀이 하는 법 좀 가르쳐 주게!"},{"a":"master","t":"카드요? 늙은 테오도르는 큰 돈이 걸린 판만 합니다만..."}]},{"id":"argon_08","i":8,"title":"다시 불붙은","req":"argon:8","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"lilu","t":"아르곤! 왜 그렇게 서둘러?"},{"a":"argon","t":"릴루, 난 성전사가 될 거야!"},{"a":"lilu","t":"성전사라고! 저, 정말 멋져. 아르곤! 그런데 어떻게...?"},{"a":"argon","t":"폐하께서 내게 시험대에 오르라고 하셨어! 성전사라는 칭호에 진정으로 걸맞은 유일한 방법이지!"},{"a":"lilu","t":"시험대라... 어떻게 할 생각인데?"},{"a":"argon","t":"..."},{"a":"argon","t":"이런! 전혀 모르겠어!"},{"a":"argon","t":"위대하고 영예로운 일이어야 할 텐데..."},{"a":"lilu","t":"아르곤, 넌 영예로운 사람이야! 수많은 몬스터를 쓰러트렸잖아..."},{"a":"argon","t":"물론이지, 하지만 그 이상이어야 해..."},{"a":"argon","t":"브릭스파이어 피크에 날개 달린 악마가 있다고 들었어. 그거면 될지도 몰라..."},{"a":"lilu","t":"그게 뭐든 간에 넌 나설 준비가 된 것 같아!"},{"a":"argon","t":"고마워, 릴루... 내가 기사 자격을 잃었을 때도 넌 항상 날 믿어줬어..."},{"a":"lilu","t":"오! 뭐, 뭘 그런 거 가지고!"},{"a":"lilu","t":"아무튼! 퀘스트를 하려면 도움이 필요할 거야! 널 위해 치유 두루마리를 준비할게!"},{"a":"argon","t":"좋아! 출발!"}]},{"id":"argon_09","i":9,"title":"브릭스파이어 클래시(아르곤)","req":"argon:9","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"argon","t":"으... 끔찍한 곳이군!"},{"a":"argon","t":"이렇게 올라왔는데도 하피는 보이지도 않고... 암살자의 습격까지 받다니!"},{"a":"argon","t":"...분명 닌자처럼 보였어, 안 그래?"},{"a":"argon","t":"릴루가 이 치료 두루마리를 줬기에 망정이지, 휴!"},{"a":"argon","t":"여기서 쉬어야겠군."},{"a":"argon","t":"...음?"},{"a":"yami","t":"또 너군."},{"a":"argon","t":"왕의 암살자!"},{"a":"argon","t":"이건 운명이야. 하피보다 현상금도 훨씬 커!"},{"a":"yami","t":"...덤벼라. 바로 죽여주마."}]},{"id":"argon_10a","i":10,"title":"개선 행진","req":"yami:9","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"argon","t":"라인홀드 왕이여! 퀘스트는 끝났습니다!"},{"a":"king","t":"훌륭하군! 어떤 끔찍한 괴물을 처치했지?"},{"a":"argon","t":"음... 그건."},{"a":"yami","t":"...어이."},{"a":"king","t":"이... 이게 뭐지!?"},{"a":"sia","t":"경비병! 저들을 모두 체포해!"},{"a":"argon","t":"워어! 잠깐! 아주 새사람이 됐군!"},{"a":"king","t":"그런 건가?"},{"a":"yami","t":"난 그냥... 사과하러 왔어."},{"a":"sia","t":"폐하, 믿기 힘드시겠지만..."},{"a":"argon","t":"저 사람은 내가 보증한다! 기사의 명예를 걸고!"},{"a":"king","t":"그래 좋아! 간청을 들어보지!"},{"a":"sia","t":"음... 결국 이렇게 되다니."},{"a":"sia","t":"경비병! 병력을 더 데려와 저 여자의 일거수일투족을 감시하라!"},{"a":"sia","t":"아르곤, 이 불청객을 어찌 할지 논할 동안 밖에서 기다려요."},{"a":"argon","t":"그럼요!"},{"a":"argon","t":"(...내가 큰 실수를 한 건가?)"}]},{"id":"argon_10b","i":11,"title":"구원자","req":"yami:10","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"sia","t":"아... 오늘도 골치 아픈 일은 끊이지 않는군."},{"a":"argon","t":"레이디 시아! 어떻게 되었나요?"},{"a":"sia","t":"...이런 상황에서도 라인홀드 폐하는 그 암살자를 용서하시려고 해요."},{"a":"sia","t":"내가 믿지 못하는데도 그녀는 자신의 아주만 조직에 대해 귀중한 첩보를 알려줬죠."},{"a":"argon","t":"그렇다면...!"},{"a":"sia","t":"그래요, 우린 그녀의 항목과 사과를 받아들일 거예요."},{"a":"sia","t":"그녀는 너무 굶주려서 지금 치료를 받고 있어요. 곧 회복할 수 있을 거예요."},{"a":"sia","t":"그리고 당신은 성전사 아르곤이죠..."},{"a":"argon","t":"성전사!"},{"a":"sia","t":"그래요. 위협을 이겨내기 위한 것이기도 하지만 왕국의 평생 원수를 구원하겠다는 의미도 있죠..."},{"a":"sia","t":"어쨌든 라인홀드 폐하가 당신을 잘 본 것 같네요."},{"a":"sia","t":"이제 가서 맘껏 축하하세요, 성전사여. 이제 곧 엄청 바빠질 테니!"},{"a":"argon","t":"그러죠! 고마워요!"},{"a":"argon","t":"아버지... 자랑스럽게 여겨주시길."}]},{"id":"argon_epilogue","i":12,"title":"에필로그","req":"argon:10","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"lilu","t":"성전사!? 해냈군요, 아르곤!"},{"a":"argon","t":"정말이지 일을 망쳤다고 생각했는데..."},{"a":"argon","t":"하지만 아버지가 옳았어요. 마음이 시키는 대로만 하면 돼요!"},{"a":"lilu","t":"아... 하지만 그게 꼭 캠페인 때문에 바다까지 건너야 한다는 건 아니지 않나요?"},{"a":"argon","t":"아직은 안 가요. 레이디 시아는 성전사가 되려는 영웅들을 내가 가르치길 바라고 있어요."},{"a":"lilu","t":"아! 그럼 안심이죠! ...당신이 스승이라니, 상상하기 힘들지만요."},{"a":"lilu","t":"완전 중요한 성전사 퀘스트들 때문에 바쁘진 않겠어요?"},{"a":"argon","t":"최선을 다해야죠! 왕국이 절 믿고 있다고요!"},{"a":"tavern","t":"아이고, 우리 고귀한 성전사님!"},{"a":"tavern","t":"브롬이 제련 장갑이 더 필요하다고 하네요!"},{"a":"argon","t":"그래! 바로 줄게요!"},{"a":"lilu","t":"...절대 변하지 않는 것도 있는 법이지, 안 그래요?"},{"a":"tavern","t":"다른 건 몰라도 아르곤은 분명 그래요."}]},{"id":"argon_c","i":13,"title":"단단히 고정되다","req":"malady:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"행운의 토큰"},"side":true,"lines":[{"a":"argon_stone","t":"..."},{"a":"lilu","t":"그 물약... 효과가 없었죠?"},{"a":"lilu","t":"휴... 정말 고생해서 만들었는데..."},{"a":"lilu","t":"미안해요, 아르곤. 저로선 부족했나 봐요... 그 안이 많이 불편하진 않길 바라요."},{"a":"elderowen","t":"흠... 그것 참 끔찍한 소식이구나."},{"a":"lilu","t":"아직 방법이 없는 건 아니에요. 하지만..."},{"a":"lilu","t":"...아르곤이 없으니까 너무 힘드네요."},{"a":"elderowen","t":"녀석이 없으니 확실히 도시가 허전하더구나. 안 그렇니?"},{"a":"lilu","t":"...친구들이 없는 생일 파티 같아요."},{"a":"lilu","t":"...축 처져 있다고 아르곤이 돌아오진 않죠. 다시 일하러 가 봐야겠어요."},{"a":"lilu","t":"도노번에게 도와 달라고 할까 봐요."},{"a":"lilu","t":"대가는 치러야 하겠지만, 사람들이 돈을 모으면 되잖아요!"},{"a":"lilu","t":"어디 갈 수 없다는 건 알지만... 거기서 조금만 기다려요! 우리가 구해 줄게요!"},{"a":"argon_stone","t":"..."}]}]},{"id":"atlab_aang","name":"아앙","chapters":[{"id":"atlab_aang_farewell","i":0,"title":null,"req":null,"reward":null,"side":false,"lines":[{"a":"atlab_aang","t":"상인님! 아파가 기력을 완전히 회복했어요!"},{"a":"atlab_aang","t":"그래서... 작별인 사를 할 시간이에요..."},{"a":"atlab_sokka","t":"너무 슬퍼하지 마세요! 언제든 다시 올 수도 있잖아요!"},{"a":"atlab_aang","t":"맞아요! 소카, 길 기억해?"},{"a":"atlab_sokka","t":"어... 집중 안 했는데..."},{"a":"atlab_sokka","t":"아, 아무튼! 이제 엄청 중요한 아바타 일을 해야 해요!"},{"a":"atlab_sokka","t":"가자, 모모! 갈 시간이야!"},{"a":"atlab_aang","t":"모모! ...모모?"},{"a":"atlab_aang","t":"여기가 좋아? 그래, 알았어."},{"a":"atlab_aang","t":"상인님, 모모를 좀 돌봐주시겠어요?"},{"a":"atlab_aang","t":"나중에 데리러 올게, 모모. 약속해!"},{"a":"atlab_aang","t":"가자, 소카. 고마웠어요, 상인님!"},{"a":"atlab_sokka","t":"잘 있어요!"},{"a":"atlab_aang","t":"가자, 아파! 입입!"}]},{"id":"atlab_aang_01","i":1,"title":"길 잃을 운명","req":"atlab_aang:1","reward":{"k":"tokens","id":"tokens","q":5,"n":"행운의 토큰"},"side":false,"lines":[{"a":"inn","t":"미안하다, 꼬마야. 제대로 못 들었어. 처음부터 다시 말해 줄래?"},{"a":"atlab_aang","t":"죄송해요! 다시 말씀드릴게요!"},{"a":"atlab_aang","t":"저는 아바타 아앙이에요."},{"a":"atlab_aang","t":"친구들과 제 스카이 바이슨을 타고 나는 중이었는데..."},{"a":"atlab_aang","t":"여길 온 걸 보니 길을 잃었나 봐요!"},{"a":"inn","t":"밖에 있는 큰 들소 말하는 거니? 저게 난다고?"},{"a":"atlab_aang","t":"네! 이름은 아파예요. 사람을 좋아해요!"},{"a":"inn","t":"굉장히 피곤해 보이는구나. 누구한테 쫓기는 중이지?"},{"a":"atlab_aang","t":"어, 음..."},{"a":"inn","t":"걱정하지 마라. 우리 집에 온 이상 다치게 두지는 않을 테니까. 이 오스카가 약속하지."},{"a":"inn","t":"그래, 여기 무료로 묵는 건 어때?"},{"a":"atlab_aang","t":"무료요? 정말요!?"},{"a":"inn","t":"너희가 갖고 있는 이상한 돈이 여기서는 쓸모가 없어 보이니까 하는 말이기도 하고."},{"a":"inn","t":"애들이 길바닥에서 자게 둘 수는 없는 일이잖아?"},{"a":"atlab_aang","t":"가, 감사합니다, 오스카 씨!"},{"a":"inn","t":"대신 너희도 일하기엔 충분해 보이니, 가서 내 상인 친구를 돕는 건 어때?"},{"a":"atlab_aang","t":"물론이죠! 정말 감사합니다!"}]},{"id":"atlab_aang_02","i":2,"title":"파이어벤딩?","req":"atlab_aang:2","reward":{"k":"tokens","id":"tokens","q":5,"n":"행운의 토큰"},"side":false,"lines":[{"a":"inn","t":"안녕, 릴루! 와서 내 새 친구랑 인사해!"},{"a":"lilu","t":"안녕! 이런 문신은 처음 보네..."},{"a":"atlab_aang","t":"나는 아앙이야! 이런 모자는 나도 처음 봐!"},{"a":"inn","t":"아앙, 네가 하는 마술 보여줘!"},{"a":"atlab_aang","t":"이거... 말이야?"},{"a":"lilu","t":"어, 어떻게 한 거야? 마법은 안 느껴졌는데!"},{"a":"atlab_aang","t":"에어벤딩이야! 나는 어스벤딩과 워터벤딩도 할 수 있어!"},{"a":"lilu","t":"엄청난걸! 잠깐만, 적어둬야겠어..."},{"a":"lilu","t":"이게 기인가? 이런 걸 실제로 하는 사람을 본 적은 없는데..."},{"a":"atlab_aang","t":"맞아! 하지만 아무나 할 수 있는 건 아니야. 능력을 갖고 태어나서 교육을 받아 마스터해야 해!"},{"a":"lilu","t":"공기, 땅, 물을 벤딩할 수 있다고 했지... 그럼 불은?"},{"a":"atlab_aang","t":"아... 나... 나는 아직 파이어벤딩은 마스터 못 했어..."},{"a":"atlab_aang","t":"...아직 파이어벤딩을 가르쳐 주실 선생님을 못 찾았거든."},{"a":"lilu","t":"그래? 나 화염 마법을 좀 쓸 줄 아는데!"},{"a":"lilu","t":"완전히 같은 건 아니겠지만, 그래도 어떻게 하는지 한번 볼래?"},{"a":"atlab_aang","t":"아... 좋아. 고마워, 릴루."}]},{"id":"atlab_aang_03","i":3,"title":"라스트 에어벤더","req":"atlab_aang:3","reward":{"k":"tokens","id":"tokens","q":5,"n":"행운의 토큰"},"side":false,"lines":[{"a":"elderowen","t":"아앙, 도시 생활은 좀 어떠니?"},{"a":"atlab_aang","t":"오웬 장로님! 정말 좋아요! 이렇게 환대해 주셔서 감사해요."},{"a":"elderowen","t":"아무것도 아니란다. 하지만 궁금한 게 있구나. 네 부모님은 어디에 계시니?"},{"a":"atlab_aang","t":"아... 저는... 부모님이 안 계세요."},{"a":"atlab_aang","t":"우리 가족은... 공기의 유목민은 불의 제국에게 모두 살해당했어요."},{"a":"atlab_aang","t":"...저만 살아남았어요."},{"a":"elderowen","t":"세상에! 정말 안타깝구나, 불쌍한 아이...."},{"a":"elderowen","t":"...돌아갈 곳이 없다면 친구들과 함께 이곳에 정착하는 것 어떠냐?"},{"a":"elderowen","t":"너희들이 머물면 정말 즐거울 거야. 벌써 인기가 대단하더구나!"},{"a":"atlab_aang","t":"그런 제안을 해 주셔서 정말 감사합니다, 장로님... 하지만 그럴 수는 없어요."},{"a":"atlab_aang","t":"지금 우리가 대화하고 있는 이 순간에도 불의 제왕 오자이는 계획을 세우고 있을 거예요."},{"a":"atlab_aang","t":"소진 혜성이 다시 하늘을 밝힐 때, 불의 제국이 제 세상을 정복할 거고..."},{"a":"atlab_aang","t":"...흙의 왕국... 물의 부족... 모두 공기의 유목민과 같은 운명을 맞게 될 거예요."},{"a":"atlab_aang","t":"아바타로서, 저만이 그를 막을 수 있어요! ...근데 전 아직 준비가 안 됐어요."},{"a":"elderowen","t":"아이가 지기에는 너무나 무거운 짐이구나..."},{"a":"elderowen","t":"무슨 일이 있어도, 우리 도시는 널 응원한다는 걸 알아 둬라."},{"a":"atlab_aang","t":"고맙습니다, 장로님. 이미 저희를 위해 많은 걸 해주셨어요!"},{"a":"atlab_aang","t":"모든 게 끝나면 꼭 다시 만나러 올게요!"}]},{"id":"atlab_aang_04","i":4,"title":"소진의 징조","req":"atlab_aang:4","reward":{"k":"tokens","id":"tokens","q":5,"n":"행운의 토큰"},"side":false,"lines":[{"a":"mana","t":"아바타여, 우리의 길이 드디어 만났군요."},{"a":"atlab_aang","t":"누구세요? 저를 어떻게 알죠?"},{"a":"mana","t":"제 심안에 아바타의 존재는 마치 불꽃처럼 빛납니다."},{"a":"atlab_aang","t":"아, 운세를 봐주시는 거군요... 전 괜찮아요!"},{"a":"mana","t":"그대, 많은 것을 갖췄지만 아직 온전하지 못하군요..."},{"a":"mana","t":"불의 제왕과의 매서운 전투가 기다립니다."},{"a":"atlab_aang","t":"불의 제왕 오자이... 그를 아세요?"},{"a":"mana","t":"혜성의 빛 아래에 땅은 산산이 조각나고, 들판은 재로 돌아갈 것입니다!"},{"a":"atlab_aang","t":"그건 저도 알아요! 제가 어떻게 하면 좋죠?"},{"a":"mana","t":"운명의 흐름은 깰 수 없습니다."},{"a":"atlab_aang","t":"..."},{"a":"mana","t":"...하지만 용감한 자라면 영향력을 행사해 다른 곳으로 이끌 수 있죠."},{"a":"mana","t":"의외의 협력자와 허술한 동맹 관계가 열쇠가 될 수 있습니다."},{"a":"atlab_aang","t":"감사합니다, 점술사님... 생각해 볼게요."},{"a":"mana","t":"..."},{"a":"mana","t":"용감해 지세요, 아바타. 스스로를 믿으면 극복할 수 있을 겁니다."}]}]},{"id":"ashley","name":"애쉴리","chapters":[{"id":"ashley_01","i":1,"title":"특이한 사무라이","req":"ashley:1","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"argon","t":"진짜 사무라이라니...! 기대돼!"},{"a":"argon","t":"레이디 사무라이! 전 아르곤이라고 해요! 견습 기사..."},{"a":"ashley","t":"오이. 난 애쉴리야. 무슨 일이지?"},{"a":"argon","t":"오... 오이?"},{"a":"tavern","t":"상에 발 올려놓지 말아요!"},{"a":"ashley","t":"쳇, 그러죠."},{"a":"ashley","t":"그래서? 원하는 게 뭐야?"},{"a":"argon","t":"음... 사무라이는 보통 질서 있고 그렇지 않나요?"},{"a":"ashley","t":"음? 그래, 고향에 있던 녀석들은 꽤 답답하게 굴었지."},{"a":"ashley","t":"난 이제 자유야. 로닌이지. 영주가 없는 사무라이 말이야."},{"a":"argon","t":"그렇군요... 아, 맞다!"},{"a":"argon","t":"릴루랑 유령의 성에서 계획된 퀘스트가 있었는데..."},{"a":"argon","t":"훈련소에 일이 생겨서요! 저 대신 가주실 수 있나요?"},{"a":"ashley","t":"물론이지. 하지만 나한테 빚진 거야, 꼬마 기사."}]},{"id":"ashley_02","i":2,"title":"무장 준비 완료","req":"ashley:2","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"ashley","t":"네가 릴루니?"},{"a":"lilu","t":"맞아요! 만나서 반가워요!"},{"a":"ashley","t":"그래 그럼, 출발하자."},{"a":"lilu","t":"자, 잠깐만요! 기다려요!"},{"a":"lilu","t":"아직 준비가 덜 끝났어요! 약물이랑, 식량이랑..."},{"a":"ashley","t":"상관 없어. 그런 거 필요하지 않을 거야."},{"a":"ashley","t":"죽거나 사는 거지. 중간 따위는 없다고."},{"a":"lilu","t":"그건... 아니에요! 너무 무모하다고요!"},{"a":"ashley","t":"난 갈거야. 이쪽이지?"},{"a":"lilu","t":"아니에요! 거기는 울부짖는 숲이에요..."},{"a":"argon","t":"음... 행운을 빌어요...?"}]},{"id":"ashley_03","i":3,"title":"삶의 가장자리","req":"ashley:3","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"ashley","t":"몬스터는 이게 다야? 덤벼!"},{"a":"lilu","t":"애쉴리! 좀 천천히 해요! 치유가 따라잡을 수 없다고요!"},{"a":"ashley","t":"이건... 아무것도... 아냐!!!"},{"a":"ashley","t":"휴... 괜찮은 싸움이었지?"},{"a":"lilu","t":"장난해요!? 거의 죽을 뻔했잖아요!"},{"a":"lilu","t":"계속 이런 식으로 싸우니 팔을 잃은 것도 놀랍지 않네요!"},{"a":"ashley","t":"오이. 그건 다른 얘기야."},{"a":"ashley","t":"그 실수는... 다시는 반복하지 않아."},{"a":"lilu","t":"에헴. 이번 치유에서는 마취 안 할 거예요."},{"a":"lilu","t":"애쉴리 잘못이에요. 마음 단단히 먹어요."},{"a":"ashley","t":"하하... 하... 괜찮다고..."},{"a":"ashley","t":"아우! 아야, 아야, 아야..."}]},{"id":"ashley_a","i":4,"title":"패밀리어 느낌","req":"ashley:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"행운의 토큰"},"side":true,"lines":[{"a":"ashley","t":"오이. 이 주변의 작은 몬스터는 다 뭐야?"},{"a":"elven","t":"저건 내가 아끼는 패밀리어야. 환영해."},{"a":"elven","t":"가치 있는 챔피언이라면 와서 충직한 동료로 입양할 수 있지."},{"a":"ashley","t":"아. 펫이네? 알겠어."},{"a":"ashley","t":"좋아. 요 녹색 녀석. 널 <c1>트리키</c1>라고 부를게. 같이 가자."},{"a":"ashley","t":"정말 귀엽구나, <c1>스노우볼</c1>. 널 데려갈게."},{"a":"elven","t":"아... 그게..."},{"a":"ashley","t":"으윽, 정말 못생긴 새네!"},{"a":"ashley","t":"넌 <c1>스패로우</c1>라고 부를게. 너도 같이 가자."},{"a":"elven","t":"...그래요. 다들 재밌게 보내."}]},{"id":"ashley_04","i":5,"title":"퀘스트 성공적으로 실패.","req":"ashley:4","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"argon","t":"어제 퀘스트는 어땠어? 릴루 보니까 화가 머리끝까지 난 거 같던데..."},{"a":"ashley","t":"아쉽지만.. 멀쩡히 돌아왔어."},{"a":"argon","t":"응?! 그럼 좋은 일 아냐?"},{"a":"king","t":"반갑구나, 평민들이여! 짐의 찬란한 위엄을 마음껏 우러러보도록 하여라!"},{"a":"ashley","t":"아, 국왕 폐하! 애쉴리, 출동했습니다!"},{"a":"king","t":"그야말로 군인의 표본이로구나! 계속 힘쓰도록 하라!"},{"a":"ashley","t":"네, 알겠습니다! 감사합니다, 폐하!"},{"a":"tavern","t":"죄송합니다, 라인홀드 폐하. 주문하신 빈티지 와인이 아직 도착하지 않았습니다."},{"a":"king","t":"좋다! 그럼 내일 다시 오마!"},{"a":"argon","t":"방금 그거 뭐였어?"},{"a":"ashley","t":"아, 그게... 한때 주군을 모신 적이 있거든. 나도 모르게 옛 습관이 튀어나왔군."},{"a":"argon","t":"멋진데! 그때 얘기 좀 해봐!"},{"a":"ashley","t":"싫어."}]},{"id":"ashley_05","i":6,"title":"뒤바뀌는 이야기","req":"ashley:5","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"ashley","t":"...그러고 나서 내가 그 녀석한테 말했지..."},{"a":"ashley","t":"\"무장 다 했냐고? 글쎄, 준비는 끝났다고 봐야지!\""},{"a":"argon","t":"하하하!"},{"a":"argon","t":"...근데 애쉴리, 아까 말한 그 주군 말인데..."},{"a":"ashley","t":"하아, 정말... 정말 끈질기군. 알았어."},{"a":"ashley","t":"...사무라이는 주군, 즉, 다이묘를 모시거든. 목숨을 다해 다이묘를 섬기고 지키는 게 우리 임무라서."},{"a":"argon","t":"진짜 명예로운 일이네!"},{"a":"ashley","t":"여느 때와 다름없던 어느 날, 주군께서는 평소처럼 점심을 드시고 계셨어..."},{"a":"ashley","t":"그런데 갑자기, 쾅 소리가 나더니 닌자들이 나타나더라고. 방 안에 가득 찰 정도로. 모두가... 우리 주군의 목숨을 노리고 있었어."},{"a":"ashley","t":"그래서 다들 필사적으로 싸웠어. 한두 번 겪은 일도 아니었으니까. 근데..."},{"a":"ashley","t":"정통으로 한 방 맞아버린 거야. 그때 팔을 잃었고."},{"a":"ashley","t":"그렇게 난... 도망칠 수밖에 없었어. 주군을 죽게 내버려두고 말이야."},{"a":"argon","t":"애쉴리..."},{"a":"ashley","t":"...으아아아아!!! 그냥 거기서 나도 죽었어야 했는데!"},{"a":"ashley","t":"...나야, 한 잔만 더 줘."},{"a":"tavern","t":"오늘은 마실 만큼 마셨어, 애쉴리."},{"a":"ashley","t":"그래. 뭐, 됐어. 충분히 마시긴 했으니까."},{"a":"ashley","t":"좋아. 아르곤, 가서 릴루한테 전해. 애쉴리가 진짜 위험한 퀘스트를 수행하러 간다고 말이야."},{"a":"argon","t":"응? 지금 당장?!"},{"a":"ashley","t":"당연하지. 목적지는... 오로라 동굴로 해볼까. 서두르는 게 좋을 거야!"}]},{"id":"ashley_06","i":7,"title":"눈에는 나","req":"ashley:6","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"ashley","t":"...닌자 아가씨로군. 엿듣고 있었나?"},{"a":"yami","t":"...살짝. 어때, 밖으로 나갈까?"},{"a":"ashley","t":"됐어. 오늘은 싸울 기분이 아니라서."},{"a":"yami","t":"쿠스노키 님이 그렇게 된 건 우리 일족 때문이야. 나야 이미 파문당한 몸이긴 하지만, 혹시 내 사과라도 받으면..."},{"a":"ashley","t":"고맙지만 그럴 필요 없어. 내가 미운 건 네가 아니라 나 자신이니까."},{"a":"yami","t":"이해해... 아니라고 생각할 수도 있는데 진짜야."},{"a":"yami","t":"하지만 명예가 갈기갈기 찢겼다 해도, 아직 살아갈 이유는 충분히 많아."},{"a":"yami","t":"친구들도 있고, 가족 같은 도시에 아끼는 펫까지 있으니까."},{"a":"yami","t":"...그걸로도 부족하다면, 명예로운 죽음을 위한 결투 정도는 해줄 수도 있고."},{"a":"ashley","t":"닌자가 공짜 암살을 해주겠다고? 이거 참 영광이네."},{"a":"ashley","t":"고마운데, 괜찮아. 뭐, 그래도 생각은 좀 해볼게."},{"a":"yami","t":"알았어, 좋을 대로 해."}]},{"id":"ashley_07","i":8,"title":"마지막 일전","req":"ashley:7","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"lilu","t":"하아... 하아... 애쉴리가 없네..."},{"a":"lilu","t":"또 길을 잃은 건가...?"},{"a":"lilu","t":"아니... 잠깐. 내가 속은 건가?"},{"a":"ashley","t":"분명 신더레이크 화산으로 가고 있는 줄 알았는데..."},{"a":"ashley","t":"뭐, 아무렴 어때."},{"a":"ashley","t":"좋아아아아! 일어나거라, 이 얼간이들아! 애쉴리 님이 오셨다!"},{"a":"monster_Grotto_Mob","t":"취한... 인간인가?"},{"a":"ashley","t":"잔소리하는 힐러도 없겠다, 오늘은 죽기 살기로 덤벼 주마! 죽기 전엔 절대 안 멈출 테니 참고해 두고!"},{"a":"ashley","t":"무슨 일이 있어도 내가 이길 거다! 자, 누가 먼저 올래?"},{"a":"monster_Ruins_Mob","t":"크아아! 덤벼라!"},{"a":"ashley","t":"그래, 기세 좋고!"}]},{"id":"ashley_08","i":9,"title":"데우스 엑스 아스테아","req":"ashley:8","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"priest","t":"아, 여신이시여... 여기가 맞나?"},{"a":"priest","t":"세상에, 완전 피바다가 따로 없네."},{"a":"monster_Grotto_Mob","t":"히히히."},{"a":"priest","t":"몬스터 여러분, 죄송하지만 동료 하나만 데려가려고 하는데요."},{"a":"monster_Grotto_Mob","t":"안 돼! 이건 말도 안 된다고! 녀석한테 전부 당하다니! 저 사무라이는 이미 죽은 몸이야!"},{"a":"priest","t":"아직 살아있거든요? 애쉴리는 고작 이 정도로 죽을 사람이 아니라서요."},{"a":"monster_Ruins_Mob","t":"그래? 그럼 내가 끝장내 주마!"},{"a":"priest","t":"그런 짓을 하게 둘 수는 없죠."},{"a":"monster_Grotto_Mob","t":"히히하! 네가 어쩔 건데? 치료라도 해 주게?"},{"a":"priest","t":"어쩔 수 없네요. 아스테아 여신이시여, 이들을 용서하소서..."},{"a":"priest","t":"전 용서할 생각 없으니까요."}]},{"id":"ashley_09","i":10,"title":"침상 속박","req":"ashley:9","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"ashley","t":"...윽..."},{"a":"priest","t":"정신이 드셨군요."},{"a":"ashley","t":"응? 아, 진짜... 너까지 온 거야? 근데 어떻게... 찾았어?"},{"a":"priest","t":"저까지 보내신 걸 보니... 여신님께서 당신을 각별히 아끼시나 봐요."},{"a":"ashley","t":"젠장... 아, 좀. 그냥 죽게 놔둬."},{"a":"priest","t":"진심이면 그렇게 할게요."},{"a":"ashley","t":"휴... 드디어..."},{"a":"ashley","t":"..."},{"a":"ashley","t":"...그런데 왜 아직도 날 치료하고 있는 거야?"},{"a":"priest","t":"말은 그렇게 하셨어도 살고 싶은 게 진심인 것 같거든요."},{"a":"priest","t":"치유 마법은 그저 생명력을 북돋울 뿐이에요. 당신이 진심으로 죽기를 원했다면 저도 손쓸 도리가 없었겠죠."},{"a":"ashley","t":"그렇군..."},{"a":"priest","t":"...일단 푹 쉬세요. 생각할 게 아주 많을 테니까요."}]},{"id":"ashley_10","i":11,"title":"생각할 시간","req":"ashley:10","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"argon","t":"돌아오셨군요! 릴루가 당신을 온통 찾아다녔어요!"},{"a":"argon","t":"...당신도 좀 엉망이네요."},{"a":"ashley","t":"신경 쓰지 마, 다 나았어. 혼도 났고."},{"a":"argon","t":"프레이야에게서? 상상하기 힘든데."},{"a":"ashley","t":"응. 그녀가 나보고 생각 좀 해보라고 했어. 그래서 생각하고 있지."},{"a":"tavern","t":"생각한다고? 신기하네!"},{"a":"ashley","t":"그만둬."},{"a":"ashley","t":"...라고 말하고 싶지만, 네 말이 맞아."},{"a":"ashley","t":"과거에 너무 오랫동안 매여 지냈더니, 생각하는 법마저 잊어버렸군."},{"a":"argon","t":"무엇을 생각하라는 거야?"},{"a":"ashley","t":"흠. 이것저것 많네."},{"a":"ashley","t":"나도 모르게, 소중히 여기는 것들이 참 많아진 것 같다."},{"a":"ashley","t":"도시. 사람들. 가게 주인. 너도, 꼬마 기사."},{"a":"ashley","t":"몇 번이나 죽을 고비를 넘기고 나서야 겨우 깨달았군. 내가 좀 둔한가 보네, 훗."},{"a":"argon","t":"사무라이님, 영광입니다!"},{"a":"ashley","t":"여전히 이곳의 낭인이다. 당분간은 달라지리라 기대 마라."},{"a":"yami","t":"..."},{"a":"yami","t":"..."}]},{"id":"ashley_epilogue","i":12,"title":"에필로그","req":"ashley:11","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"ashley","t":"어이, 릴루. 퀘스트 하나 더 나가려는데, 같이 갈래?"},{"a":"lilu","t":"흥! 또 이상한 곳으로 데려가려고요?"},{"a":"lilu","t":"아니면 또 무모하게 덤비다가 된통 당해서 저만 하루 종일 당신 꿰매느라 고생하게 만들 거잖아요?"},{"a":"ashley","t":"...아니야, 나도 이제 완전히 달라졌다고. 살살 할게. 한 손만 쓰면 되잖아."},{"a":"lilu","t":"흠... 그럼 알겠어요."},{"a":"lilu","t":"잠깐만요..."},{"a":"ashley","t":"하하! 농담이야, 농담."},{"a":"ashley","t":"내 뒤만 좀 봐줘. 그럼 나도 그렇게 할게."},{"a":"lilu","t":"좋아요! 그래도 이번엔 꼭 약속해요."},{"a":"lilu","t":"상황이 너무 위험해지면... 바로 후퇴하자고요. 제 말 꼭 들으시고요!"},{"a":"ashley","t":"약속하지. 보잘것없을 수도 있지만, 로닌의 명예를 걸고 그렇게 할게."},{"a":"ashley","t":"어쨌든 우리도 돌아갈 집이 있으니까."}]}]},{"id":"yami","name":"야미","chapters":[{"id":"yami_01","i":1,"title":"아주마 방랑자","req":"yami:1","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"monster_forest_Boss","t":"히히히! 이게 누구신가?"},{"a":"yami","t":"흥, 꺼져."},{"a":"monster_forest_Boss","t":"예의가 없으시네! 옷도 이상하고!"},{"a":"yami","t":"..."},{"a":"monster_forest_Boss","t":"아하! 동부 인간 왕국인 아주마 냄새가 나는군!"},{"a":"monster_forest_Boss","t":"이 먼 곳까지는 어쩐 일로 오셨나?"},{"a":"monster_forest_Boss","t":"완전 무장을 하고 입은 꼭 다물고 있는 걸 보니... 암살자구나?"},{"a":"yami","t":"..."},{"a":"monster_forest_Boss","t":"히히! 그럴 줄 알았다니까. 멍청한 인간들, 언제나 서로 죽이려 하지!"},{"a":"yami","t":"...맞다. 내가 여기까지 온 것은 폭정을 펼치는 왕을 죽이기 위해서다."},{"a":"monster_forest_Boss","t":"이렇게 떠들고 다니다니 좋은 암살자는 되기 어렵겠어! 내게 말해주는 이유가 뭐지?"},{"a":"yami","t":"죽은 자는 말이 없기 때문이지. 잘 가라고."},{"a":"monster_forest_Boss","t":"윽!"},{"a":"yami","t":"...라인홀드 왕, 다음은 네 차례다."}]},{"id":"yami_02","i":2,"title":"사냥하거나 사냥당하거나","req":"yami:2","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"yami","t":"...궁전의 보안이 삼엄하군."},{"a":"yami","t":"암호도 매일 바뀌고..."},{"a":"yami","t":"정찰 일정도 정해져 있지 않아..."},{"a":"yami","t":"그럼..."},{"a":"argon","t":"안녕하세요! 거기 덤불 안에 있는 분이요!"},{"a":"yami","t":"...!"},{"a":"argon","t":"당신도 기사가 되기 위해 왔나요?"},{"a":"argon","t":"곧 시아가 올 거예요! 친절하시니까 숨지 않아도 돼요!"},{"a":"yami","t":"시아...!"},{"a":"yami","t":"난 이만."},{"a":"argon","t":"잠시만요!"},{"a":"argon","t":"우와! 연막탄이잖아!?"},{"a":"yami","t":"...멍청이는 따돌렸군."},{"a":"yami","t":"시아가 있으면... 내 임무를 달성하기 어렵겠어."},{"a":"yami","t":"하지만 해내야만 해. 실패할 순 없지."},{"a":"yami","t":"조직을 위해... 그리고 언니를 위해."}]},{"id":"yami_03","i":3,"title":"반환점","req":"yami:3","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"king","t":"존경하는 국민들이여! 내 멋진 연회에 잘 와주었다!"},{"a":"king","t":"아름다운 내 모습을 보기에도 알맞은 기회가 아닌가! 이 기회를 놓치지 말라!"},{"a":"yami","t":"(전형적인 거만한 독재자로군.)"},{"a":"sia","t":"음 네. 훌륭한 연설 감사합니다 폐하."},{"a":"sia","t":"오늘은 폐하의 놀라운 너그러움을 축하하기 위해 모였습니다."},{"a":"sia","t":"지난 몇 달 간 왕께서는 수백 만 골드를 사비로 기부하셨습니다."},{"a":"sia","t":"...기부처는 지역 사원과 학교 및 고아원입니다."},{"a":"sia","t":"모든 분들은 오늘 연회에 초대되셨으니 가족과 친구들에게도 알리시기 바랍니다."},{"a":"sia","t":"라인홀드 왕 만세!"},{"a":"yami","t":"(...독재자가 할 만한 짓이 아닌데.)"},{"a":"yami","t":"(...아니 조직에서 거짓말을 할 리가. 함정이야.)"},{"a":"yami","t":"독재자 라인홀드, 오늘이 네 제삿날이다!"},{"a":"sia","t":"수리검...! 아주마의 암살자로군!"},{"a":"yami","t":"내가 실패했다고...!? 그럴 리가!"},{"a":"sia","t":"경비병! 모든 출구를 막아라! 이 여자를 당장 잡아와!"}]},{"id":"yami_04","i":4,"title":"반사","req":"yami:4","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"yami","t":"(망설이다 결국...실패했지.)"},{"a":"yami","t":"(조직에서 거짓말을 한 걸까...?)"},{"a":"yami","t":"(상관 없어. 이제 혼자 해야 해.)"},{"a":"argon","t":"드디어 찾았다!"},{"a":"yami","t":"멍청한 기사!"},{"a":"argon","t":"우와! 난 싸우러 온 게 아냐!"},{"a":"yami","t":"네 속임수엔 넘어가지 않아, 라인홀드의 개 같으니라고!"},{"a":"argon","t":"...일부러 빗맞춘거지?"},{"a":"yami","t":"...!"},{"a":"argon","t":"연회장에서 널 봤어. 수리검을 던진 것조차 후회하는 듯 보이더군."},{"a":"argon","t":"왕은 나쁜 사람이 아닌 거 알아? 이상하긴 하지만 최선을 다하고 있다고!"},{"a":"argon","t":"누가 사주했는진 모르겠지만 좋은 녀석들은 아닐 거야..."},{"a":"argon","t":"성으로 돌아가서 사과하는 게 어때? 라인홀드 왕이..."},{"a":"yami","t":"...사과한다고? 멍청하군."},{"a":"yami","t":"생각할 게 많아졌어. 따라오지 마, 살고 싶으면."},{"a":"argon","t":"...나쁜 사람은 아냐, 확실해."},{"a":"argon","t":"시아에게 보고해야겠군..."},{"a":"argon","t":"엄청 까이겠네..."}]},{"id":"yami_05","i":5,"title":"달빛 아래","req":"yami:5","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"fabric","t":"<sprite tint=1 name=Note1>높은 버드나무에 드리운 햇빛, 지난날의 찬란함이여<sprite tint=1 name=Note2>..."},{"a":"fabric","t":"<sprite tint=1 name=Note2>엘프의 숲속 빈터에서 우리는- 꺆!"},{"a":"yami","t":"지금 차갑게 쏘이는 느낌이 드는 건 당신 목을 겨눈 내 칼입니다."},{"a":"yami","t":"궁금한 게 있는데, 솔직히 대답해준다면 살려줄 수도 있습니다."},{"a":"fabric","t":"아악! 네! 뭐든지- 아야!"},{"a":"yami","t":"조용히 하세요."},{"a":"yami","t":"당신들이 왕이라고 부르는 머저리... 그에 대해 알고 싶습니다."},{"a":"fabric","t":"라... 라인홀드 왕이요? 이곳을 지배하는 분이고..."},{"a":"fabric","t":"특이하시긴 하지만, 그의 미덕과 관용은 모두가 인정하죠."},{"a":"fabric","t":"... 그에게 부족한 경험 부분은 그의 새 고문인 시아가 십분 보완해주고요!"},{"a":"yami","t":"말도 안 돼...! 당신의 말에서는 비겁함이 묻어나지만, 진실인 것 같긴 하군요."},{"a":"yami","t":"이 도시 말입니다! 사제가 있습니까?"},{"a":"fabric","t":"아! 네! 언덕 위쪽에 사는 세렌이 있어요!"},{"a":"fabric","t":"불가사의한 이방인이시여... 당신의 이름을 제게...아야!"},{"a":"yami","t":"며칠 전까지만 해도 당신을 죽이는 데 망설임이 없었을 겁니다. 날 시험하지 마세요."},{"a":"yami","t":"이제 하던 지루한 일을 마저 하고 방금 일어난 모든 일은 잊는 겁니다."},{"a":"fabric","t":"...휴우! 이렇게 짜릿한 만남이라니!"},{"a":"fabric","t":"검은 옷의 여성이라... 과연 다시 만날 일이 있을까...?"}]},{"id":"yami_06","i":6,"title":"무너진 하수인","req":"yami:6","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"mana","t":"...흑풍이 조용한 침입자의 존재를 들춰버리는군요."},{"a":"yami","t":"...! 어떻게...?"},{"a":"mana","t":"깃털처럼 걸을지 몰라도, 무거운 마음은 심안으로 훤히 보이는 법입니다."},{"a":"yami","t":"...속임수는 그만두시죠, 사제님. 전 알아야 할 진실이 있습니다."},{"a":"yami","t":"조직과... 제 가족에 대한 진실이요."},{"a":"mana","t":"죽음을 다루는 자가 조언을 구하는군요. 그 조언에 대한 답례는 무엇입니까?"},{"a":"yami","t":"당신의 목숨."},{"a":"mana","t":"... 좋습니다."},{"a":"mana","t":"<c1>한때 세상의 그릇됨을 바로잡으려 힘썼던 아주만 조직...</c1>"},{"a":"mana","t":"<c1>... 질서의 투사였던 그들이 막대한 부의 노예가 되어...</c1>"},{"a":"mana","t":"<c1>... 불가능에 가까운 일을 위해 희생된 하수인...</c1>"},{"a":"mana","t":"<c1>... 실패하든 성공하든 조직에 이득이 될 것이다.</c1>"},{"a":"yami","t":"... 말도 안 돼."},{"a":"mana","t":"사제는 하늘의 말을 전합니다."},{"a":"yami","t":"... 말도 안 돼!"},{"a":"mana","t":"..."},{"a":"mana","t":"그림자 속을 걷는 자는 그만큼 빛으로 베풀어야 합니다. 시간이 허한다면 말이죠."}]},{"id":"yami_07","i":7,"title":"무너진 하수인","req":"yami:7","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"yami","t":"...내 물건들을 갖고 최대한 빨리 떠나야겠어."},{"a":"inn","t":"저기, 수수께끼의 이방인님."},{"a":"yami","t":"주인장. 입을 다물라고 방값을 더 줬을 텐데."},{"a":"inn","t":"걱정 마세요. 에메랄드 여관에서는 누구도 캐묻지 않으니!"},{"a":"inn","t":"그렇긴 해도, 뭔가 험상궂은 손님들이 이방인님을 찾고 있는 거 같던데요."},{"a":"yami","t":"(조직의 집행자들? 이렇게나 빨리?)"},{"a":"inn","t":"이름도 안 남겨서. 아주 수상쩍더군요. 친구들인가요?"},{"a":"yami","t":"이젠 아니지. 내가 죽었다고 말해. 진짜 그럴지도 모르니."},{"a":"inn","t":"급하게 가시게요? 그러실 것 같긴 했지만. 혹시 몰라 뭘 좀 준비했습니다."},{"a":"yami","t":"...고마워 주인장. 하지만 내가 가려는 곳에는 필요 없어."}]},{"id":"yami_08","i":8,"title":"돌아오지 않는 길","req":"yami:8","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"sia","t":"브릭스파이어 피크로 간다고요?"},{"a":"wood","t":"예. 당신이 얘기한 모습의 닌자 소녀를 봤습니다. 서두르는 눈치더군요."},{"a":"sia","t":"좋아요. 마침내 암살자를 따라잡았군요."},{"a":"sia","t":"병력을 모아서..."},{"a":"wood","t":"정말인가요? 그럴 필요까지는."},{"a":"sia","t":"...왜죠, 고르자?"},{"a":"wood","t":"브릭스파이어 피크로 혼자 떠나는 건 자살행위예요. 그 애는 갖고 있는 물건도 전혀 없었고요."},{"a":"wood","t":"그걸 모를리가 없습니다. 루도도 거길 혼자 갈 만큼은 어리석지 않아요."},{"a":"sia","t":"그런가요? 고마워요, 고르자. 명심하죠."},{"a":"sia","t":"이 문제는 절로 해결될 줄 알건만..."},{"a":"sia","t":"...영 뒤가 찝찝하게 됐네요. 무슨 생각하지, 암살자?"}]},{"id":"yami_09","i":9,"title":"브릭스파이어 클래시 (야미)","req":"yami:9","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"argon","t":"이건 운명이야. 하피보다 현상금도 훨씬 커!"},{"a":"yami","t":"...덤벼라. 바로 죽여주마."},{"a":"argon","t":"말은 그렇게 해도, 진심으로 들리진 않는군..."},{"a":"yami","t":"...그래, 맞아. 이제는 아무 상관없어."},{"a":"yami","t":"정말 날 죽이고 싶다면 여기서 죽게 내버려둬."},{"a":"argon","t":"난 절대 누굴 죽게 내버려두지 않아! 널 라인홀드 왕에게 다시 데려가야겠어!"},{"a":"argon","t":"왕은 이해할 거야! 널 다시 데려가는 게 옳아!"},{"a":"yami","t":"..."},{"a":"argon","t":"어서, 흡!"},{"a":"argon","t":"잡아. 뼈랑 가죽밖에 안 남았군! 마지막으로 뭘 먹은 게 언제야?"},{"a":"yami","t":"..."},{"a":"argon","t":"가는 길에 뭐 좀 먹자. 힘든 여행이 될 테니!"}]},{"id":"yami_10","i":10,"title":"적진 속으로","req":"argon:10","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"sia","t":"경비병! 병력을 더 데려와 저 여자의 일거수일투족을 감시하라!"},{"a":"sia","t":"아르곤, 이 불청객을 어찌 할지 논할 동안 밖에서 기다려요."},{"a":"argon","t":"그럼요!"},{"a":"sia","t":"자 그럼. 말해봐, 암살자."},{"a":"yami","t":"흠, 맞아. 난 폭군을 암살하도록 고용되었다."},{"a":"yami","t":"폭군이라는 건 내 생각이었을지도 몰라. 그저 사람 좋은 광대처럼 보이니까."},{"a":"king","t":"광대!?"},{"a":"sia","t":"너희는 왜 폐하에게 맞서는 거지?"},{"a":"yami","t":"우리 조직은 정의의 이름으로만 처단한다..."},{"a":"yami","t":"하지만 거짓이었을지도 몰라. 그리고 나도 실패했으니 이제 사냥감의 처지가 되었지."},{"a":"yami","t":"저기... 사과할게. 마땅한 처벌을... 받겠다..."},{"a":"yami","t":"...윽."},{"a":"king","t":"쓰러졌다!"},{"a":"sia","t":"굶주림에 탈진까지..."},{"a":"sia","t":"경비병! 최고의 의사들을 불러와라!"},{"a":"sia","t":"왕실의 손님으로 극진히 모셔라."}]},{"id":"yami_epilogue","i":11,"title":"에필로그","req":"yami:10","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"sia","t":"헉... 헉... 널 보러 오는 건... 정말 등산이나 마찬가지네..."},{"a":"yami","t":"이젠 여기가 집이야."},{"a":"sia","t":"왜 도시 안에서 살지 않고? 넌 사면 받았잖아."},{"a":"yami","t":"조직에선 내가 죽었다고 믿을 게 분명해. 그렇게 해두고 싶어."},{"a":"sia","t":"그래, 이해해. 필요한 물건을 한 번씩 보내주지."},{"a":"sia","t":"자 그럼, 네 다음 임무는..."},{"a":"yami","t":"해치울 녀석들이 더 있는 거야?"},{"a":"sia","t":"맞아. 알겠지만 폐하를 노리는 악의 무리들이 많지."},{"a":"sia","t":"이 문서에 목표에 대한 자세한 정보가 나와 있으니 살펴봐."},{"a":"yami","t":"문제 없이 해결할게."},{"a":"sia","t":"선뜻 말하기는 어렵지만 널 믿어."},{"a":"sia","t":"돌아갈 시간이군. 그리 즐거운 여행은 못 되겠지만..."},{"a":"yami","t":"시아... 라인홀드..."},{"a":"yami","t":"...고마워. 정말로."}]}]},{"id":"leather","name":"태마스","chapters":[{"id":"leather_farewell","i":0,"title":null,"req":null,"reward":null,"side":false,"lines":[{"a":"leather","t":"이봐 친구. 드디어 챔피언이 된 것 같아."},{"a":"leather","t":"그런데 생각보다 책임이 많아, 친구. 가죽 살 시간도 없어!"},{"a":"leather","t":"그래서 내년에 다시 해보려고, 친구. 마을에서 다시 보자고!"}]},{"id":"leather_01","i":1,"title":"가죽과 나무","req":"leather:1","reward":{"k":"tokens","id":"tokens","q":5,"n":"행운의 토큰"},"side":false,"lines":[{"a":"leather","t":"도와줘서 고마워, 친구."},{"a":"argon","t":"천만에, 태마스! 가죽 엄청 많네!"},{"a":"leather","t":"오늘 짐이 많네. 그래도 발밑 조심하라고."},{"a":"argon","t":"그래... 여기 주변 울퉁불퉁한걸... 우왁!"},{"a":"leather","t":"우와! 오우!"},{"a":"argon","t":"미안, 태마스! 괜찮아?"},{"a":"leather","t":"머리를 좀 부딪쳤어, 친구. 괜찮은 것 같아."},{"a":"leather","t":"...천재적인 생각이 떠올랐어, 친구"},{"a":"leather","t":"가야겠어, 친구. 이거 엄청나다고."},{"a":"argon","t":"아, 그래! 도움이 돼서 다행이야!"},{"a":"argon","t":"...그런데 이 흩어진 가죽을 다 어떻게 하지...?"}]},{"id":"leather_02","i":2,"title":"예언서에 나온 예언","req":"leather:2","reward":{"k":"tokens","id":"tokens","q":5,"n":"행운의 토큰"},"side":false,"lines":[{"a":"leather","t":"...그렇게 내 머리를 때린 거야, 친구. 여기 작은 혹이 생겼어."},{"a":"mana","t":"듣고 있지만 도와줄 수는 없습니다."},{"a":"mana","t":"에테르의 흐름은 신성하고 계시해 주시지만, 치유하지는 않습니다."},{"a":"leather","t":"아직 마법 쓰지? 이리 와서 마법의 손으로 만져봐, 친구."},{"a":"mana","t":"그게 아닌-"},{"a":"mana","t":"...!!!"},{"a":"mana","t":"이건... 운명...! 대단해...!"},{"a":"leather","t":"확실히 효과가 있는 거야, 친구? 난 아직 좀 어지러운데."},{"a":"mana","t":"...미안합니다. 명상이 필요한 새로운 비전이 보였어요."},{"a":"mana","t":"당신의 상처는... 여신의 총애를 받는 사람을 찾으십시오. 저는 즉시 출발해야 합니다."},{"a":"leather","t":"멋지네 친구. 요즘 몸 상태가 좋아서 그냥 내버려 둘까 봐."}]},{"id":"leather_03","i":3,"title":"챔피언 조합","req":"leather:3","reward":{"k":"tokens","id":"tokens","q":5,"n":"행운의 토큰"},"side":false,"lines":[{"a":"argon","t":"마을에 새로운 챔피언이 나타났어."},{"a":"polonia","t":"요호호! 잘생긴 남자였으면 좋겠다!"},{"a":"leather","t":"안녕 친구들."},{"a":"polonia","t":"망할 찰거머리! 지금 장난해?"},{"a":"lilu","t":"태마스!? 너 언제..."},{"a":"leather","t":"이 챔피언 사업에 도전하기로 했어, 친구. 별로 어려워 보이지 않는데."},{"a":"argon","t":"음... 태마스, 무슨 일을 하려는지 말해주지 않을래?"},{"a":"leather","t":"몬스터를 때려눕히는 거야, 친구. 그리고 수 마일에 걸쳐 가죽 아이템을 냄새로 찾아낼 수 있지."},{"a":"polonia","t":"이봐! 도둑질은 내 몫이야! 네 일이나 해!"},{"a":"leather","t":"훔친다는 게 아니야, 친구. 사람들이 그냥 아무 데나 버려둔 거라고."},{"a":"lilu","t":"곧 여기서 재미있는 일이 벌어지겠네!"},{"a":"polonia","t":"아, 네 말이 맞을지도 몰라..."}]},{"id":"leather_04","i":4,"title":"칭송받지 못한 영웅","req":"leather:4","reward":{"k":"tokens","id":"tokens","q":5,"n":"행운의 토큰"},"side":false,"lines":[{"a":"sia","t":"폐하, 특이한 보고가 하나 있습니다."},{"a":"king","t":"늘 그렇듯 듣고 있다! 계속해!"},{"a":"sia","t":"영웅들과 캐러밴들이 길이 그 어느 때보다 안전하다고 보고했습니다."},{"a":"sia","t":"몬스터들은 거의 나타나지 않고, 심지어 누굴 공격하는 것조차 너무 두려워하는 것처럼 보입니다."},{"a":"king","t":"좋은 소식이군!"},{"a":"sia","t":"그런데 이 이상한 행동의 원인을 전혀 알 수가 없습니다."},{"a":"sia","t":"마찬가지로 이상한 것은 가죽 제품 시장이 갑작스럽게 붕괴된 것입니다..."},{"a":"king","t":"분명 우연의 일치일 것이다! 이 좋은 소식을 축하하고 즐기자고!"},{"a":"sia","t":"어쩌면, 폐하... 어쩌면 그럴지도 모르죠."}]}]},{"id":"polonia","name":"폴로니아","chapters":[{"id":"polonia_01","i":1,"title":"탁월한 풋내기 선원","req":"polonia:1","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"polonia","t":"요호호! 풋내기들!"},{"a":"polonia","t":"사나운 바다 위 해적들의 용맹한 활극을 꿈꾼 적 있나?"},{"a":"polonia","t":"나 폴로니아 델 몬테 선장이, 내 배에 오를 선원을 모집하고 있지!"},{"a":"polonia","t":"전설적인 해적 바로스 델 몬테의 후손으로서 온갖 전리품과 모험을 약속하네!"},{"a":"argon","t":"폴로니아 선장님이라고 하셨죠?"},{"a":"polonia","t":"그렇다네. 흥미 있나? 자네 같은 튼튼한 종마라면 환영이야."},{"a":"argon","t":"조, 종마요!?"},{"a":"argon","t":"흐흠, 별로 관심 없습니다! 제 이름은 아르곤, 훈련 중인 기사입니다!"},{"a":"argon","t":"해적질은 불법이므로... 부디 투항하고 얌전히 따라와 주시죠!"},{"a":"polonia","t":"제기랄! 빌어먹을 기사라니..."},{"a":"polonia","t":"어, 이보게, 난 합법적인 해적이야. 그 누구냐... 로빈 후드란 녀석처럼 말야."},{"a":"polonia","t":"...난 부자들에게서 훔친 걸 가난뱅이들에게 준다고!"},{"a":"argon","t":"오! 그건 오히려 고결한 행동인 것 같군요. 좋습니다, 가세요!"},{"a":"polonia","t":"...휴우."},{"a":"tavern","t":"오늘도 재수가 별로인가 보군, 안 그런가?"},{"a":"polonia","t":"음, 험난한 바다에서 살아가는 건 고달프지."}]},{"id":"polonia_02","i":2,"title":"델 몬테의 이야기","req":"polonia:2","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"tavern","t":"오늘은 선원 모집이 끝난 모양이지, 폴로니아?"},{"a":"polonia","t":"아무짝에 소용이 없어. 난 실패한 해적 선장이 될 거야, 델 몬테의 이름만 짊어진 채로..."},{"a":"tavern","t":"바로스 델 몬테라는 사람... 당신의 할아버지랬던가?"},{"a":"polonia","t":"그렇다네! 전설 중의 전설이지! 현대에는 해적들이 살기 쉽지 않아..."},{"a":"polonia","t":"요즘 상선이란 상선은 죄다 대단한 마법 감지 도구를 들고 다녀서 우리 같은 해적들을 쉽게 피해가지."},{"a":"polonia","t":"하지만 바로스는 예외였어! 마법이든 뭐든, 그분은 안개 속에서 나타나 덮쳐왔지!"},{"a":"polonia","t":"값진 건 전부 뜯어내고, 쩌렁쩌렁한 웃음소리만 인장처럼 남기고 사라졌어..."},{"a":"polonia","t":"다른 해적들이 모두 은퇴한 뒤에도 몇십 년 동안이나 바다를 호령하셨다네!"},{"a":"tavern","t":"마땅히 따를 만한 유산이지!"},{"a":"polonia","t":"그래! 그리고 항해가 끝날 때마다 그분은 언제나 손녀딸에게 찾아와 온갖 모험담을 들려주셨어..."},{"a":"polonia","t":"해적기를 올려라! 대포 발사! 우편, 약탈 준비!"},{"a":"tavern","t":"우편? 우현 아닌가?"},{"a":"polonia","t":"...하! 젠장! 난 그저 그럴듯하게 차려입고 해적처럼 말하려고 애쓰는 풋내기 선원일 뿐이야."},{"a":"polonia","t":"애초에 배 없는 해적이란 게 말이나 돼!?"},{"a":"tavern","t":"배가 없다고? 거기서부터 시작하는 건 어때."},{"a":"polonia","t":"어?"},{"a":"tavern","t":"배가 없는 선장이 선원을 금방 모을 수는 없어!"},{"a":"tavern","t":"하지만 배가 필요한 문제라면, 내가 소개해줄 만한 녀석이 있지."},{"a":"polonia","t":"...정말?"},{"a":"polonia","t":"맙소사, 해적기에 대고 감사를 표하네, 여관 주인! 폴로니아 선장이 빚을 졌어!"},{"a":"tavern","t":"그럼 그럼, 이자까지 쳐서 돌려주라고."}]},{"id":"polonia_03","i":3,"title":"완벽한 조선공","req":"polonia:3","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"carpenter","t":"배 한 척을 통째로 만들어 내라고!?"},{"a":"polonia","t":"그래. 할 수 있나?"},{"a":"carpenter","t":"두말하면 잔소리지! 이번 작업은 나의 대작이 될 거야! 도면을 한 번 볼까."},{"a":"carpenter","t":"흠... 제법 정교한걸. 이 낙서는 뭐지?"},{"a":"polonia","t":"내가 쓴 거야. 난 글을 읽을 줄 몰라."},{"a":"carpenter","t":"아, 그렇다면 어느 정도 이해가 되네. 그래도 이 도면이면 충분하고도 남겠어."},{"a":"polonia","t":"요호호! 바로스와 보나벤투라 이후로 이쪽 바다에서는 최고의 함선이 될 거야!"},{"a":"carpenter","t":"그렇지만 자금 문제가 있어. 정말 배를 건조할 만한 여유가 있는 거야?"},{"a":"polonia","t":"그래, 금화 걱정은 필요 없어. 배만 제작하면 전리품을 잔뜩 가져다주지."}]},{"id":"polonia_a","i":3,"title":"어엿한 해적 되기","req":"polonia:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"행운의 토큰"},"side":true,"lines":[{"a":"polonia","t":"어어이, 예쁜 여성분. 당신이 치유사지, 안 그런가?"},{"a":"priest","t":"아, 맞아요! 저는 이 신전의 사제, 프레이야-"},{"a":"polonia","t":"내 다리를 자르게."},{"a":"priest","t":"네?"},{"a":"polonia","t":"내 다리를 잘라 달라고 했네!"},{"a":"priest","t":"하느님 맙소사, 안 돼요! 도대체 왜 그런 걸 부탁하시는 거예요?"},{"a":"polonia","t":"나는 해적일세! 무슨 놈의 해적이 의족 하나 없단 말인가!?"},{"a":"polonia","t":"후딱 내 다리를 잘라버리고 멋진 마법으로 치료해 주게!"},{"a":"priest","t":"절대 안 돼요. 저는 여신님께 결코 사람을 다치게 하지 않겠다고 맹세한 몸이에요."},{"a":"polonia","t":"으, 쓸모없는 풋내기 같으니! 좋아! 대신 내 금화는 한 푼도 줄 수 없어!"},{"a":"priest","t":"...희한한 사람이네."}]},{"id":"polonia_04","i":4,"title":"선장의 몫","req":"polonia:4","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"polonia","t":"핫, 이 예티들은 장물이 넘쳐나잖아! 배 제작비를 순식간에 갚을 수 있겠어!"},{"a":"leather","t":"좋아, 형씨. 내가 왔다. 뭘 하면 되지?"},{"a":"polonia","t":"폴로니아 선장이라고 불러라, 수병!"},{"a":"leather","t":"알았다고, 선장 형씨. 내가 뭘 해주길 바라시나?"},{"a":"polonia","t":"수레를 가져와. 내가 예티들을 털어먹는 사이 전리품을 실으라구."},{"a":"leather","t":"와우, 선장 형씨, 이 복슬복슬하고 예쁜 녀석들한테서 훔치려는 거야?"},{"a":"polonia","t":"그렇다. 왠지는 몰라도 이 녀석들은 워해머나 컴파운드 활처럼 값나가는 것들을 잔뜩 가지고 있어."},{"a":"leather","t":"가죽은 어떡할 거야, 선장 형씨? 내가 가져도 돼?"},{"a":"polonia","t":"감히 무슨 말인가, 수병! 해적은 약탈할 뿐이지, 죽이진 않는다고!"},{"a":"leather","t":"아, 헛수고잖아."},{"a":"polonia","t":"그렇지 않다. 녀석들을 살려두면 나중에 털 수 있는 전리품을 더 모아오지. 경제의 기본이야!"},{"a":"polonia","t":"이제 자네 몫을 원한다면 후딱후딱 움직이게, 수병!"},{"a":"leather","t":"예예, 선장 형씨."}]},{"id":"polonia_05","i":5,"title":"처녀 항해","req":"polonia:5","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"carpenter","t":"보시게, 내 인생의 역작이 탄생했어!"},{"a":"polonia","t":"오... 아름다워. 이 오랜 뱃사람의 눈에 눈물이 고이는군."},{"a":"carpenter","t":"그렇지? 약간 수정해야 했던 부분이 있긴 한데, 말하자면 당신이 묘하게 집착하던 돛대 꼭대기의 대포라든지..."},{"a":"carpenter","t":"그래도 상상 이상으로 멋지게 되었지, 안 그런가?"},{"a":"polonia","t":"정말 그렇네, 친구. 여기 금화를 받게. 마땅히 받을 자격이 있어."},{"a":"carpenter","t":"물론이지! 한 가지 마지막으로 덧붙일 게 있는데. 나는 도목수지만 천이나 직물과는 거리가 멀어."},{"a":"carpenter","t":"... 그리고 돛이 없으면, 당신 배는 빠른 시일 내에 항구를 떠나진 못할 거야!"},{"a":"polonia","t":"친구, 자네는 이미 이 선장님을 기쁘게 했네. 돛은 내가 여기 가지고 있어."},{"a":"carpenter","t":"와! 예술 작품이로군! 환상적이야! 어디서 구한 건가?"},{"a":"polonia","t":"바로스 할아버지가 물려준 가보라네. 할아버지의 배, 바로 보나벤투라의 꼭대기에 달려 있던 바로 그 돛이지!"},{"a":"carpenter","t":"그렇군! 이 선박의 훌륭한 화룡점정이 되겠어!"},{"a":"carpenter","t":"좋아, 폴로니아 선장, 아름다운 앨런은 자네 거야!"},{"a":"polonia","t":"이 배 이름을 아름다운 앨런이라고 지은 건가? 잠깐만..."},{"a":"polonia","t":"저 선수상... 당신이야!? 거기다 알몸뚱이잖아!"},{"a":"carpenter","t":"하하! 이 완벽한 배에 이보다 더 나은 선수상을 생각할 순 없었지!"}]},{"id":"polonia_b","i":5,"title":"달아나!","req":"polonia:5","reward":{"k":"tokens","id":"tokens","q":3,"n":"행운의 토큰"},"side":true,"lines":[{"a":"polonia","t":"어어이, 거기 친구."},{"a":"wood","t":"응?"},{"a":"polonia","t":"내 다리를 자르게."},{"a":"wood","t":"그래."},{"a":"polonia","t":"내 말은- 잠깐, 괜찮다고?"},{"a":"wood","t":"물론이지. 이렇게 다리를 잘 붙잡고 있어 봐. 이 노련한 도끼면 충분할 거야."},{"a":"polonia","t":"어어, 잠깐만!"},{"a":"wood","t":"예쁘게 해주진 못하지만, 그런 것쯤은 상관없겠지. 안 그래?"},{"a":"wood","t":"지혈대만 잘 대고 있도록 해. 피를 줄줄 흘리는 걸 보고 싶진 않거든, 자."},{"a":"polonia","t":"정지! 친구! 잠깐 기다리게!"},{"a":"polonia","t":"난- 내 배가 곧 출항해야 해! 어, 얼른 가야겠군! 또 보자고, 친구!"},{"a":"wood","t":"...하! 인간들이란. 지루할 새가 없군."}]},{"id":"polonia_06","i":6,"title":"바다의 유산","req":"polonia:6","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"sia","t":"폐하, 끔찍한 소식입니다."},{"a":"king","t":"안 돼! 사라진 황금의 도시에 황금이 다 떨어지기라도 했단 말이냐!?"},{"a":"sia","t":"다행히 그 정도로 끔찍하진 않습니다."},{"a":"sia","t":"하지만 해적들이 폐하의 개인 상단을 약탈했다는 것 같습니다."},{"a":"sia","t":"...예상하기로 황금을 100조 넘게 빼앗겼다고 합니다."},{"a":"king","t":"맙소사! 상단의 첨단 마법 해적 탐지기는 어떻게 하고?"},{"a":"sia","t":"전혀 먹히지 않았습니다. 위대한 바로스가 그랬던 것처럼 해적선도 우리의 최고 마법을 교묘히 빠져나간 것 같습니다..."},{"a":"sia","t":"...폐하의 황금을 모조리 약탈하고 유유히 바다 멀리 빠져나갔다고 합니다."},{"a":"king","t":"이런 야만적인 놈들 같으니! 선원들은 무사한가?"},{"a":"sia","t":"무사합니다, 폐하. 저항할 틈도 없었던 것 같습니다."},{"a":"king","t":"황금은 작은 희생일 뿐이다. 피해를 복구할 때까지는 농부들과 똑같은 식사를 해야겠구나!"},{"a":"king","t":"...얼마나 걸리겠느냐?"},{"a":"sia","t":"2일 정도입니다, 폐하."},{"a":"king","t":"정말 암흑기구나..."}]},{"id":"polonia_07","i":7,"title":"상륙 허가","req":"polonia:7","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"polonia","t":"요호호! 폴로니아 선장이 상륙한다! 나를 따르라!"},{"a":"tavern","t":"폴로니아! 아... 폴로니아 선장이라고 해야 하나! \"사업\"이 잘 풀리는 모양인데?"},{"a":"polonia","t":"그럼, 보아하니 자네의 육지 사업은 바닥을 치는군! 바다는 털어먹기 딱 좋은데 말이야!"},{"a":"polonia","t":"어디로 배를 몰든 할아버지의 돛은 귀신 같이 바람을 탄단 말이야!"},{"a":"tavern","t":"바로스도 자랑스러워 하겠군. 그런데 이... 약탈한 물건들은 어떻게 쓸 생각인가?"},{"a":"polonia","t":"착한 해적처럼 써야지. 이곳 저곳에 나랑 같이 묻어버리는 거야."},{"a":"tavern","t":"오오! 보물지도! 멋진 생각인데!"},{"a":"polonia","t":"그래, 그게 해적이지. 추운 겨울에 대비해서 자네도 좀 챙기게, 육지에 사는 다람쥐처럼 말이야."},{"a":"tavern","t":"나머지는 어쩌고?"},{"a":"polonia","t":"사원에 있는 예쁜 여인에게 줘버렸어."},{"a":"tavern","t":"고아원에 기부했단 말인가? 자선가인 줄은 또 몰랐군."},{"a":"polonia","t":"고아원에 뭐?"},{"a":"tavern","t":"아, 신경 쓰지 말게. 그럼, 뭘 드릴까요, 선장님?"},{"a":"polonia","t":"늘 마시던 거, 노련한 뱃사공의 물약! 이걸 마실 수 있는 뭍사람에게도..."},{"a":"polonia","t":"다음은 내가 사지! 바로스 패밀리가 바다로 돌아왔다! 요호호!"}]},{"id":"polonia_08","i":8,"title":"과거의 속삭임","req":"polonia:8","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"polonia","t":"인어 친구, 또 물에 뛰어들 준비 됐어?"},{"a":"baker","t":"얼마든지요! 아, 이 말씀은 꼭 드려야겠군요..."},{"a":"baker","t":"수중 탐사는 얼마든지 할 수 있지만... 계약에 해적질까지 포함된 건 아닌데요!"},{"a":"polonia","t":"걱정 말게, 친구. 우린 항해도를 만드는 중이니까. 자네 선장은 지금 영토를 넓히는 중이야."},{"a":"polonia","t":"오늘은 해적질할 일 없을 거야. 뭐, 운이 좋으면 가라앉은 배를 만나 약탈할 수도 있지만! 요호호!"},{"a":"baker","t":"어, 선장님? 저 수평선 위에 나타난 배는 뭐죠?"},{"a":"polonia","t":"아르르... 꼬리 진정시키게. 보나벤투라 호잖아! 근데... 우리 할아버지 배인데."},{"a":"baker","t":"확실해요? 그냥 낡은 배 같은데..."},{"a":"polonia","t":"...말이 안 돼! 지, 진짜 보나벤투라인가! 이, 이럴 수는 없어! 할아버지는 오래전에 돌아가셨는데!"},{"a":"polonia","t":"자, 친구들! 계획을 바꾸자! 저 배를 미행한다!"}]},{"id":"polonia_09","i":9,"title":"표류하는 전설","req":"polonia:9","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"baker","t":"...설마 내 인생에 버려진 배를 타게 될 줄이야."},{"a":"polonia","t":"발 조심해, 인어. 이 배 상태가 안 좋아."},{"a":"baker","t":"차라리 바다에 빠지는 게 더 낫겠어요! 대체 이 배에 탄 이유가 뭐죠?"},{"a":"polonia","t":"이유가 뭐냐니? 바로스 할아버지의 보나벤투라 호잖아!"},{"a":"polonia","t":"여기서 무슨 일이 있었는지 알아야겠어. 버려진 배가 떠다닐 리가 없는데..."},{"a":"baker","t":"배라 하긴 좀 그렇고... 유령선에 가깝죠."},{"a":"polonia","t":"아, 그런 식으로 겁주지 마! 유령 같은 건 없어!"},{"a":"baker","t":"그럼 그..."},{"a":"polonia","t":"마, 말 그만하고 아가미 좀 닫아. 단서 찾느라 바쁘니까."},{"a":"baker","t":"저기 있는 일지가 좀 섬뜩해 보이는데..."},{"a":"polonia","t":"아, 선장의 일지군!"},{"a":"baker","t":"근데... 일지가 선장님을 보는 거 같지 않아요?"},{"a":"polonia","t":"같이 가자, 일지야. 자네도 해적 눈을 부릅뜨고 다른 게 없는지 찾아봐."},{"a":"polonia","t":"...내 머리 그만 좀 만지지?"},{"a":"baker","t":"선장님, 저 여기 있어요."},{"a":"polonia","t":".....으갸갸갸갹! 배를 버려라!"}]},{"id":"polonia_10","i":10,"title":"해적의 유산","req":"polonia:10","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"polonia","t":"선장이 돌아왔다, 얘들아. 돛을 올리고 출항하자."},{"a":"baker","t":"선장님! 보나벤투라 호가 가라앉고 있어요!"},{"a":"polonia","t":"세상에! 어떻게 이런 일이... 시간은 또 왜 이렇게 지났어!? 일지는... 그 오랜 세월 동안 떠다니고 있었던 건가?"},{"a":"baker","t":"...배가 목적을 달성한 걸지도요."},{"a":"polonia","t":"바로스, 바다의 사나이여... 이런 건 대체 어떻게 아시고..."},{"a":"baker","t":"폴로니아, 일지 읽어보는 건 어때요?"},{"a":"polonia","t":"그렇지. 어디 보자..."},{"a":"polonia","t":"..............."},{"a":"polonia","t":"인어 친구, 부탁이 하나 더 있어."},{"a":"baker","t":"아, 그래요. 제가 읽어드리죠."},{"a":"baker","t":"흠... 물속에서 뭔가를 찾으라는 것 같네요."},{"a":"polonia","t":"가라앉은 사원? 그건 진작 알려진 얘긴데."},{"a":"baker","t":"아니요, 거기서 좀 더 멀리... 사라진 황금의 도시를 언급하네요?"},{"a":"baker","t":"사라진 황금의 도시는 물속에 있지 않은데..."},{"a":"polonia","t":"단순한 이야기가 아니었어? 그런 데가 진짜 있다고?"},{"a":"polonia","t":"인어 친구, 자넨 헤엄칠 수 있잖아. 이건 운명이야."},{"a":"polonia","t":"이 이야기가 사실이라면... 자넬 데려오길 잘했군."}]},{"id":"polonia_11","i":11,"title":"가라앉은 황금의 도시","req":"polonia:11","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"baker","t":"휴! 다 왔어요! 좀 어떠세요, 선장님?"},{"a":"polonia","t":"콜록, 콜록. 으으..."},{"a":"polonia","t":"에취... 너도 다리가 꽤 튼튼하구나. 인어치고는..."},{"a":"baker","t":"오히려 잘됐네요. 입구 자체가 엄청 깊은 곳에 있어요. 인간이 오진 못할 겁니다."},{"a":"polonia","t":"맞아! 하마터면 죽을 뻔했지. 두 번 다신 안 올 거야..."},{"a":"baker","t":"세상에... 폴로니아, 주변을 좀 둘러보세요!"},{"a":"polonia","t":"이럴 수가... 가라앉은 황금의 도시잖아..."},{"a":"polonia","t":"여긴... 이런 건 처음 봐..."},{"a":"baker","t":"보물이 흘러넘치네요! 황금, 진주... 사라진 황금의 도시가 시시해 보일 정도예요!"},{"a":"polonia","t":"할아버진 평생 이곳을 찾아 헤매셨지..."},{"a":"baker","t":"하지만 결국 아무것도 육지로 가져갈 수가 없어서, 사랑하는 손녀를 위해 전부 남겨두시기로 한 거네요."},{"a":"polonia","t":"훌쩍... 왜 눈에서 물이 흐르는 건지..."},{"a":"baker","t":"선장님, 잠깐만요."},{"a":"polonia","t":"왜 그래? 약탈할 전리품이 널렸잖아! 그래서 방금 자넬 일등 항해사로 승진시켰다네. 수영할 준비 됐나?"},{"a":"baker","t":"뭐야, 보물도 담고 해적질도 하라고요? 후, 그럼 스트레칭 좀 할게요!"}]},{"id":"polonia_epilogue","i":12,"title":"에필로그","req":"polonia:11","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"polonia","t":"흠..."},{"a":"baker","t":"폴로니아 선장님, 또 수영할 준비하시는 건가요?"},{"a":"polonia","t":"아니라네. 지금 큰 문제가 생겼어."},{"a":"polonia","t":"돈이이 너무 많아졌어! 해변에 하도 파묻어서 더 묻을 자리가 없을 지경이야."},{"a":"baker","t":"제가 받은 몫만 해도 감당하기 힘들 정도로 벅차긴 하죠!"},{"a":"baker","t":"아, 그러고 보니...!"},{"a":"baker","t":"아까 침몰한 보나벤투라 호를 한 바퀴 쭉 돌고 왔습니다만..."},{"a":"baker","t":"별다른 건 없었고 이 안대만 있었어요. 무슨 물건인지 알아보시겠어요?"},{"a":"polonia","t":"오오, 일등 항해사! 바로스 할아버지의 안대잖아!"},{"a":"polonia","t":"요호호! 뽀뽀라도 해주고 싶을 지경이군!"},{"a":"baker","t":"오히려 제가 영광입니다. 바로스 씨도 안대를 찾길 원하셨을 거예요."},{"a":"polonia","t":"...음, 그건 그렇고 이제 해저 보물 사냥도 그만둬야겠어."},{"a":"polonia","t":"바다는 황금의 도시가 아니라 해적의 고향이란 말이야! 이제 억만금을 줘도 보물찾기는 그만할래."},{"a":"polonia","t":"위대한 바로스의 손녀로서 말하건대, 자네에게 가라앉은 황금의 도시와 남은 보물을 전부 물려주겠네."},{"a":"polonia","t":"그동안 수고 많았어, 일등 항해사. 해적질이 그리워지면 언제든 돌아오도록."},{"a":"baker","t":"감사합니다, 선장님. 우리가 함께 떠난 모험을 평생 기억할게요!"},{"a":"baker","t":"...이제 투투 마노랑 어떻게 하면 휴가 마치고 집에 돌아갈 수 있는지 얘기해 봐야겠어요."}]}]},{"id":"hemma","name":"헴마","chapters":[{"id":"hemma_01","i":1,"title":"희미한 그림자","req":"hemma:1","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"hemma","t":"...그렇게 트러블린은 쓰러졌습니다. 내 친구들의 타격을 맞은 후였죠."},{"a":"hemma","t":"반드시 치유해주세요."},{"a":"priest","t":"물론이죠. 최대한 빨리 상처를 돌볼게요."},{"a":"lilu","t":"안녕하세요! 마을에 새로운 주문술사가 있다고 들었습니다."},{"a":"lilu","t":"전 릴루예요! 만나서 반가워요!"},{"a":"hemma","t":"그래요, 어린 릴루. 우리 이름은 헴마입니다. "},{"a":"lilu","t":"...\"우리\"요?"},{"a":"hemma","t":"...네. 강령술은 견습자에게 대가를 치르게 하거든요..."},{"a":"hemma","t":"일부는 베일 너머에 머물고 나머지는 문턱을 넘죠..."},{"a":"hemma","t":"이 힘이... 우리를 바꿔놓았어요. 물론 최선의 방향으로요."},{"a":"lilu","t":"강령술이라고 하셨나요!? 그건... 위험하지 않나요?"},{"a":"hemma","t":"정말 위험하죠. 하지만 우린 단순한 기술에 더는 만족할 수 없어요."},{"a":"hemma","t":"자, 실례지만 이제 다른 곳에 가야 해서요. 안녕히 계십시오."},{"a":"lilu","t":"강령술사라... 저건 흑마법일 텐데, 폴럭스! 하지만 견습자를 본 건 처음이야!"},{"a":"lilu","t":"나쁜 사람 같지는 않았어... 그렇지?"}]},{"id":"hemma_02","i":2,"title":"무슨 일이 있어도","req":"hemma:2","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"elderowen","t":"강령술사라...?"},{"a":"elderowen","t":"이걸 어떻게 생각해야 할지 모르겠군요..."},{"a":"hemma","t":"걱정하는 것도 당연해요. 강령술은 미약한 존재를 소멸시킬 수 있는 위험한 기술이니까요..."},{"a":"hemma","t":"하지만 우린 어떻게 봐도 미약한 존재가 아니잖아요."},{"a":"elderowen","t":"당신과 함께 가는 모험가들은요? 자신의 주문을 강력하게 만들기 위해 그들을 흡수하지는 않나요?"},{"a":"hemma","t":"모험가들이 동의할 때만요. 효과가 영구하진 않거든요."},{"a":"hemma","t":"그리고 우린 그에 대한 대가를 후하게 치른답니다."},{"a":"elderowen","t":"어쨌든 좋은 일을 하는 것 같군요..."},{"a":"elderowen","t":"좋습니다. 당신을 이 도시의 챔피언으로 허가할 수 있을 것 같네요."},{"a":"hemma","t":"당신의 허가가 필요한 건 아니지만... 어쨌든 고마워요."},{"a":"elderowen","t":"이 도시에는 무슨 일로 온 겁니까?"},{"a":"hemma","t":"..."},{"a":"hemma","t":"우린 그저 지식과 전투력을 추구해요. "},{"a":"hemma","t":"반드시 완수해야 하는... 임무가 있어요."},{"a":"elderowen","t":"정말 모호한 대답이군요..."},{"a":"hemma","t":"계속 그럴 겁니다. 그럼 이만."},{"a":"elderowen","t":"..."},{"a":"elderowen","t":"아주 슬픔이 많은 눈빛이었어..."}]},{"id":"hemma_03","i":3,"title":"잠재된 적수","req":"hemma:3","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"herbalist","t":"...설익은 살아있는 뿌리, 그리고 바삭바삭한 섬뜩한 심령 추가. 더 필요한 건?"},{"a":"hemma","t":"그거면 되겠군요. 나머지는 상인에게 방문해야 합니다."},{"a":"herbalist","t":"고맙습니다, 또 와요!"},{"a":"hemma","t":"<c4>...음침한 발도 잊지 마세요.</c4>"},{"a":"hemma","t":"아, 그렇죠. 음침한 발 한 쌍도 부탁해요."},{"a":"herbalist","t":"...방금 그건 뭐였죠?"},{"a":"hemma","t":"신경쓰지 마세요. 그냥 지나가던 사람입니다."},{"a":"hemma","t":"<c4>내보내 줘, 내보내 줘, 내보내 줘, 내보내 줘.</c4>"},{"a":"hemma","t":"어. 좀 진정해 주실래요?"},{"a":"hemma","t":"잔돈은 가지셔도 됩니다. 그럼 안녕히."},{"a":"herbalist","t":"...잔돈 고맙군요... 악몽까지 덤으로 주셨네요."}]},{"id":"hemma_a","i":3,"title":"불멸자들","req":"hemma:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"행운의 토큰"},"side":true,"lines":[{"a":"donovan","t":"설익은 살아있는 뿌리? 흥미로운 선택이로군."},{"a":"hemma","t":"뭐가?"},{"a":"donovan","t":"살아있는 뿌리는 젊음과 수명에 관한 마법들에 많이 사용되는 재료니까."},{"a":"donovan","t":"너도 나와 같은 연금술사인가? 혹시 수명 연장을 위한 연구를 하고 있어?"},{"a":"hemma","t":"...숙녀에게 나이에 관해 물어보는 건가? 아주... 부적절하네."},{"a":"hemma","t":"우린 연금술사가 아니야. 피의 희생이 훨씬 더 효율적이라고."},{"a":"donovan","t":"아, 강령술사라! 존중 대신 오해를 더 많이 받는 분야지."},{"a":"hemma","t":"우린... 꽤 오래전부터 나이 계산하는 걸 그만뒀어."},{"a":"donovan","t":"공감할 수밖에 없군. 몇 세기를 살아보면 그다음부터 수십 년은 금방 지나가는 것처럼 느껴지니까!"},{"a":"donovan","t":"이 하루살이들 사이에서 살다 보면 외로워지더라, 너도 그렇지?"},{"a":"hemma","t":"우린 외롭진 않아. 너도 강령술사의 일을 꼬치꼬치 캐묻지만 않으면 잘 살 수 있을 거야."},{"a":"donovan","t":"물론, 그럴 의도는 아니었어. 그럼 이만!"},{"a":"donovan","t":"이상한 강령술사네... 만난 적이 있던가?"},{"a":"donovan","t":"...설마 페어린?"}]},{"id":"hemma_04","i":4,"title":"퇴마","req":"hemma:4","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"lilu","t":"걱정하지 마, 헴마! 내가 프레이야를 데리고 왔어!"},{"a":"priest","t":"이름이 헴마라고? 몸을 편안히 하고, 퇴마의식을 받아들여..."},{"a":"hemma","t":"우린 도움을 요청한 적이 없는데 말이지."},{"a":"hemma","t":"<c4>저리 가라, 꼬마야. 난 이 몸을 떠나지 않을 거니까.</c4>"},{"a":"lilu","t":"아아! 빙의되고 있어! 빨리, 프레이야!"},{"a":"priest","t":"안... 돼! 뭔가가 내 기도를 막고 있어..."},{"a":"hemma","t":"우리가 막고 있는 거다. 그만해라."},{"a":"priest","t":"너 지금... 원해서 이 악령을 받아들인 거야?"},{"a":"hemma","t":"시간이 지나니까 좀 정신이 나가긴 하더라."},{"a":"hemma","t":"<c4>여기서 피해자는 바로 나야! 날 내보내 줘!</c4>"},{"a":"hemma","t":"으, 정말. 악령보다 무례하다니까."},{"a":"hemma","t":"이건 너랑 상관없는 문제야. 끼어들지 마, 프레이야."},{"a":"priest","t":"강령술사들은... 항상 자기가 이해하지 못하는 힘을 남용하지!"},{"a":"lilu","t":"괜찮아, 프레이야! 헴마도 자기가 무슨 일을 하고 있는지 알고 있을 거야!"},{"a":"lilu","t":"...맞지?"}]},{"id":"hemma_05","i":5,"title":"두 개의 의식","req":"hemma:5","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"hemma","t":"<c4>사실이 발각된 모양이네. 이제 여길 뜰까?</c4>"},{"a":"hemma","t":"다 너 때문이야. 너만 조용히 했으면 훨씬 더 순조로웠을 텐데."},{"a":"hemma","t":"어쨌든 이 마을을 뜨진 않을 거야. 가능성이 많은 곳이라고."},{"a":"hemma","t":"<c4>좋아. 근데 나 좀 내보내 주면 안 돼?</c4>"},{"a":"hemma","t":"절~대 안 되지. 지금도 이렇게 통제하기가 힘든데."},{"a":"hemma","t":"<c4>내보내 줘, 내보내 줘, 내보내 줘, 내보내 줘.</c4>"},{"a":"hemma","t":"다 널 위해서 그러는 거야, 클라우드."},{"a":"hemma","t":"...명심하라고."}]},{"id":"hemma_06","i":6,"title":"거짓말의 유산","req":"hemma:6","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"lilu","t":"페어린!"},{"a":"hemma","t":"응?"},{"a":"lilu","t":"이럴 줄 알았어! 헴마라는 이름은 가짜지! 괴물은 너였어, 페어린!"},{"a":"hemma","t":"이거 이거, 교활하신 꼬마 사기꾼 아니야."},{"a":"hemma","t":"맞아. 보아하니 조사를 제대로 한 것 같군."},{"a":"hemma","t":"그렇다면 미치광이 아리엘에 대해서도 들어봤겠네? 아니면 타락한 아스트리드라든가?"},{"a":"lilu","t":"... 읽어본 적은 있어... 하지만 그들은 수십 년 전에 사라졌다고! 그럴 리가..."},{"a":"hemma","t":"우리 모두가 사라졌지, 맞아. 불행히도 우리는 많은 박해를 받으니 이름 따위는 버려야 하지..."},{"a":"lilu","t":"넌 괴물이야! 가만두지 않을 거야!"},{"a":"hemma","t":"가만두지 않으면 어쩔 건데? \"헴마\"는 죄 없는 착한 사람인데. 네 헛소리를 누가 믿어줄까?"},{"a":"hemma","t":"물론, 너 혼자서 덤빈다면 얘기는 달라지겠지만..."},{"a":"lilu","t":"...쳇!"}]},{"id":"hemma_07","i":7,"title":"영혼 결합","req":"hemma:7","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"hemma","t":"아직도 몰래 숨어있는 거야?"},{"a":"lilu","t":"널 감시하는 거야. 너랑 네가 중얼거리는 말들이 수상하니까..."},{"a":"hemma","t":"아, 인사해. 우리 남편 클라우드야. 한때는 잘 나갔었는데."},{"a":"hemma","t":"<c4>날 내보내 줘!</c4>"},{"a":"lilu","t":"...그에게 무슨 일이 있었던 거야?"},{"a":"hemma","t":"끔찍한 강령술 사고였지. 어리석은 실수로 죽을 뻔했어."},{"a":"hemma","t":"우리 강령술사들이 이 땅에서 지은 죄를 생각하면, 우리의 사후 세계는 분명 끔찍할 거란 말이지..."},{"a":"hemma","t":"그의 육체를 살릴 수 없었으니, 방법은 하나였어... 영혼을 살린 거야."},{"a":"lilu","t":"영혼 결합이라고? 그 주문에 필요한 알맞은 그릇을 준비하려면 수년의 연구가 필요할 텐데..."},{"a":"hemma","t":"네 말이 맞아. 상황이 상황이니만큼 급한 대로 처리했지."},{"a":"lilu","t":"처리했다니? 설마... 클라우드의 영혼을 너에게 결속시켰다는 거야!?"},{"a":"lilu","t":"하나의 육체에 영혼을 두 개나 담을 수는 없어! 그렇게 하면..."},{"a":"hemma","t":"엄청난 고통. 실성. 네가 상상하는 것보다 끔찍한 일들이 일어나."},{"a":"lilu","t":"헴마... 대체 왜...? 어째서...?"},{"a":"hemma","t":"간단해, 릴루. 실패는... 용납되지 않으니까."}]},{"id":"hemma_08","i":8,"title":"세기의 현상금","req":"hemma:8","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"lilu","t":"퇴마 의식을 하기엔 너무 강력해... 아니면 영혼을 다른 곳에 결속시킨다면...?"},{"a":"hemma","t":"굉장히 협조적이네. 강령술에 흥미라도 생긴 거야?"},{"a":"lilu","t":"아니! 난 너도 싫고 네가 한 일도 다 싫어!"},{"a":"lilu","t":"...내 생각에 만약 그 클라우드라는 남자가 밖으로 나온다면 모두가 곤란해질 거야."},{"a":"lilu","t":"이 상황을 해결하는 걸 도와주는 것뿐이야!"},{"a":"hemma","t":"고상하기도 해라. 하지만 어린아이에 불과한 네가 도움을 줄 수 있을까?"},{"a":"lilu","t":"제대로 된 그릇을 준비하는 데에는 수십 년의 시간과 재료들이 필요해..."},{"a":"hemma","t":"그건 문제없어. 봐."},{"a":"lilu","t":"...! 이것들을 다 어떻게 구한 거야...? 블랙 다이아몬드까지!"},{"a":"hemma","t":"지난 수십 년을 허투루 보내지 않은 거지. 우리에게 남은 시간은 얼마 없으니까."},{"a":"hemma","t":"이제 남은 건 의식에 적합한 장소를 찾는 건데, 마땅한 곳이 없는 것 같아."},{"a":"lilu","t":"그렇지. 영혼이 애착을 가지고 있는 장소여야 해. 그렇지 않으면 결속은 실패할 거야."},{"a":"hemma","t":"<c4>아니면 이 클라우드 파비우스 님을 풀어주던가! 친구도 많이 사귈 거야!</c4>"},{"a":"lilu","t":"잠깐... 파비우스라고?"}]},{"id":"hemma_09","i":9,"title":"유령의 성","req":"hemma:9","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"hemma","t":"으스스하니 정말 유쾌한 곳이네."},{"a":"lilu","t":"끔찍한 곳이지. 정신이 제대로 박힌 사람이라면 절대 오지 않을 거야."},{"a":"lilu","t":"하지면 지금은 그게 중요한 게 아니야. 내 조사에 따르면..."},{"a":"lilu","t":"...몇백 년 전, 파비우스 가문의 어느 미치광이 왕이 이곳을 다스렸다고 해."},{"a":"lilu","t":"어쩌면 클라우드가 왕의 먼 친척인 게 아닐까? 그 왕국의 멸망과 클라우드가 아무런 연관도 없길 바라..."},{"a":"hemma","t":"...느껴져. 이곳과 우리가 연결되어 있어. 여기가 맞아."},{"a":"hemma","t":"너에게 큰 빚을 졌어, 릴루. 하지만 여기서부턴 우리가 알아서 할게."},{"a":"lilu","t":"헴마... 행운을 빌어."}]},{"id":"hemma_10","i":10,"title":"죽음이 우리를 갈라놓을 때까지","req":"hemma:10","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"hemma","t":"강령술의 기운이 넘쳐흐르는 음산하고 어두운 은밀한 장소..."},{"a":"hemma","t":"우리가 이런 장소를 얼마나 오랫동안 찾아 헤맨 걸까?"},{"a":"hemma","t":"이제 적합한 그릇을 찾자..."},{"a":"hemma","t":"말은 필요 없어. 원하는 게 뭔지 잘 알고 있으니까."},{"a":"Castle_Boss","t":"..."},{"a":"hemma","t":"...미치광이 왕의 갑옷, 이곳에 영원히 묶이게 될 거야."},{"a":"hemma","t":"<c1>영혼 결합!</c1>"},{"a":"Castle_Boss","t":"..."},{"a":"hemma","t":"윽... 우리가... 아니면 나 혼자인가...?"},{"a":"hemma","t":"이 고독이 어떤 느낌인지 잊고 있었어..."},{"a":"hemma","t":"난 널 구하기 위해 영겁의 시간을 고통받았어. 네가 나였어도 똑같이 했을 테니까."},{"a":"hemma","t":"용감한 모험가들이 반드시 올 거야. 그들과 맞서 싸워서, 고통받는 네 존재를 학살로써 치유하도록 해."},{"a":"Castle_Boss","t":"..."},{"a":"hemma","t":"잘 있어, 내 사랑. 하지만 오직 죽음만이 우리를 진정으로 갈라놓을 수 있을 거야."}]},{"id":"hemma_epilogue","i":11,"title":"에필로그","req":"hemma:11","reward":{"k":"gems","id":"gems","q":10,"n":"보석"},"side":false,"lines":[{"a":"Castle_Boss","t":"<c4>어리석기는!!! 감히 짐의 영토에 발을 들이다니?</c4>"},{"a":"sia","t":"...정말 까다로운 적이군!"},{"a":"Castle_Boss","t":"<c4>으하하하! 약해빠진 인간들 같으니라고!</c4>"},{"a":"argon","t":"레이디 시아! 루도! 퇴각해야 합니다!"},{"a":"rudo","t":"절대 안 된다! 물러설 수 없어!"},{"a":"yami","t":"출구를 찾았어. 어서!"},{"a":"rudo","t":"쳇! 반드시 돌아올 거다, 이 몸집만 큰 깡통 녀석아! 알겠나?"},{"a":"Castle_Boss","t":"<c4>실력을 쌓아서 다시 돌아오거라!</c4>"},{"a":"Castle_Boss","t":"<c4>가장 뛰어난 영웅들에게 이 독재자 왕이 기다리고 있다 전해라!</c4>"}]}]}];
